export const FLOWS={"build":{"title":"CORE One+ 組み立て","guide":"組み立てガイド","revision":"1.02","manual":"https://help.prusa3d.com/manual/prusa-core-one-kit-assembly_2321","chapters":["はじめに","ベースの組み立て","背面の組み立て","ヒートベッド","CoreXYユニット","Nextruder","外装と電子部品","ドアとxLCD","校正と初回起動"],"steps":[{"chapter":0,"officialStep":1,"officialId":982324,"chapterSteps":15,"title":"キットを準備する","description":"CORE One+組み立てキットを準備します。はんだ付けや電線の圧着は不要です。まず導入部を読み、工具と作業場所を整えてから組み立てを始めてください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982324","checks":["CORE One+組み立てキットを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/3742ce01b4fb3a75c1bccee3a05d258e-800x600.jpg","reveal":[],"add":[],"fullContext":true,"overview":true,"action":"組み立てを開始","verificationRevision":"a4d595dfe3b95f4d"},{"chapter":0,"officialStep":2,"officialId":982357,"chapterSteps":15,"title":"マニュアルの読み方","description":"手順の説明と注意事項を読み、作業後に確認項目へチェックを入れます。矢印で前後の手順へ、「工程一覧」から任意の手順へ移動できます。3D表示のままでも次へ進めます。確認を付けずに移動しても、その手順が完了扱いになることはありません。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982357","checks":["手順の移動と、作業後の確認チェックの使い方を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/40fab709d565e69bff12f8ce85a47166-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"0d4158b095a47a0f"},{"chapter":0,"officialStep":3,"officialId":982427,"chapterSteps":15,"title":"写真を大きく見る方法","description":"写真をタップまたはクリックすると、この画面内で拡大できます。写真が複数ある手順では、矢印か小さな写真を選んで切り替えてください。スマートフォンの3D画面では「手順を確認する」から説明と写真を開き、「3Dに戻る」で同じ手順へ戻れます。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982427","checks":["参考写真を大きく開く方法を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3e09e21237dcc90fdf141ca0e21ea34d-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"292977d8025d4973"},{"chapter":0,"officialStep":4,"officialId":982461,"chapterSteps":15,"title":"付属工具を確認する","description":"「Electronics & Fasteners」の工具を確認します。ラジオペンチ、PH2プラスドライバー、ユニバーサルレンチ、13–16 mmレンチ、六角レンチセット、トルクスセットが入っています。各章の最初に、その章で使うものを取り出してください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982461","checks":["付属工具の種類と保管場所を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c692bc2c05f2275b-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"802b367717d71c0e"},{"chapter":0,"officialStep":5,"officialId":982537,"chapterSteps":15,"title":"あると便利な道具","description":"防錆油を拭くペーパータオルか布と、ベアリングの袋を開けるはさみを用意します。Nextruderの遊星ギアに使う潤滑剤はキットに含まれています。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982537","checks":["拭き取り用の紙か布、はさみ、付属の潤滑剤を用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e4291ae4c4cf3a7e302adb573fa3a478-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"e796182878f1243d"},{"chapter":0,"officialStep":6,"officialId":982582,"chapterSteps":15,"title":"ラベルの見分け方","description":"袋のラベルには部品名と数量があります。ねじは章ごとではなく種類ごとの袋です。M3x10の10は頭を除く長さ10 mm、M3x8rTは長さ8 mmのトルクス頭を示します。公式の実寸早見表を使う場合は、拡大縮小せず100%で印刷してください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982582","checks":["ねじの長さと頭の種類をラベルで見分ける方法を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/880c4f7c632273f2affc6d9a49101c70-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"7412a4381b74e516"},{"chapter":0,"officialStep":7,"officialId":982634,"chapterSteps":15,"title":"予備部品の袋","description":"ねじ類の袋に書かれた総数には、予備分も含まれます。ほかの部品にも予備が1個入っている場合があります。余った数だけで取り付け忘れと判断せず、手順で指定された数量と照合してください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982634","checks":["袋の総数に予備が含まれることを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/67c7d3b48a0283caa7e3887fd9153fe7-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"0f0aafc4ebfbbb13"},{"chapter":0,"officialStep":8,"officialId":982660,"chapterSteps":15,"title":"プリント部品のリビジョン","description":"プリントパーツのE1やR1などの刻印は、製造区分やリビジョンを示します。写真と番号が違う場合も、手順内の版ごとの注意を優先してください。組み付けに問題があれば、刻印を控えてサポートへ伝えます。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982660","checks":["リビジョン刻印の見方と、手順内の版ごとの注意を優先することを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a19a0436df07587a9ad06fbc7cad2885-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"5a3e09ad9da2e119"},{"chapter":0,"officialStep":9,"officialId":982718,"chapterSteps":15,"title":"サポートの利用方法","description":"部品の不足や破損、手順で分からない点がある場合は、Prusa公式サポートを利用できます。公式手順のコメント欄、help.prusa3d.comのチャット、info@prusa3d.comが案内されています。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982718","checks":["部品や手順について相談する公式サポート窓口を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b7c6ccbca9fbe7d1-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"b0196684ae671ec7"},{"chapter":0,"officialStep":10,"officialId":982770,"chapterSteps":15,"title":"ナットを入れるコツ","description":"ナットが入りにくい場合は、全ねじのM3x10やM3x18を反対側の穴から入れ、締めながらナットを引き込み、最後にねじを外します。抜け落ちる場合はテープで仮止めし、ねじが入ったら剥がしてください。接着剤はねじ山に入ることがあるため使いません。","parts":[],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982770","checks":["ナットの引き込み方法と、テープで仮止めする方法を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/439e93bc86b5e40e21c14d2efe7c87ba-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"315726b01a1d9bd2"},{"chapter":0,"officialStep":11,"officialId":982830,"chapterSteps":15,"title":"電子部品の取り扱い","description":"電子基板は取り付け直前までESD袋に入れておきます。扱う前に近くの金属構造物へ触れて手の静電気を逃がし、基板の縁だけを持ってください。表面の部品や端子には触れず、静電気がたまりやすいカーペットや衣服にも注意します。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982830","checks":["基板を直前までESD袋に入れ、縁を持って扱う方法を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c76c0776008a589daf67a9fcd5617829-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"e56ff5b212f4769e"},{"chapter":0,"officialStep":12,"officialId":982896,"chapterSteps":15,"title":"休憩のごほうび","description":"キットのグミは、章ごとの休憩用に取っておきましょう。公式マニュアルでは各章の終わりに食べる列が案内されています。休憩もグミも任意です。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982896","checks":["章ごとの任意の休憩について確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/00d4cc46192ce8f70bc122dc469c0bf4-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"ae9fc3dd1ec0a7b0"},{"chapter":0,"officialStep":13,"officialId":982945,"chapterSteps":15,"title":"最後まで進めるコツ","description":"写真だけで進めず、各手順の説明と注意事項を最後まで読んでから作業します。指示がない切断・切り詰めはしないでください。部品が合わないときは力を増す前に、向きと手順をもう一度確認します。","parts":[],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#982945","checks":["説明を先に読み、指示なく切断せず、合わない部品を無理に押し込まないことを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/02c0e7d5c2d11adc48d61527aec87ef1-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"fd370a3e007f2d30"},{"chapter":0,"officialStep":14,"officialId":983011,"chapterSteps":15,"title":"作業台を整える","description":"平らで明るい作業台を片付け、小さな部品を置く場所を確保します。推奨作業範囲は1.5 × 1.5 m以上です。金属板で傷が付かないよう、柔らかいマットや段ボールを敷き、梱包材を捨てる前に部品が残っていないか確認してください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#983011","checks":["明るく平らな作業場所、保護用の敷物、小物の置き場所を用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a4a55a208fd045a8b5012d21604001a9-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"26d8f719f3fe2ea2"},{"chapter":0,"officialStep":15,"officialId":983085,"chapterSteps":15,"title":"追加オプションについて","description":"追加オプションは、本体を組み立てて動作確認を済ませてから、各オプションの専用ガイドに沿って取り付けます。Buddy3D CameraのUSB先行配線など、途中で個別の案内がある場合は、その手順に従ってください。","parts":[],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_981923#983085","checks":["本体の組み立て・テストを先に行い、先行配線は指定手順に従うことを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/dd15251ac31358a3572f27e164ff574d-800x600.jpg","reveal":[],"add":[],"fullContext":true,"verificationRevision":"de4f6b443094c560"},{"chapter":1,"officialStep":1,"officialId":983111,"chapterSteps":22,"title":"この章で使う工具","description":"13–16 mmレンチ、2.5 mm六角レンチ、T10トルクスを用意します。工具は「2. Electronics & Fasteners」の箱に入っています。","parts":["zDrive","base"],"tip":"","kind":"prepare","time":1,"tools":["13–16 mm レンチ","2.5 mm 六角レンチ","T10 トルクスレンチ"],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983111","checks":["13–16 mmレンチ、2.5 mm六角レンチ、T10トルクスを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3f4de27076a766c3-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"fcff06d9d3aa3730"},{"chapter":1,"officialStep":2,"officialId":983155,"chapterSteps":22,"title":"ベースの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["zDrive","base"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983155","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["底板（1枚） — 「Metal parts 1/3」同梱","結束バンド（6本） — 「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9c58ca2ea5740978f1b0ea6327da4962-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"c8cab381ef8380e2"},{"chapter":1,"officialStep":3,"officialId":983191,"chapterSteps":22,"title":"結束バンドを通す","description":"底板の折り曲げ部を上にし、周囲の2つずつの穴へ結束バンドを6本通します。先端をロックへ入れ、最初の数歯だけ掛けて大きな輪を残してください。後で配線を通すため、まだ締めません。ロック部は板金の内側・外側のどちらでも構いません。","parts":["zDrive","base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983191","checks":["6本のバンドは数歯だけ掛かり、配線を通す大きな輪が残っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c4881789eb687565592981e8363baaf6-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"8f7b4f8e0d20d926"},{"chapter":1,"officialStep":4,"officialId":983243,"chapterSteps":22,"title":"ベース部品を確認する①","description":"左Zモーター2個と右Zモーター1個を用意します。左のうち1個はElectronics & chamber partsの箱へ別に入っています。台形ナットはまだ使わず、モーターの梱包に残しておいてください。","parts":["zDrive","base"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983243","checks":["左2個・右1個のZモーターを用意し、台形ナットは後の手順用に残した"],"supplies":["左Z軸モーター（2個） — 「Motor set」同梱","右Z軸モーター（1個） — 「Motor kit」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4c459706cf74e795a1e0601e46a01ddc-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"7b928539d4cb3af0"},{"chapter":1,"officialStep":5,"officialId":1071272,"chapterSteps":22,"title":"ベース部品を確認する②","description":"Z-motor-mountを3個、Z-rod-mountを2個、M3x8を24本用意します。Motor washerが付属する型では透明ワッシャー3枚も使います。ワッシャーが入っていないキットは、それを必要としない新型マウントです。追加のワッシャーを用意する必要はありません。","parts":["zDrive","base"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#1071272","checks":["付属品を確認し、手元のマウントが透明ワッシャーを使う型か確認した"],"supplies":["Zモーターマウント（Z-motor-mount）（3個） — 「Printed parts」同梱","モーターワッシャー（3枚） — 「Electronics & Chamber parts」同梱","Zロッドマウント（Z-rod-mount）（2個） — 「Printed parts」同梱","M3x8ネジ（24本） — 「Fasteners (3/3)」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/04/911ad73f8fff7f36-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"688cd40e76a04ce8"},{"chapter":1,"officialStep":6,"officialId":983329,"chapterSteps":22,"title":"モーターマウントを取り付ける","description":"3個のZモーターそれぞれで、ねじ棒を手で回せるか確認します。「Electronics & Chamber parts」の袋に透明パッド（Motor washer）を同梱する型は、各モーターに1枚載せ、その上にマウントを置きます。Motor washerを同梱しないキットは、パッド不要の新型Z-motor-mountです。パッドを追加せず、マウントを直接載せます。どちらの型も突起を上に向け、穴を合わせてM3x8を4本ずつ使って固定します。3個とも同じ構成にします。","parts":["zDrive","base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983329","checks":["3個すべてのZモーターで、ねじ軸を手で回せることを確認した","Motor washer同梱型は各1枚、同梱しない新型はパッドなしで、3個ともマウントの突起を上に向け、M3x8を4本ずつ使って固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/41cab994664d7772a4798d5732da78a9-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"a47e7309000921f3"},{"chapter":1,"officialStep":7,"officialId":983383,"chapterSteps":22,"title":"後方のモーターを取り付ける","description":"底板を裏返します。最も長いケーブルにZR表示がある右Zモーターを後ろ中央の丸穴へ通し、ケーブルを外側へ向けて穴を合わせます。左Zモーター2個は前側の穴へ入れ、ケーブルを後方モーター側へ向けてください。前はモーター2個、後ろは1個です。","parts":["zDrive","base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983383","checks":["長いZRを後ろ中央へ、残り2個を前へ入れ、前のケーブルは後ろへ向けた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4d334b0c6b6967d4ea1984426db3a49d-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"bb909b9c1302c1d4"},{"chapter":1,"officialStep":8,"officialId":983461,"chapterSteps":22,"title":"後方モーターを固定する","description":"後方モーターをM3x8の4本で固定します。ねじを傾けず、まっすぐ締めてください。樹脂へ直接ねじ込むため、最後はレンチの短い側を持って締めすぎを防ぎます。","parts":["zDrive","base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983461","checks":["後方モーターのM3x8の4本をまっすぐ、締めすぎずに固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f70f254da6c7c1b502624e8649d1fbd5-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"98a34a70ec764ad5"},{"chapter":1,"officialStep":9,"officialId":983505,"chapterSteps":22,"title":"右前のモーターを取り付ける","description":"Z-rod-mountの内部に突起や異物がないか確認し、Rods箱の細いスムースロッドを試し通しします。前から見た右前モーターの隣へマウントを入れ、13–16レンチで90°回してロックしてください。モーターはM3x8の4本をまっすぐ入れ、しっかり固定します。","parts":["zDrive","base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983505","checks":["Z-rod-mount内部が清潔で、細いスムースロッドを試し通しできた","右前ロッドマウントを90°回して固定し、モーターをM3x8の4本で留めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/23c7226982dc46c3bc449c9a30dfc4c8-800x600.jpg","reveal":["zDrive","base"],"add":[],"verificationRevision":"bdfa1c698bf1a9ee"},{"chapter":1,"officialStep":10,"officialId":983551,"chapterSteps":22,"title":"左前のモーターを取り付ける","description":"前から見た左前モーターのケーブルが後ろを向いていることを確認します。左前の残りのロッドマウントを入れ、13–16レンチで90°回してロックしてください。モーターをM3x8の4本でまっすぐ固定し、ベース一式を脇に置きます。","parts":["zDrive","base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983551","checks":["左前のケーブルを後ろへ向け、ロッドマウントを90°でロックしてモーターを4本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6d47546137693d0b3352edc61af588b9-800x600.jpg","reveal":["zDrive","base"],"add":["zDrive"],"verificationRevision":"c278995b587be13b"},{"chapter":1,"officialStep":11,"officialId":983621,"chapterSteps":22,"title":"底面フレームの部品を準備する","description":"薄板の縁でけがをしないよう注意してください。前面プロファイルは切り欠きあり、背面用は平らな面に穴が2個、ユニバーサル用は平らな面に穴がありません。よく似ているので、形を確認してから部品表の数量を用意します。","parts":["base"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983621","checks":["切り欠きのある前面用1本、穴2個の背面用1本、穴のないユニバーサル用2本を選んだ"],"supplies":["前プロファイル（1本） — 切り欠きのある部品。「Metal parts 1/3」同梱","後ろプロファイル（1本） — 平面に2つの穴がある部品。「Metal parts 1/3」同梱","共通プロファイル（2本） — 平面に穴がない部品。「Metal parts 1/3」同梱","スペーサーピン（2本） — 「Electronics & Fasteners」同梱","M3x4rTネジ（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3533800b16ceda06cc717220a8b27ec9-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"59f330179ebb5d88"},{"chapter":1,"officialStep":12,"officialId":983699,"chapterSteps":22,"title":"前・左の底面プロファイルを組む","description":"板金の縁に注意し、切り欠きが手前になるよう前プロファイルを置きます。左のユニバーサルプロファイルの下へ前プロファイルのフランジを差し込み、穴を合わせてM3x4rTで接合してください。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983699","checks":["前プロファイルのフランジを左プロファイルの下へ入れ、M3x4rTで接合した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/63c026315cda9f451be24f4c1f63b82d-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"ae302e15b5d84df9"},{"chapter":1,"officialStep":13,"officialId":983769,"chapterSteps":22,"title":"左・後ろの底面プロファイルを組む","description":"平らな面に穴が2つある後ろプロファイルを、左のユニバーサルプロファイルへ合わせます。左プロファイルのフランジを後ろプロファイルの下にし、穴を合わせてM3x4rTで接合してください。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983769","checks":["左のフランジが後ろプロファイルの下に入り、M3x4rTで接合した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b563de85c47e0ef3f0f7442bfb94fb9f-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"91075cbd17be909d"},{"chapter":1,"officialStep":14,"officialId":983823,"chapterSteps":22,"title":"右の底面プロファイルを組む","description":"右ユニバーサルプロファイルを前後の間へ入れます。後ろ端は後ろプロファイルのフランジの上へ、前のフランジは前プロファイルの下へ収めてください。両端をM3x4rTの2本で固定します。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983823","checks":["右プロファイルの後端はフランジの上、前フランジは前プロファイルの下で、両端を固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/fb7b6feef8d7fdc12f903f834550ea5a-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"f21abd77fcdb4d23"},{"chapter":1,"officialStep":15,"officialId":983867,"chapterSteps":22,"title":"スペーサーピンを入れる","description":"前プロファイルの突起にある穴へスペーサーピンを入れ、しっかり押して奥まで収めます。2本目も同じように入れてください。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983867","checks":["前プロファイルのスペーサーピン2本が奥まで入っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f6a3dc7224e2618d19f40fa68904c146-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"349a6a4b9ae753c0"},{"chapter":1,"officialStep":16,"officialId":983903,"chapterSteps":22,"title":"防振フットの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["feet"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983903","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["防振フット（4個） — 「Electronics & Chamber parts」同梱","M3x4rTネジ（8本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/07af277f3a9db5167f41ddd8e6ea088b-800x600.jpg","reveal":["feet"],"add":[],"verificationRevision":"0de3b40f20590a08"},{"chapter":1,"officialStep":17,"officialId":983939,"chapterSteps":22,"title":"防振フットを取り付ける","description":"フットを貼る金属面をイソプロピルアルコールで拭き、乾かします。粘着層を剥がさないよう保護フィルムだけを外し、四隅の外縁に合わせて貼ってください。粘着層も付いてきたら別の角から剥がします。接着が弱い場合は終盤まで取り付けを待つか、公式案内どおり3M VHBテープを使えます。","parts":["feet"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983939","checks":["粘着層を剥がしていない。フットを外縁へ貼ったか、接着が弱い場合は取り付けを後へ回した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6ed2045499797a2cf8440e32160cdcd9-800x600.jpg","reveal":["feet"],"add":["feet"],"verificationRevision":"a28020fd8170c4e1"},{"chapter":1,"officialStep":18,"officialId":983991,"chapterSteps":22,"title":"底面フレームを取り付ける","description":"底面フレームを裏返し、切り欠きのある前プロファイルを手前にします。モーター2個の側を前、1個の側を後ろへ合わせて底板一式を載せてください。ケーブルを中央へよけ、ゆっくり下ろして全体をフレーム内へ収めます。はみ出しやケーブルの挟み込みがないか確認します。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#983991","checks":["前がモーター2個で、底板全体がフレーム内に収まり、ケーブルを挟んでいない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/706e35ad85e8a2ecb2f206780ea378bf-800x600.jpg","reveal":["base"],"add":["base"],"verificationRevision":"27f970c55941bdfe"},{"chapter":1,"officialStep":19,"officialId":984069,"chapterSteps":22,"title":"底面フレームの右側を固定する","description":"右前の角を少し持ち上げ、底板とプロファイルの穴を合わせてM3x4rTで固定します。必要なら一式を横向きにし、隣の穴へ六角レンチを通して位置を保ってください。右後ろの角も合わせ、もう1本のM3x4rTで固定します。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#984069","checks":["右前と右後ろの2か所をM3x4rTで接合した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/569234e0232427a35febc6928c6654c1-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"ee563fdc644a1271"},{"chapter":1,"officialStep":20,"officialId":984131,"chapterSteps":22,"title":"底面フレームの残りを固定する","description":"モーター1個がある後ろ側をM3x4rTの2本で固定します。左側も2本、切り欠きのある前側も2本で接合してください。","parts":["base"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#984131","checks":["後ろ・左・前をそれぞれM3x4rTの2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f90678eafd65ed4e1a6f5b0366545abb-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"bbf675657812313e"},{"chapter":1,"officialStep":21,"officialId":984193,"chapterSteps":22,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの1列目が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["base"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#984193","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c2a86b5d8f2ba8e36f7ffa4cacd81abd-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":1,"officialStep":22,"officialId":984243,"chapterSteps":22,"title":"ベースの組み立てを確認する","description":"ベースの組み立てはここまでです。未確認の手順がないか見直し、ベースユニットをいったん脇によけて次の章へ進みます。","parts":["base"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-base-assembly_981931#984243","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/129c53733b8c0596-800x600.jpg","reveal":["base"],"add":[],"verificationRevision":"1244d7ec7442a18d"},{"chapter":2,"officialStep":1,"officialId":984269,"chapterSteps":53,"title":"この章で使う工具","description":"PH2プラスドライバー、ラジオペンチ、2.5 mm六角レンチ、T10トルクスを用意します。","parts":["psu"],"tip":"","kind":"prepare","time":1,"tools":["PH2 プラスドライバー","ラジオペンチ","2.5 mm 六角レンチ","T10 トルクスレンチ"],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984269","checks":["PH2プラスドライバー、ラジオペンチ、2.5 mm六角レンチ、T10トルクスを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3f4de27076a766c3-800x600.jpg","reveal":["psu"],"add":[],"view":"back","verificationRevision":"0677de4df36115c2"},{"chapter":2,"officialStep":2,"officialId":984321,"chapterSteps":53,"title":"電源ユニットの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["psu"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984321","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["Delta電源ユニット 240 W 24 V（1個） — 電源ユニット","M4x6rネジ（2本） — 「Fasteners 3/3」同梱","xBuddy電源ケーブル（2本） — 「Electronics」同梱","Power Panicケーブル（1本） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1388c9ddab50875085f90eb95a55ee8a-800x600.jpg","reveal":["psu"],"add":[],"view":"back","verificationRevision":"ec5c7459123b473c"},{"chapter":2,"officialStep":3,"officialId":984375,"chapterSteps":53,"title":"電源ユニットを準備する","description":"電源の左側面にM4x6rを2本入れ、頭の下に4 mm以上の隙間を残します。電源端子のネジ4本は3～4回転だけ緩め、抜き取らないでください。","parts":["psu"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984375","checks":["左側面のネジ2本に4 mm以上の隙間があり、端子ネジは抜いていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/92206b6967e57fe5a5159e94a09629ee-800x600.jpg","reveal":["psu"],"add":[],"view":"back","verificationRevision":"1392bfea9b99f973"},{"chapter":2,"officialStep":4,"officialId":984403,"chapterSteps":53,"title":"電源ケーブルの注意点","description":"赤が主な色の線は＋、黒が主な色の線は−です。縞の色だけで判断しないでください。電源側ではU字端子を使います。電源端子のネジはxBuddy側とは別の種類なので、外して混ぜないでください。まだ接続せず、次の手順に進みます。","parts":["psu"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984403","checks":["配線の主な色と電源のV+・V−表示を確認した","電源の端子ネジは外さずに残し、xBuddy側のネジと混ぜていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/01e8ffd46d67c0982d325ec64e02052b-800x600.jpg","reveal":["psu"],"add":[],"view":"back","verificationRevision":"f8d8e8fdccf14c87"},{"chapter":2,"officialStep":5,"officialId":984487,"chapterSteps":53,"title":"電源ユニットに配線する","description":"公式写真の向きで、電源の下側にある左から1・2番目のV+端子へ赤線、3・4番目のV−端子へ黒線を接続します。U字端子をワッシャーの下まで差し込み、端子ネジを締めてください。Power Panicケーブルは一番右のコネクターに接続します。","parts":["psu"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984487","checks":["赤はV+、黒はV−で、U字端子がワッシャーの下に収まり、端子ネジ4本を締めた","Power Panicを電源の一番右のコネクターに接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a82f26bc313e0f3e670ecef4adb4025a-800x600.jpg","reveal":["psu"],"add":[],"view":"back","verificationRevision":"9b233c7cbb5d52fe"},{"chapter":2,"officialStep":6,"officialId":984549,"chapterSteps":53,"title":"xBuddyの部品を準備する①","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984549","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["CORE One xBuddyケース（1個） — 「Metal parts 3/3」同梱","グロメット 19/16 mm（2個） — 「Electronics & Fasteners」同梱","サーマルパッド 40x12x2.2 mm（1枚） — 「Electronics & Fasteners」同梱","サーマルパッド 12x12x2.2 mm（2枚） — 「Electronics & Fasteners」同梱","結束バンド（4本）","M3x6ネジ（9本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4e37cfe18e184d7c7eba5998b526f6d9-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"c46160b0b52e9a6b"},{"chapter":2,"officialStep":7,"officialId":984627,"chapterSteps":53,"title":"xBuddyの部品を準備する②","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics","xBuddy","xBuddyExtension"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984627","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["xBuddy拡張基板（1枚） — 「Electronics & chamber」同梱","xBuddyメイン基板（1枚） — 「Electronics」同梱","xBuddy拡張基板用ケーブル（1本） — 「Electronics & Fasteners」同梱","組み立て用マルチツール（Assembly-multi-tool）（1個） — 「Printed parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f23223e843362009c55914b8757cb19d-800x600.jpg","reveal":["electronics","xBuddy","xBuddyExtension"],"add":[],"view":"back","verificationRevision":"6c41cf2b93ed2cef"},{"chapter":2,"officialStep":8,"officialId":984671,"chapterSteps":53,"title":"サーマルパッドを貼る","description":"xBuddy基板は端を持ち、部品に触れないよう柔らかい梱包材の上に置きます。パッドを貼る裏面の油分を取り除き、白い保護フィルムを剥がして、サイズと位置の印に合わせて貼ってください。最後に青いフィルムもすべて剥がします。剥がしにくい端はAssembly-multi-toolの薄い側で持ち上げられます。","parts":["xBuddy","thermalPads"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984671","checks":["パッドの位置とサイズが印に合い、白・青の保護フィルムをすべて剥がした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d59310dd0f8e35a25687494248baf415-800x600.jpg","reveal":["xBuddy","thermalPads"],"add":[],"view":"back","verificationRevision":"d8117549d8dcaad4"},{"chapter":2,"officialStep":9,"officialId":984741,"chapterSteps":53,"title":"xBuddyを取り付ける","description":"基板の縁を持ち、Ethernet端子をケースの開口に合わせます。M3x6を5本とも仮止めしてから慎重に締めます。右下の穴は空けておいてください。","parts":["xBuddy","electronics"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984741","checks":["Ethernet端子が開口に合い、M3x6は5本、右下の穴は空いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/72c1a4ead7366d0fd0a4ea2b3aa3cb1a-800x600.jpg","reveal":["xBuddy","electronics"],"add":[],"view":"back","verificationRevision":"433231c90f150263"},{"chapter":2,"officialStep":10,"officialId":984811,"chapterSteps":53,"title":"xBuddy拡張基板を取り付ける","description":"拡張基板をxBuddyの上に置き、基板の4つの穴をケースの支柱に合わせます。M3x6を4本使って固定してください。","parts":["xBuddyExtension","electronics"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984811","checks":["拡張基板の向きと4か所の固定を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/01dfe78407f1ab804fe2d42663bd92fc-800x600.jpg","reveal":["xBuddyExtension","electronics"],"add":[],"view":"back","verificationRevision":"5206b6fb18801e0e"},{"chapter":2,"officialStep":11,"officialId":984847,"chapterSteps":53,"title":"結束バンドを取り付ける","description":"xBuddyボックスの6か所の穴のうち、3番目と6番目を空けて結束バンドを通します。先端を約30°曲げ、Assembly-multi-toolのフックを最初の左側の穴の下に当てて、バンドをボックス内へ導いてください。歯が見える側を向けます。基板のコネクターやコンデンサーを傷つけないよう慎重に作業します。","parts":["electronics"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984847","checks":["3番目と6番目の穴を空け、歯を見える側に向けて4本を通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/eeee63f037d7d997a920cd4b67fa54c8-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"47bda35503ab9f08"},{"chapter":2,"officialStep":12,"officialId":984917,"chapterSteps":53,"title":"拡張基板を接続する","description":"赤い枝線がある側のコネクターをxBuddy拡張基板へ、反対側をxBuddyメイン基板へ接続します。赤い枝線は、まだ接続せずに残してください。","parts":["electronics"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984917","checks":["赤い枝線がある側は拡張基板、反対側はメイン基板に接続し、赤い枝線はまだ接続していない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8f72e23f545085aa-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"fab755551919f5ea"},{"chapter":2,"officialStep":13,"officialId":984953,"chapterSteps":53,"title":"xBuddyボックスにグロメットを入れる","description":"xBuddyボックスの丸穴2か所にグロメットを入れます。軽くつぶして穴へ押し込み、板金の縁がグロメットの溝に一周収まるようにしてください。","parts":["electronics"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984953","checks":["丸穴2か所とも、板金の縁がグロメットの溝に収まっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2444208fc601ac2fbf6ae7ea9d676e40-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"fa8369d1504af99d"},{"chapter":2,"officialStep":14,"officialId":984983,"chapterSteps":53,"title":"Wi-Fiの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#984983","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["ESP-WiFiモジュール（1個） — 「Electronics」同梱","Wi-Fiカバー（CORE-One-Wifi-cover）（1個） — 「Printed parts」同梱","M3x12ネジ（1本）","M3x6ネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4fc9f9f3a4facb6119b5a7c1652b10d8-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"573001c7335c5d25"},{"chapter":2,"officialStep":15,"officialId":985035,"chapterSteps":53,"title":"Wi-Fiユニットを組み立てる","description":"右側のM3x6を2本入れ、頭の下に4 mm以上残します。ESP-WiFiをカバーの橋の下に収め、端子を開口に合わせます。次の手順用のM3x12もケースに通してください。穴がきつくてM3x12を通せない場合は、六角レンチかドライバーで穴を慎重に広げ、ねじが入ることを確認します。","parts":["electronics"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985035","checks":["M3x6の頭の下に4 mm以上あり、Wi-Fiの端子が開口に合っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7dcad286d39f7a48cbf9daf86c89e905-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"fbd3bc79f005e6ec"},{"chapter":2,"officialStep":16,"officialId":985073,"chapterSteps":53,"title":"Wi-Fiユニットを取り付ける","description":"先にxBuddyボックスの穴へM3x12をねじ込み、一度外してねじが入ることを確認します。Wi-Fiカバー一式のESPモジュールを、ピンを曲げないようxBuddyのコネクターへまっすぐ差し込んでください。ピンが正しく入ったことを確認してカバーを合わせ、M3x12で固定します。","parts":["electronics"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985073","checks":["ESPのピンが正しく入り、カバーをM3x12で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/cb911e449d0281802d2af4df0dc6a031-800x600.jpg","reveal":["electronics"],"add":[],"view":"back","verificationRevision":"22dc528faf412eab"},{"chapter":2,"officialStep":17,"officialId":985127,"chapterSteps":53,"title":"背面パネルの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["back"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985127","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["背面パネル（1枚） — 「Metal parts 1/3」同梱","グロメット 19/16 mm（2個） — 大きい方。「Electronics & Fasteners」同梱","グロメット 13.5/10 mm（2個） — 小さい方。「Electronics & Fasteners」同梱","シーリングプラグ 15.5 mm（1個） — 「Electronics & Fasteners」同梱","M3x4rTネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f9c60ebfdc340b30f305817eb51651e1-800x600.jpg","reveal":["back"],"add":[],"view":"back","verificationRevision":"a5c0d0965811c94f"},{"chapter":2,"officialStep":18,"officialId":985189,"chapterSteps":53,"title":"背面パネル上部にグロメットを入れる","description":"2つの楕円穴を目印に、背面パネルを公式写真と同じ向きに置きます。中央の穴には、細い側を下にしてシーリングプラグを入れてください。左の丸穴と、写真で示された楕円穴には小さいグロメットを1個ずつ入れます。","parts":["back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985189","checks":["中央のプラグは細い側が下で、小さいグロメット2個を指定穴に入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a8e4224752564b92644bc443885483e1-800x600.jpg","reveal":["back"],"add":[],"view":"back","verificationRevision":"1acd395c0d5df421"},{"chapter":2,"officialStep":19,"officialId":985243,"chapterSteps":53,"title":"側面・底面にグロメットを入れる","description":"公式写真の向きで背面パネルの左上にある2つの楕円穴を確認し、角に近い方へ大きいグロメットを入れます。右上の楕円穴にも大きいグロメットを入れてください。","parts":["back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985243","checks":["大きいグロメット2個を、左上の角寄りの穴と右上の穴に入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/19dfb9b0f1cd8a9a5fcea2041de1d568-800x600.jpg","reveal":["back"],"add":[],"view":"back","verificationRevision":"d8d8760839ebaefe"},{"chapter":2,"officialStep":20,"officialId":985279,"chapterSteps":53,"title":"電源ユニットの位置を合わせる","description":"電源ユニットを背面パネルのくぼみに置き、ユニットのねじをパネル左側の穴に合わせて通します。電源ケーブルはパネルの穴へ入れず、そのまま外に垂らしてください。xBuddyへの接続は後の手順で行います。","parts":["psu","back"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985279","checks":["電源のねじを左側の穴に通し、ケーブルはパネルの穴へ入れていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/fc9478d411af4ba75f8cd33794935237-800x600.jpg","reveal":["psu","back"],"add":[],"view":"back","verificationRevision":"549a690e74bd6bd6"},{"chapter":2,"officialStep":21,"officialId":985317,"chapterSteps":53,"title":"電源ユニットを固定する","description":"電源ユニットをゆっくりスライドし、2本のねじを鍵穴形の穴の端まで移動します。その位置を保ったまま、2本ともしっかり締めてください。","parts":["psu","back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985317","checks":["2本とも鍵穴の端に収まり、電源ユニットを固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3def4a747c12b64e32d110a924ca20a3-800x600.jpg","reveal":["psu","back"],"add":["psu"],"view":"back","verificationRevision":"dbe0aa2fa855728f"},{"chapter":2,"officialStep":22,"officialId":985345,"chapterSteps":53,"title":"xBuddyボックスの位置を合わせる","description":"xBuddyボックス一式を背面パネルのくぼみに入れます。ボックスのねじをパネル右側の穴に合わせ、スライドして通してください。","parts":["electronics","back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985345","checks":["xBuddyボックスのねじをパネル右側の穴に通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d8b6f42c32583024871f96283e22071f-800x600.jpg","reveal":["electronics","back"],"add":[],"view":"back","verificationRevision":"5b60675e30acbfcf"},{"chapter":2,"officialStep":23,"officialId":985383,"chapterSteps":53,"title":"xBuddyボックスを固定する","description":"xBuddyボックスをゆっくりスライドし、2本のねじを鍵穴形の穴の端まで移動します。位置を保って2本を締めてください。さらにM3x4rTの2本で、電源ユニットとxBuddyボックスを背面パネルに固定します。","parts":["electronics","back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985383","checks":["xBuddyボックスのねじ2本を締め、追加のM3x4rTの2本も取り付けた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0e2900693ed3301e3f98def7c81eb7fe-800x600.jpg","reveal":["electronics","back"],"add":["electronics"],"view":"back","verificationRevision":"40e38277a7b42aa2"},{"chapter":2,"officialStep":24,"officialId":985421,"chapterSteps":53,"title":"電源ケーブルカバーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["psu","covers"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985421","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["電源ケーブルカバー（PSU-cable-cover）（1個） — 「Printed parts」同梱","M3nSナット（2個）","M3x10rTネジ（2本）","6-32 電源端子ネジ（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4a17f8414843da2e33f436fea1bafda1-800x600.jpg","reveal":["psu","covers"],"add":[],"view":"back","verificationRevision":"6bf393ffdf7b094d"},{"chapter":2,"officialStep":25,"officialId":985473,"chapterSteps":53,"title":"電源ケーブルを接続する","description":"公式写真の向きで、電源からのケーブルを1組ずつ、xBuddyの左から赤・黒・赤・黒の順で接続します。6-32電源端子ネジ4本を使い、L字端子をネジ頭の下に収めて締めてください。3番目には拡張基板の赤線も共締めします。拡張ケーブルはヒューズの間を通し、ヒューズを押さないようにします。小型の白いヒューズの基板もあります。取付穴を空けた状態で配線し、Power Panicを基板の右下に接続して余長を端子の上で数回巻きます。","parts":["psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985473","checks":["赤・黒・赤・黒の順で、L字端子が6-32電源端子ネジの頭の下に収まり、4本を締めた","3番目の端子で拡張基板の赤線も固定し、取付穴をふさいでいない","拡張ケーブルがヒューズの間を通り、ヒューズを押していない","Power Panicを基板の右下に接続し、余長を端子の上で巻いた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/173c87ad3e6079eec496df91cadc4e94-800x600.jpg","reveal":["psu","covers"],"add":[],"view":"back","verificationRevision":"7193148b4e36ec02"},{"chapter":2,"officialStep":26,"officialId":985559,"chapterSteps":53,"title":"電源ケーブルカバーを準備する","description":"PSU-cable-coverの両端へ、M3nS角ナットを1個ずつ差し込みます。ナットのねじ穴がカバーの穴と合っていることを確認してください。","parts":["psu","covers"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985559","checks":["両端の角ナット2個を入れ、ねじ穴が合っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a0ee2a188cae586a913c800fa3242e3c-800x600.jpg","reveal":["psu","covers"],"add":[],"view":"back","verificationRevision":"dcdd36ed1365d066"},{"chapter":2,"officialStep":27,"officialId":985587,"chapterSteps":53,"title":"電源ケーブルを覆う","description":"PSU-cable-coverを電源ケーブルにかぶせます。部品の一番外側の穴2か所を使い、M3x10rTの2本で固定してください。","parts":["psu","covers"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985587","checks":["カバーの一番外側の穴を使い、M3x10rTの2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/522ba44197ed66d20108b13606b18e5c-800x600.jpg","reveal":["psu","covers"],"add":["covers"],"view":"back","verificationRevision":"fc57477bb4793140"},{"chapter":2,"officialStep":28,"officialId":985613,"chapterSteps":53,"title":"チャンバーファンの部品を準備する","description":"ファングリッドには旧型の平らなものと、新型の囲いのあるものがあります。どちらも組み立ての順序は同じです。新型の内側・外側とケーブルの通し方は、次の参考写真で確認します。260 mmのチャンバーサーミスターとファン2個など、部品表のものを用意してください。","parts":["fans"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985613","checks":["手元のグリッドと、260 mmサーミスター、ファン2個を含む部品を用意した"],"supplies":["ファングリッド（1枚） — 「Electronics & Chamber parts」同梱","チャンバー用サーミスター 260 mm（1本） — 「Electronics & Chamber parts」同梱","結束バンド（1本）","冷却ファン（2個） — 「Electronics & Chamber parts」同梱","M3x30ネジ（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/07/c86a9369d5676503f6458f8f789aaa44-800x600.jpg","reveal":["fans"],"add":[],"view":"back","verificationRevision":"45b299d1c09796d4"},{"chapter":2,"officialStep":29,"officialId":1094480,"chapterSteps":53,"title":"新しいファンカバーを確認する","description":"ここでは新しいファンカバーの表裏と配線位置を写真で確認します。旧型の平らなグリッドは両面が同じですが、新型は内側と外側が決まっています。取り付けの順序は同じです。まだ組み立てず、次の手順へ進んでください。","parts":["fans"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#1094480","checks":["使用するカバーの表裏を確認した。この手順ではまだ組み立てていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/07/29f4bb8a65ab2c57bc4c8925481e3c8b-800x600.jpg","reveal":["fans"],"add":[],"view":"back","verificationRevision":"38157edccf3074e1"},{"chapter":2,"officialStep":30,"officialId":985673,"chapterSteps":53,"title":"ファングリッドを組み立てる","description":"サーミスターの検出部を外に残し、ケーブルを公式写真の向きでグリッドの下へ通します。新型カバーでは内側を使ってください。グリッドを裏返し、突起の2つの穴へ結束バンドを通してケーブルを挟みます。ロック部はサーミスターと反対側に置き、ケーブルを傷めない程度に締めてください。","parts":["fans"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985673","checks":["検出部を外に残し、ロック部を反対側にして、ケーブルを強くつぶさず固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ed18f26c31833ddb3b5a1fccc90398c1-800x600.jpg","reveal":["fans"],"add":[],"view":"back","verificationRevision":"ca733f3c5534bf13"},{"chapter":2,"officialStep":31,"officialId":985751,"chapterSteps":53,"title":"ファンを取り付ける","description":"ファン用のグリッド穴が手前に来るよう背面パネルを置きます。ファン2個はステッカーのない面を上にし、ケーブルが中央側の角から出る向きで載せてください。ケーブルはまだ固定せず、挟み込まないよう外へ垂らします。","parts":["fans"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985751","checks":["ファン2個ともステッカーなしの面が上で、ケーブル出口が中央側にある"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/65e1c9e8f821a2e78702a077d51fb6e2-800x600.jpg","reveal":["fans"],"add":["fans"],"view":"back","verificationRevision":"d527e9e1e7ce0a1d"},{"chapter":2,"officialStep":32,"officialId":985803,"chapterSteps":53,"title":"冷却ファンにカバーを付ける","description":"組み立てたグリッドをファンに載せます。サーミスターが上を向き、ケーブルがグリッドの下を通っていることを確認してください。ファン・グリッド・背面パネルの穴を合わせ、M3x30の4本で固定します。グリッドを割らないよう締めすぎないでください。","parts":["fans"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985803","checks":["サーミスターは上、ケーブルはグリッドの下で、M3x30の4本を締めすぎず固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1a2cc7ad0b20e719-800x600.jpg","reveal":["fans"],"add":[],"view":"back","verificationRevision":"4426052a11154383"},{"chapter":2,"officialStep":33,"officialId":985855,"chapterSteps":53,"title":"背面プロファイルの部品を準備する","description":"長いプロファイルのうち、切り欠きのない2本を背面用に選びます。もう一組の長いプロファイルには切り欠きがあります。ナイロンリベット11個、M3x4rTを4本、2.9x6.5sTのタッピングねじを1本用意してください。","parts":["back"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985855","checks":["切り欠きのない長いプロファイル2本を選び、指定のねじとリベットを用意した"],"supplies":["後ろプロファイル（2本） — 「Metal parts 1/3」同梱","ナイロンリベット（11個）","M3x4rTネジ（4本）","2.9x6.5sTタッピングネジ（1本） — 「Electronics and Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2b8ea17cc18d32d89ed2096e4547392c-800x600.jpg","reveal":["back"],"add":[],"view":"back","verificationRevision":"88fc772e04b57ee3"},{"chapter":2,"officialStep":34,"officialId":985917,"chapterSteps":53,"title":"背面プロファイルを取り付ける","description":"中央にモーター1個がある後ろ側を手前にします。底板の最も長い楕円穴がある右後ろ角へ、背面プロファイルのフランジがない端を合わせてください。後ろ側ともう一方の面をM3x4rTの2本で固定します。左後ろ角も同様に、プロファイル1本につき2本で固定します。","parts":["back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985917","checks":["後ろの左右プロファイルはフランジなしの端が下で、各M3x4rTの2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/af6eb623cb88b4b27c22a16e11f845aa-800x600.jpg","reveal":["back"],"add":[],"view":"back","verificationRevision":"691036602d793859"},{"chapter":2,"officialStep":35,"officialId":985979,"chapterSteps":53,"title":"背面パネルを固定する","description":"背面一式を少し持ち上げ、ベースと背面プロファイルへ静かに載せます。右上からナイロンリベットを通し、頭を指で押して奥まで入れてください。周囲の11本を同様に入れます。最後に2.9x6.5のタッピングねじを取り付けます。抵抗が強い場合は無理に締めず、公式手順どおり2 mmの下穴を開けるか、完全に締め切らずに残してください。","parts":["back"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#985979","checks":["ナイロンリベット11本が奥まで入り、タッピングねじを無理に締めていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4374014996ef3f2431487573c50895c2-800x600.jpg","reveal":["back"],"add":["back"],"view":"back","verificationRevision":"3f61414ad499fdb9"},{"chapter":2,"officialStep":36,"officialId":986033,"chapterSteps":53,"title":"Stepper splitterの部品を準備する","description":"Stepper Splitter基板1枚と、Stepper Splitterケーブル1本を用意します。基板は「電子部品とチャンバー」、ケーブルは「電子部品と締結部品」の袋にあります。","parts":["stepperSplitter"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986033","checks":["基板1枚とStepper Splitterケーブル1本を用意した"],"supplies":["Stepper Splitter基板（1枚） — 「Electronics & Chamber parts」同梱","Stepper Splitterケーブル（1本） — 「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/bf15d3d02fc2065519dce5567666b3d0-800x600.jpg","reveal":["stepperSplitter"],"add":[],"view":"back","verificationRevision":"8f4d8989e1d92a6b"},{"chapter":2,"officialStep":37,"officialId":986069,"chapterSteps":53,"title":"Stepper splitterのケーブルを通す","description":"プリンターを慎重に背面側へ倒します。突き出したWi-Fiユニットに重さをかけないよう、背面を柔らかく高さのある梱包材や空き箱で支えてください。左側の結束バンド3本へStepper splitterケーブルとZ-axis motor Rケーブルを通します。ラベル側は外に残し、結束バンドはまだ締めません。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986069","checks":["Wi-Fiユニットに荷重がかからないよう背面を支えた","2本のケーブルを左の結束バンド3本へ通し、まだ締めていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d5fe0704fec94c670fde62eae412c990-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"7258d1eb3e6c26e4"},{"chapter":2,"officialStep":38,"officialId":986137,"chapterSteps":53,"title":"Stepper splitterを接続する","description":"基板はまだピンに取り付けません。Stepper SplitterケーブルをJ6、Z-axis motor RをJ7、2本のZ-axis motor LをJ1とJ5に接続します。基板の印字と公式写真を照合し、各コネクターをまっすぐ奥まで差し込んでください。","parts":["stepperSplitter","splitterPlugJ6","splitterPlugJ7","splitterPlugJ1","splitterPlugJ5","splitterWires"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986137","checks":["J6・J7・J1・J5の接続先を確認し、4個とも奥まで差し込んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3ac3c5cca5b42efdf38bf49d3aed27f2-800x600.jpg","reveal":["stepperSplitter","splitterPlugJ6","splitterPlugJ7","splitterPlugJ1","splitterPlugJ5","splitterWires"],"add":[],"view":"back","verificationRevision":"d90eed3cb03d3c39","references":[{"label":"公式の端子配置図","url":"https://help.prusa3d.com/article/prusa-core-one-electronics_857793"}]},{"chapter":2,"officialStep":39,"officialId":986187,"chapterSteps":53,"title":"Stepper splitterを固定する","description":"裏面のPRUSAロゴが上下逆になる向きで、基板の2つの穴を底面フレームのピンに合わせます。端子や電子部品を避け、基板の中央を押してカチッと固定してください。押し込むにはある程度の力が必要です。","parts":["stepperSplitter","splitterPlugJ6","splitterPlugJ7","splitterPlugJ1","splitterPlugJ5","splitterWires"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986187","checks":["裏面のロゴは上下逆で、基板が2本のピンに固定されている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/06277236315e9ca1825611737e42591c-800x600.jpg","reveal":["stepperSplitter","splitterPlugJ6","splitterPlugJ7","splitterPlugJ1","splitterPlugJ5","splitterWires"],"add":["stepperSplitter"],"view":"back","verificationRevision":"25ebbfdb98638f68"},{"chapter":2,"officialStep":40,"officialId":986241,"chapterSteps":53,"title":"LCDケーブルを準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics","psu","covers"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986241","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["xLCDケーブル（1本） — 「Electronics & Fasteners」同梱","メインFE接地ケーブル（1本） — 「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/38887625df280ee23f2d80e62cfaaf7c-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"3f3702d6c0fc36f9"},{"chapter":2,"officialStep":41,"officialId":986277,"chapterSteps":53,"title":"LCDケーブルを通す","description":"Stepper splitterケーブルを楕円穴から電子部品側へ通します。xLCDケーブルはQRラベルのある端を軽く折り、底板の楕円穴へ数cm通してください。左の結束バンドに沿わせ、前面プロファイルの四角穴から約6 cm出します。まだ自由に動かせる状態で残してください。","parts":["electronics","psu","covers","splitterZRPlug","splitterWires"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986277","checks":["xLCDケーブルを左側へ通し、前面の四角穴から約6 cm出している"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/194c27d3fa17d6b516b08e8b5ac53e35-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"38729c0c0a9d500b"},{"chapter":2,"officialStep":42,"officialId":986347,"chapterSteps":53,"title":"FEケーブルの注意点","description":"Main FEケーブルを公式写真と同じ形に広げ、各端子の位置を確認します。①～⑤は写真内の参照番号で、次の手順でもこの番号を使います。ケーブルに番号が印刷されているわけではありません。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986347","checks":["写真の参照番号①～⑤と各端子の位置を照合した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/25d0524e0d52bb07e383f3eff935b321-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"b4fdbcb2f7917de5"},{"chapter":2,"officialStep":43,"officialId":986381,"chapterSteps":53,"title":"FEケーブル③を接続する","description":"FEケーブル中央にあるメスFaston端子③を使います。底部右角のオスFaston端子へ、奥まで差し込んでください。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986381","checks":["ケーブル中央のメス端子③が、底部右角のFastonへ奥まで入っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5a15629bb71255a21576281b13e91cfc-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"41adf91f6893022d"},{"chapter":2,"officialStep":44,"officialId":986425,"chapterSteps":53,"title":"FEケーブル②を通す","description":"すぐ近くにある丸形端子②を、底板の穴へ通します。この段階では固定せず、自由に動く状態にしてください。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986425","checks":["丸形端子②を底板の穴に通し、まだ固定していない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f1238260eceee3a3d9644abd4173a08a-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"36ca6570a1c2d892"},{"chapter":2,"officialStep":45,"officialId":986459,"chapterSteps":53,"title":"FEケーブル①を通す","description":"先端にFaston端子が1個だけある長い枝①を、右側の結束バンドへ通します。前面プロファイルの四角穴から端子を約6 cm出し、端子はまだ接続しないでください。右側の結束バンド3本を締め、余りを切ります。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986459","checks":["枝①が前面から約6 cm出ており、右側の結束バンド3本を締めて余りを切った"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e3b27c69f32d3ee4de856c2fbe5ab933-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"05943ec9789fdb1c"},{"chapter":2,"officialStep":46,"officialId":986513,"chapterSteps":53,"title":"FEケーブル④・⑤を通す","description":"FE端子④・⑤を底板の一番左の穴へ通し、まだ接続せずに残します。左側の結束バンド3本を軽く締め、余りを切ってください。後で長さを調整できるよう、ケーブルが動く締め加減にします。最後にプリンターを慎重に脚の上へ戻し、背面を手前に向けます。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986513","checks":["④・⑤を左端の穴に通し、左の結束バンド内でケーブルの長さを調整できる","結束バンドの余りを切り、プリンターを脚の上へ戻した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/952208461d6b29e53020bb07f1938363-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"0677f2777322b59c"},{"chapter":2,"officialStep":47,"officialId":986567,"chapterSteps":53,"title":"xBuddy用FEケーブルを準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics","psu","covers","feGroundRing","feGroundWire","feGroundWasher","feGroundScrew"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986567","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["M3wワッシャー（1枚）","M3x6ネジ（1本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/000a973d8853938b7cd0e1a7786e64d3-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"96ecfde610daeee6"},{"chapter":2,"officialStep":48,"officialId":986601,"chapterSteps":53,"title":"FEケーブルをxBuddyに接続する","description":"FEケーブル④をxBuddyにM3x6で固定し、M3wワッシャーをネジ頭と端子の間に入れます。FE⑤はケースに沿わせ、右側の穴から外へ通してください。Stepper splitterのケーブルもケースに沿わせ、公式写真の向きでxBuddyメイン基板の上段・右から2番目にあるZR端子へ接続します。","parts":["electronics","psu","covers","splitterZRPlug","splitterWires","feGroundRing","feGroundWire","feGroundWasher","feGroundScrew"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986601","checks":["FE④をM3x6で固定し、M3wがネジ頭と端子の間にある","FE⑤がケース右側の穴から外へ出ている","Stepper splitterを上段・右から2番目のZR端子に接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b8542b97ad232a1286520dc6ecf6a768-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"3e339b507fda636d"},{"chapter":2,"officialStep":49,"officialId":986647,"chapterSteps":53,"title":"xLCDケーブルを接続する","description":"ケーブルをxBuddyボックスの右側に沿わせ、結束バンドの下敷きにせず輪の中へ通します。xLCDケーブルを他のケーブルの上から上向きに通し、右側の端子へ接続してください。コネクターのロックは上側です。一番下の結束バンドだけを、配線を傷めない程度に締めて余りを切ります。残り3本はまだ締めません。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986647","checks":["xLCDを他のケーブルの上へ通し、ロックを上にして右側の端子へ接続した","一番下の結束バンドだけを締めて切り、残り3本は緩めたままにしている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ec3b461ad45e4bb0015ad65ba5ccfd8a-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"20f9a91f22851d31"},{"chapter":2,"officialStep":50,"officialId":986717,"chapterSteps":53,"title":"電源カバーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics","psu","covers"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986717","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["電源ユニットカバー（CORE-One-PSU-cover）（1個） — 「Printed parts」同梱","M3x10ネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e70e5303cded2ff1a0250a2ab63e0314-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"91b603f47454b07f"},{"chapter":2,"officialStep":51,"officialId":986751,"chapterSteps":53,"title":"FEケーブルを電源に接続する","description":"FEケーブル②が電源の区画に入っていることを確認します。電源基板のネジを外して保管し、そのネジを端子に通して基板に戻してください。端子を反時計回りに向け、下のネジ穴を空けます。電源カバーをコネクターの上にかぶせ、M3x10を2本使って固定します。","parts":["electronics","psu","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986751","checks":["FE②を元のネジで固定し、下のネジ穴を空けている","電源カバーをコネクターの上にかぶせ、M3x10を2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7a7ead620bfca295b30b9e1e892ae54b-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"ca7f5b590fbc8dc6"},{"chapter":2,"officialStep":52,"officialId":986813,"chapterSteps":53,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの2列目が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["electronics","psu","covers"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986813","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/43c1bd635cda65c4c4893d3209996742-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"ae3947de3fb402f9"},{"chapter":2,"officialStep":53,"officialId":986847,"chapterSteps":53,"title":"背面の組み立てを確認する","description":"背面ユニットの作業はここまでです。未確認の手順がないか見直してから、ヒートベッドの章へ進みます。","parts":["electronics","psu","covers"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-back-assembly_982260#986847","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3c05209a79c2962dbe457274d7d8601e-800x600.jpg","reveal":["electronics","psu","covers"],"add":[],"view":"back","verificationRevision":"1244d7ec7442a18d"},{"chapter":3,"officialStep":1,"officialId":986873,"chapterSteps":40,"title":"この章で使う工具","description":"ラジオペンチ、ユニバーサルレンチ、13–16 mmレンチ、PH2プラスドライバー、2.0 mmと2.5 mmの六角レンチ、T10トルクスを用意します。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":["ラジオペンチ","ユニバーサルレンチ","13–16 mm レンチ","PH2 プラスドライバー","2.5 mm 六角レンチ","2.0 mm 六角レンチ","T10 トルクスレンチ"],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#986873","checks":["ラジオペンチ、ユニバーサルレンチ、13–16 mmレンチ、PH2プラスドライバー、2.0 mmと2.5 mmの六角レンチ、T10トルクスを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3f4de27076a766c3-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"80f85d2df84b2df6"},{"chapter":3,"officialStep":2,"officialId":986949,"chapterSteps":40,"title":"ヒートベッドの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#986949","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["ヒートベッド MK52 24V（1個） — 「CoreXY parts + Hinges set」同梱","ヒートベッドケーブル（赤）（1本） — 「Electronics & Fasteners」同梱","ヒートベッドケーブル（黒）（1本） — 「Electronics & Fasteners」同梱","M3x10rTネジ（2本）","M3nNナット（2個）","M3wワッシャー（2枚）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8d792d3892aac31f3e8e370f3d375d5a-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"6d12b190eba342cc"},{"chapter":3,"officialStep":3,"officialId":987017,"chapterSteps":40,"title":"ベッドのケーブルを組む①","description":"次の手順で固定する前に、ヒートベッドの端子表示と配線色を確認します。公式写真の向きで左にあるGND端子には黒線、VCC端子には赤線を使います。両ケーブルとも、ベッド側に取り付けるラベルのない端を用意してください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987017","checks":["GND用の黒線とVCC用の赤線を確認し、ラベルのない端を用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b11fcdea4e74e89cfcf73a41cba6e3d5-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"fbf57fec70185ee0"},{"chapter":3,"officialStep":4,"officialId":987044,"chapterSteps":40,"title":"ベッドのケーブルを組む②","description":"QRラベルのない黒線の丸端子を、GND端子へ公式写真の向きに置きます。丸端子の上にM3wワッシャーを置き、M3x10rTを通してください。ネジを支えてベッドを慎重に裏返し、裏側からM3nNナットを軽く締めます。赤線も同じ手順でVCCへ取り付けてください。両ケーブルを少し内向きのV字に寄せてから、裏側のナットをしっかり締めます。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987044","checks":["黒線はGND、赤線はVCCに固定した","両端子でM3wがネジ頭と丸端子の間にあり、裏側のM3nNをしっかり締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/66aad0be4768284612822e1b9bb1b980-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"1fd8b3544504797d"},{"chapter":3,"officialStep":5,"officialId":987120,"chapterSteps":40,"title":"ベッドケーブル下カバーを準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987120","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["ベッドケーブルの下側カバー（Bed-cable-cover-bottom）（1個）","M3nナット（3個）","M3x10rTネジ（1本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/81b9e01013ee28dfa9d20f0355a3b80c-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"a487fa8a31b73fe6"},{"chapter":3,"officialStep":6,"officialId":987162,"chapterSteps":40,"title":"ケーブルカバーを取り付ける","description":"Bed-cable-cover-bottomへM3nナット3個を奥まで入れます。入りにくい場合は、ねじで引き込む方法を使ってください。カバーの向きを写真に合わせ、ヒートベッドのケーブル接続部の下へ差し込みます。穴を合わせてM3x10rTで固定してください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987162","checks":["M3nナット3個が奥まで入り、ケーブル接続部の下のカバーをM3x10rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b9297891fbaecc84fbbf13f2b1288d7b-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"2b157298ffbbcdba"},{"chapter":3,"officialStep":7,"officialId":987224,"chapterSteps":40,"title":"ベッドキャリアの部品を準備する","description":"ヒートベッドキャリア1個、Expansion jointを8個、M3x4rを8本用意します。ここではM3x4rTではなくM3x4rを使うので、袋の末尾まで確認してください。","parts":["bedSupport"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987224","checks":["Expansion jointを8個と、M3x4rを8本用意し、rTと区別した"],"supplies":["ヒートベッドキャリッジ（1個） — 「Metal parts 1/3」同梱","エキスパンションジョイント（8個） — 「Electronics」同梱","M3x4rネジ（8本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/795c8f3742cbbab7f3ac8d8b07aeb284-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"c9c6374e7a2718b6"},{"chapter":3,"officialStep":8,"officialId":987278,"chapterSteps":40,"title":"ベッドキャリアを準備する","description":"四角い切り欠きが手前の右側に来るようベッドキャリアを置きます。周囲に六角レンチ用のM3x4rを8本入れ、約3 mmの隙間を残してください。ジョイントの穴にトルクスレンチは入らないため、M3x4rTを使わないでください。","parts":["bedSupport"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987278","checks":["六角レンチ用M3x4rの8本を使い、約3 mmの隙間を残した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ddee1da6f7215f03efda0acb624399a2-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"712054cd7a8bc119"},{"chapter":3,"officialStep":9,"officialId":987322,"chapterSteps":40,"title":"伸縮ジョイントを取り付ける","description":"伸縮ジョイントのU字溝をねじに向け、M3x4rへスライドして掛けます。ユニバーサルレンチの四角い切り欠きでジョイントを保持し、公式図の向きを保ったまま、ジョイントの穴から2 mm六角レンチを入れて締めてください。8か所とも、それぞれの向きを図で確認して取り付けます。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987322","checks":["8個のジョイントを、図の向きを保って固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/cf1ec1e37a81ea949fab2444d7cc13f2-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"e07e999b297b2ace"},{"chapter":3,"officialStep":10,"officialId":987392,"chapterSteps":40,"title":"RGB LEDの部品を準備する","description":"166 mmのRGB LEDストリップを用意します。LEDと抵抗には直接触れないでください。LED status coverはElectronics & Chamber parts箱内の「Others」袋に入っています。ディフューザー、スペーサー2個、M3x10rTを2本、結束バンド3本も用意します。","parts":["bedSupport"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987392","checks":["LEDと抵抗に触れずに、166 mmストリップとカバーを含む部品を用意した"],"supplies":["RGB LEDストリップ 166 mm（1本） — 「Electronics & Fasteners」同梱","ステータスLEDカバー（1個） — 「Electronics & Chamber parts」内の「Others」袋","LEDストリップの拡散カバー（1個） — 「CoreXY parts + Hinges set」同梱","スペーサー 3.2/6x5 mm（2個） — 「Electronics & Fasteners」同梱","M3x10rTネジ（2本）","結束バンド（3本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/bba434d1bd525694f7b4dfc3b518feda-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"cd3cb85b54dce578"},{"chapter":3,"officialStep":11,"officialId":987470,"chapterSteps":40,"title":"LEDストリップを取り付ける","description":"四角い切り欠きが奥の右側に来るようキャリアを置きます。RGB LEDストリップの保護紙を剥がし、前側の折り曲げ端から約3 mmの位置へ均等に貼ってください。中央のLEDをキャリアのねじに合わせ、ケーブルは右へ向けます。押さえるのは部品のない部分だけにし、LEDや抵抗には触れないでください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987470","checks":["中央LEDをねじに合わせ、折り曲げ端から約3 mm、ケーブルを右向きに貼った"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6808facf348e03ff17c8f69dab95e386-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"aaad052a4b75d458"},{"chapter":3,"officialStep":12,"officialId":987540,"chapterSteps":40,"title":"LEDのディフューザーを取り付ける","description":"面取りされた端を目印に向きを合わせ、RGB LEDストリップの上へディフューザーを載せます。両端の穴に3.2/6x5 mmスペーサーを1個ずつ置いてください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987540","checks":["ディフューザーの向きを確認し、両端にスペーサーを置いた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d9531014e7e45ee9d51e70fa5f5572e6-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"2539474216d34ff8"},{"chapter":3,"officialStep":13,"officialId":987568,"chapterSteps":40,"title":"RGB LEDにカバーを付ける","description":"LEDカバーの両面の保護フィルムを剥がします。つや消し面を上にして載せ、M3x10rTの2本で固定してください。カバーが割れないよう締めすぎないでください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987568","checks":["両面のフィルムを剥がし、つや消し面を上にして2本を締めすぎず固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a4fe4b414e15cfb2b61ea9ea77565748-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"aae5aaae7e9f94a6"},{"chapter":3,"officialStep":14,"officialId":987620,"chapterSteps":40,"title":"RGB LEDケーブルを通す","description":"ベッドキャリア右側の3か所へ、ロック部が外向きになるよう結束バンドを通します。RGB LEDケーブルを3本すべての輪へ通し、締めて余りを切ってください。","parts":["bedSupport"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987620","checks":["右側の結束バンド3本はロック部が外向きで、LEDケーブルを固定して余りを切った"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a4d025ddf80001da20ad71fbec1a0faa-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"99ec5044126ab455"},{"chapter":3,"officialStep":15,"officialId":987658,"chapterSteps":40,"title":"ベッドマウントの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["bedSupport"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987658","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["左ベッドマウント（CORE-One-bed-mount-left）（1個） — 「Printed parts」同梱","右ベッドマウント（CORE-One-bed-mount-right）（1個） — 「Printed parts」同梱","後部ベッドスペーサー（CORE-One-bed-spacer-rear）（1個） — 「Printed parts」同梱","LM8UU ベアリング（2個） — 「Electronics」同梱","M3x10ネジ（6本）","M3nナット（2個）","M3nNナット（10個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a58821e757a709acc81b21fe03c7dc08-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"34298cc2eadad28f"},{"chapter":3,"officialStep":16,"officialId":987742,"chapterSteps":40,"title":"ベッドマウントを組み立てる","description":"CORE-One-bed-mount-leftをベアリングに合わせ、公式写真で向きを確認します。部品がはまる感触があるまで奥へ押し付け、ベアリングが全体に収まって突き出していないことを確認してください。入りにくい場合は、マイナスドライバーでマウントの開口を慎重に広げます。右側のマウントも同じ手順で組みます。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987742","checks":["左右のベアリングが奥まで入り、突き出していない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0cf70b20d53558eb20cdec037e7cba49-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"7a1707f80377c127"},{"chapter":3,"officialStep":17,"officialId":987786,"chapterSteps":40,"title":"ベッドマウントを固定する","description":"左ベッドマウントへM3nナットを入れ、ベアリングのボール列2列が部品の底側へ向くよう置きます。1列だけが底を向く向きにしないでください。ベアリング上面と樹脂部品上面をそろえ、M3x10で固定します。右ベッドマウントも同じように組み立ててください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987786","checks":["左右ともボール列2列が底側を向いている","ベアリングと樹脂部品の上面をそろえ、左右ともM3x10で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/46ce94bc4b0e4445e6a50aab64f8f6d0-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"e49816209de2aa15"},{"chapter":3,"officialStep":18,"officialId":987848,"chapterSteps":40,"title":"ベッドマウントにナットを入れる","description":"左右のベッドマウントへM3nNナットを4個ずつ、合わせて8個入れます。すべて部品の奥まで押し込んでください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987848","checks":["左右それぞれM3nNナット4個、計8個を奥まで入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/44b73bcd333c8cb0-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"4a5d7b8a1b670ae6"},{"chapter":3,"officialStep":19,"officialId":987874,"chapterSteps":40,"title":"後方ベッドスペーサーを組み立てる","description":"CORE-One-bed-spacer-rearへM3nNナット2個を入れ、奥まで押し込んでください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987874","checks":["後方スペーサーのM3nNナット2個が奥まで入っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1b197e1f2bc07e57499f715b2c3f3a05-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"8482ce0852165480"},{"chapter":3,"officialStep":20,"officialId":987900,"chapterSteps":40,"title":"右ベッドマウントを取り付ける","description":"ベッドキャリアのフォークを手前、伸縮ジョイントを上にします。右フォークの下へ右ベッドマウントを差し込み、ベアリングが右側に来る向きでM3x10の2本を締めてください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987900","checks":["右フォークの下でベアリングが右側にあり、M3x10の2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d42c2c8b031cf35a72831d17f780b4a5-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"7886929bcc90610d"},{"chapter":3,"officialStep":21,"officialId":987938,"chapterSteps":40,"title":"左ベッドマウントを取り付ける","description":"左フォークの下へ左ベッドマウントを差し込み、ベアリングが左側に来る向きにします。M3x10の2本で固定してください。","parts":["bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987938","checks":["左フォークの下でベアリングが左側にあり、M3x10の2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5d22878e416c301b8b38564980a5ac2d-800x600.jpg","reveal":["bedSupport"],"add":[],"verificationRevision":"99f02d9eb4499778"},{"chapter":3,"officialStep":22,"officialId":987966,"chapterSteps":40,"title":"ベッド固定用の部品を準備する","description":"皿ねじM3x12bTを1本、スペーサー6x3.1x8 mmを1個、皿ねじM3x4bTを8本用意します。12 mmねじの袋は「M3x12cT」と表記されている場合があります。スペーサーはElectronics箱内のNextruder assemblyに入っています。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#987966","checks":["12 mm皿ねじ1本、スペーサー1個、4 mm皿ねじ8本を用意した"],"supplies":["M3x12bT皿ネジ（1本）","スペーサー 6x3.1x8 mm（1個） — 「Electronics」内の「Nextruder assembly」パッケージ","M3x4bT皿ネジ（8本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ded5fd01c2c9f44581ee3f6b2cae5e46-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"33ca53f16113a479"},{"chapter":3,"officialStep":23,"officialId":988016,"chapterSteps":40,"title":"ヒートベッドを取り付ける","description":"伸縮ジョイントがある面の中央穴にスペーサーを合わせ、ケーブル位置を目印にヒートベッドを載せます。中央のM3x12bTはまだ本締めしないでください。最も細いサーミスター線を電源ケーブルに沿わせ、ジョイントの周りや上を横切らないようにします。残りの穴へM3x4bTを入れ、こちらも仮締めにしてください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988016","checks":["中央のM3x12bTと周囲のM3x4bTは、まだ本締めしていない","サーミスター線は電源線に沿い、伸縮ジョイントを横切っていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9f274cfd36ff7b03b8d1b05b9a050aa4-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"8144aaf07518d990"},{"chapter":3,"officialStep":24,"officialId":988070,"chapterSteps":40,"title":"ヒートベッドのネジを締める","description":"中央の1本、辺の4本、四隅の4本の順に締めます。この順番で少しずつ均等に締め、2周以上繰り返した後、同じ順番で最終締めをしてください。最後は軽く、確実に締めます。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988070","checks":["中央→辺→四隅の順を2周以上繰り返した後、同じ順番で軽く確実に最終締めした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ac5a4120c0b4799ef7af959921e93cdd-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"531e8bee93f06a76"},{"chapter":3,"officialStep":25,"officialId":988128,"chapterSteps":40,"title":"ケーブルを覆う部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988128","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["ベッドケーブルの上側カバー（CORE-One-bed-cable-cover-top）（1個） — 「Printed parts」同梱","M3x10ネジ（2本）","布スリーブ 520 x 8 mm（1本） — 「Electronics & Chamber parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4ab155024e0045309f9900792cf799e4-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"0836176130ecd078"},{"chapter":3,"officialStep":26,"officialId":988172,"chapterSteps":40,"title":"ベッドのケーブルを通す","description":"RGB LEDケーブルを下から四角い切り欠きへ通し、上へ引き出します。サーミスター線はRGB LEDケーブルの下へ通してカバーの溝へ入れ、続いてRGB LEDケーブル、最後にヒートベッド電源線を溝へ収めてください。","parts":["heatbed"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988172","checks":["サーミスター線をLEDケーブルの下へ通し、サーミスター・LED・電源線の順に溝へ収めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/202b54166483af4aef4b7722ac536c9e-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"b8b759ae5f98fb5f"},{"chapter":3,"officialStep":27,"officialId":988218,"chapterSteps":40,"title":"ベッドのケーブルを覆う","description":"ケーブル束へ布スリーブを約5 cmかぶせ、端をカバーの溝へ1 cm差し込みます。スリーブを引っ張らず、その位置を保ったまま上カバーを載せ、M3x10の2本で固定してください。残りのスリーブもケーブル束に巻きます。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988218","checks":["スリーブ端が溝に1 cm入り、M3x10の2本で上カバーを固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/952d510bf9ce831d819c3f3abda5b408-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"1675b26099d5ede6"},{"chapter":3,"officialStep":28,"officialId":988272,"chapterSteps":40,"title":"ベッドユニット取り付けの準備","description":"台形ナットを3個、M3x18を6本用意します。台形ナットはモーターの箱に2個、Electronics & Chamber parts箱に1個入っています。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988272","checks":["箱2か所から台形ナットを計3個取り出し、M3x18を6本用意した"],"supplies":["台形ナット（3個）","M3x18ネジ（6本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/54e0280cf3844855ba084b9e28b261fd-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"e708633f8d139097"},{"chapter":3,"officialStep":29,"officialId":988314,"chapterSteps":40,"title":"ベッドユニットを取り付ける","description":"プリンターの前を手前にし、後方モーターのねじ頭へCORE-One-bed-spacer-rearを載せます。穴の向きを写真と合わせ、ずれないようにしてください。ヒートベッド一式をZモーターのねじ棒へ慎重に通し、ベースへ静かに下ろします。ケーブル束はスペーサーやモーターに掛けず、ヒートベッドの下から後方モーターの後ろへ通します。","parts":["heatbed","bedSupport"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988314","checks":["後方スペーサーがずれておらず、ケーブル束はベッドの下から後方モーターの後ろへ通っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e3025a7348dcbf787b1f1ae46fb31464-800x600.jpg","reveal":["heatbed"],"add":["bedSupport","heatbed"],"verificationRevision":"5973ee6595781a7b"},{"chapter":3,"officialStep":30,"officialId":988376,"chapterSteps":40,"title":"後方モーター側を固定する","description":"ねじ棒が正しい穴を通り、ケーブル束がベッドの下から後方ねじ棒の後ろへ通っていることを確認します。台形ナットの突き出た側を下にし、後方ねじ棒へ手で回してキャリアに着くまで下げてください。ナット・キャリア・後方スペーサーの穴を合わせ、M3x18の2本で固定します。穴合わせには1.5 mm六角レンチを通して使えます。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988376","checks":["後方ナットの突き出た側が下を向き、ナット・キャリア・スペーサーをM3x18の2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/737b62e4bc0d28f8ed83d479502b15d0-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"3044515ca7e68a7c"},{"chapter":3,"officialStep":31,"officialId":988454,"chapterSteps":40,"title":"左前モーター側を固定する","description":"左前の台形ナットを突き出た側が下になるよう手で回し、樹脂部品に着くまで下げます。穴を合わせてM3x18の2本で固定してください。締めた後は2本とも¼回転戻し、少し動ける余裕を残します。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988454","checks":["左前ナットは突き出た側が下で、M3x18の2本を締めた後に各¼回転戻した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/817f91b3b500698d4300e490bbb467e5-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"280fefbf61ad8379"},{"chapter":3,"officialStep":32,"officialId":988500,"chapterSteps":40,"title":"右前モーター側を固定する","description":"右前の台形ナットを突き出た側が下になるよう手で回し、樹脂部品に着くまで下げます。使う穴の組はどちらでも構いません。穴を合わせてM3x18の2本で固定してください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988500","checks":["右前ナットは突き出た側が下で、M3x18の2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/037e8afc2b271f0617e37ae71f871712-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"e4ffd2e54be69b9f"},{"chapter":3,"officialStep":33,"officialId":988546,"chapterSteps":40,"title":"ベッドのケーブルを取り付ける①","description":"背面一式の右上にあるグロメット穴へ、最初にRGB LEDケーブル、次にサーミスター線、最後に電源線2本を通してください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988546","checks":["右上のグロメットへLED・サーミスター・電源線2本の順に通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/830c35c1819bd7992e8e22ab70f8089e-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"26633b0bcae74c5b"},{"chapter":3,"officialStep":34,"officialId":988592,"chapterSteps":40,"title":"ベッドのケーブルを取り付ける②","description":"ヒートベッドのケーブル束と布スリーブをグロメットへ通します。背面側へ出るスリーブは1 cm以内にしてください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988592","checks":["背面側へ出ている布スリーブは1 cm以内になっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1823c67835d8e869472fbf8b8503bcbb-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"4e41d83235140d57"},{"chapter":3,"officialStep":35,"officialId":988620,"chapterSteps":40,"title":"ケーブル固定部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["heatbed"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988620","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["結束バンド（1本）","電源端子ネジ 6-32（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b096dcac9733f9c0c6ef367d3229350d-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"2d8c57ae138302f9"},{"chapter":3,"officialStep":36,"officialId":988654,"chapterSteps":40,"title":"布スリーブを固定する","description":"ヒートベッドケーブルの下にある2つの穴へ結束バンドを通し、内側で布スリーブごとケーブル束を囲みます。しっかり締め、余りを切ってください。","parts":["heatbed"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988654","checks":["内側で布スリーブごと束を結束し、余りを切った"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3a215114634e9c85d3a95ad7c5b74fcb-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"f9c05f9996a99b86"},{"chapter":3,"officialStep":37,"officialId":988682,"chapterSteps":40,"title":"ベッドユニットのケーブルを通す","description":"RGB LEDケーブルをxBuddyボックス左の穴へ通し、拡張基板の右から1番目にある「RGBW LED」端子へ接続します。ヒートベッド電源線とサーミスター線も左の穴へ通し、こちらはまだ接続せず残してください。","parts":["heatbed"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988682","checks":["LEDを拡張基板の右端「RGBW LED」へ接続し、電源線とサーミスター線も左穴へ通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a514648bf5464f5f0db1859d75f73c31-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"167dbe1c2aeff128"},{"chapter":3,"officialStep":38,"officialId":988720,"chapterSteps":40,"title":"ベッドの電源ケーブルを接続する","description":"ヒートベッドの配線が結束バンドの上をまたがず、その下に収まっていることを確認します。公式写真の向きで、黒の電源線を左の端子、赤を右の端子へ、それぞれ6-32端子ねじでしっかり固定してください。サーミスターのコネクターは、電源端子の隣へ差し込みます。","parts":["heatbed"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988720","checks":["写真の向きで黒が左・赤が右の電源端子に付き、両方の端子ねじをしっかり締めた","サーミスターを電源端子の隣へ接続し、配線は結束バンドの下に収まっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8e48c270b5a510de366a3fb10233106c-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"1070e49f3c6d81f1"},{"chapter":3,"officialStep":39,"officialId":988766,"chapterSteps":40,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの3列目とおまけ1個が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["heatbed"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988766","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c8d86d99210385c4ab293abdb7f68885-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":3,"officialStep":40,"officialId":988800,"chapterSteps":40,"title":"ヒートベッドの組み立てを確認する","description":"ヒートベッドの組み立てと取り付けはここまでです。未確認の手順がないか見直してから、CoreXYの章へ進みます。","parts":["heatbed"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/4-heatbed-assembly_982268#988800","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d808cc83276bddede8e35dc5caa0e954-800x600.jpg","reveal":["heatbed"],"add":[],"verificationRevision":"1244d7ec7442a18d"},{"chapter":4,"officialStep":1,"officialId":988826,"chapterSteps":83,"title":"この章で使う工具","description":"ラジオペンチ、2.0 mmと2.5 mmの六角レンチ、T10トルクスを用意します。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":["ラジオペンチ","2.0 mm 六角レンチ","2.5 mm 六角レンチ","T10 トルクスレンチ／ドライバー"],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#988826","checks":["ラジオペンチ、2.0 mmと2.5 mmの六角レンチ、T10トルクスを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3f4de27076a766c3-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"fb60dba637302bba"},{"chapter":4,"officialStep":2,"officialId":988878,"chapterSteps":83,"title":"ロッドホルダーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#988878","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["左ロッドホルダー（1個） — 「CORE XY parts + hinges + HB set」同梱","右ロッドホルダー（1個） — 「CORE XY parts + hinges + HB set」同梱","後ろロッドホルダー（2個） — 「CORE XY parts + hinges + HB set」同梱","M3x10ネジ（6本）","M3x6ネジ（4本）","CoreXYプレート（1枚） — 「Metal parts 1/3」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a0de30f9345c5ccabbf9d8aecdb61308-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"ea38b11157bdbc61"},{"chapter":4,"officialStep":3,"officialId":988946,"chapterSteps":83,"title":"ロッドホルダーを組み立てる","description":"左右の前ロッドホルダーへM3x10を2本ずつ入れます。後ろの各ホルダーには、ねじ頭を収める穴のある側から1本ずつ入れてください。すべて数回転だけ入れ、まだ締め切りません。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#988946","checks":["前の左右は各2本、後ろは各1本のM3x10を仮止めした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b3666f2e66cfc4b5ad666013f83270c5-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"b326080f471b55f3"},{"chapter":4,"officialStep":4,"officialId":988990,"chapterSteps":83,"title":"前方ロッドホルダーを準備する","description":"CoreXY板の折り曲げ部を上にします。面取りを目印にRod holder leftとRod holder rightを見分け、前側の左右へ写真どおりに用意してください。","parts":["xy"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#988990","checks":["折り曲げ部を上にし、面取りで左右の前ロッドホルダーを見分けた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9b398822d8260ea235398a5dd1b6c1a3-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"70aa3d9f5de25248"},{"chapter":4,"officialStep":5,"officialId":989042,"chapterSteps":83,"title":"前方ロッドホルダーを取り付ける","description":"左前のねじ穴へRod holder left、右前へRod holder rightを合わせ、各M3x6の2本で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989042","checks":["左右それぞれの前ホルダーをM3x6の2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a6da24d52a95e45fb485c070e302c8e3-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"a3d0101abba60be6"},{"chapter":4,"officialStep":6,"officialId":989086,"chapterSteps":83,"title":"XYキャリッジの部品を準備する","description":"左右の金属ホルダーを1個ずつ、XY-carriageを2個、LM10LUUを2個、GT2-20アイドラーを4個用意します。ねじは黒いM3x8rTを8本とM3x18を10本です。XY-carriageは外観が違う版でも、この手順の組み方は同じです。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989086","checks":["XY-carriageを2個含む部品一式と、指定のねじ8本・10本を用意した"],"supplies":["左リニアホルダー（1個） — 「Metal parts 1/3」同梱","右リニアホルダー（1個） — 「Metal parts 1/3」同梱","XYキャリッジ（XY-carriage）（2個） — 「Printed parts」同梱。外観が異なる場合も、組み立て方は同じです","LM10LUU リニアベアリング（2個） — 「CORE XY parts + hinges + HB set」同梱","GT2-20 アイドラープーリー（4個） — 「Electronics & Fasteners」同梱","M3x8rTネジ（黒）（8本）","M3x18ネジ（10本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/aa744dde6f6dfc12f3dde4c2c68aa7ca-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"0d121ea2844eb674"},{"chapter":4,"officialStep":7,"officialId":989162,"chapterSteps":83,"title":"XYキャリッジを組み立てる","description":"XY-carriageの面取り側を目印に、公式写真の向きへ合わせます。GT2-20アイドラープーリーを入れ、M3x18を通してしっかり締めてください。部品を裏返し、反対側のプーリーもM3x18でしっかり固定します。もう1個のXY-carriageも同じ手順で組みます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989162","checks":["両キャリッジの向きを面取りで確認し、各両側のプーリーをM3x18でしっかり固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6b73d0f68860043436decbab4fe9dca5-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"89db95a23f2de17b"},{"chapter":4,"officialStep":8,"officialId":989230,"chapterSteps":83,"title":"左リニアホルダーを組み立てる","description":"左リニアホルダーを写真の向きに置き、XYキャリッジをM3x18の3本で固定します。裏返し、キャリッジ側からLM10LUUベアリングを載せ、M3x8rTの4本で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989230","checks":["左ホルダーのキャリッジをM3x18の3本、ベアリングをM3x8rTの4本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/021814737230ee7d7d68eace1a078878-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"bb2b8b0e59f0197b"},{"chapter":4,"officialStep":9,"officialId":989284,"chapterSteps":83,"title":"右リニアホルダーを組み立てる","description":"右リニアホルダーを写真の向きに置き、XYキャリッジをM3x18の3本で固定します。裏返し、キャリッジ側からLM10LUUベアリングを載せ、M3x8rTの4本で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989284","checks":["右ホルダーのキャリッジをM3x18の3本、ベアリングをM3x8rTの4本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ef2efeaf3a42462d976989f118fc842a-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"b9548fa12acded40"},{"chapter":4,"officialStep":10,"officialId":989338,"chapterSteps":83,"title":"リニアホルダーを取り付ける","description":"前ロッドホルダーが上に来るようCoreXY板を置き、板を少し持ち上げて内側から左右のリニアホルダー一式を掛けます。この段階では、どちらも載っているだけの仮置きです。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989338","checks":["左右を正しい側へ内側から仮置きした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/637d81ac8ad07de13f5bba00462cf2f3-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"2f2d0f8c57cd0ffa"},{"chapter":4,"officialStep":11,"officialId":989388,"chapterSteps":83,"title":"スムースロッドの注意点","description":"スムースロッドには330x8 mmと325x10 mmの2種類があります。次の手順では太い325x10 mmを2本使います。M3x6の4本も用意してください。細い330x8 mmと取り違えないようにします。","parts":["xy"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989388","checks":["325x10 mmの太いロッド2本とM3x6の4本を用意した"],"supplies":["スムーズロッド 330 x 8 mm（2本）","スムーズロッド 325 x 10 mm（2本） — 後の手順で使用","M3x6ネジ（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2bb5e54761100ebc17d1884bffd0b98b-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"0c89d36fee787c98"},{"chapter":4,"officialStep":12,"officialId":989448,"chapterSteps":83,"title":"スムースロッドを取り付ける","description":"直径10 mmロッドへ後ろホルダーを1個ずつ通し、端をそろえます。ロッドをLM10LUUベアリングから前ホルダーへ通し、前端もホルダーへ合わせてください。後ろホルダーのねじはフレームの外側を向けます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989448","checks":["2本のロッドがベアリングと前後ホルダーを通り、後ろのねじが外側を向いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2edebf3d868ccc1ce7feb742d312c0cf-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"74dcf22bac2dfeeb"},{"chapter":4,"officialStep":13,"officialId":989500,"chapterSteps":83,"title":"後方ロッドホルダーを固定する","description":"左後ろホルダーを板のねじ穴に合わせ、M3x6の2本で固定します。ホルダー内のロッド固定ねじもしっかり締めてください。右後ろも同じように、取付ねじ2本とロッド固定ねじを締めます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989500","checks":["後ろの各ホルダーをM3x6の2本で留め、それぞれのロッド固定ねじも締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0db79c39e702639cc90fcd2e5669c910-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"5b805a291e4f9d16"},{"chapter":4,"officialStep":14,"officialId":989560,"chapterSteps":83,"title":"前方ロッドホルダーを固定する","description":"前の左右ホルダーで、ロッドを留めるねじを締めます。公式写真の作業姿勢では左前が右に、右前が左に見えます。どちらのホルダーも下側のねじはまだ締めないでください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989560","checks":["前のロッド固定ねじを左右とも締め、下側のねじは両方とも締めていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/beffedea71d9671a572973263e1156cc-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"dcf9b6ba45c4c407"},{"chapter":4,"officialStep":15,"officialId":989604,"chapterSteps":83,"title":"モーターマウントの部品を準備する①","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989604","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["左XYモーターマウント（XY-motor-mount-left）（1個） — 「Printed parts」同梱","右XYモーターマウント（XY-motor-mount-right）（1個） — 「Printed parts」同梱","組み立て用マルチツール（Assembly-multi-tool）（1個） — 前の手順で使ったもの","M3x30ネジ（2本）","M3x18ネジ（2本）","スペーサー 3.2/6x2（2個） — 「Electronics & Fasteners」内の「Small parts & fasteners」袋","M3nSナット（1個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/808a3ab4a182957dbba8cb3b8677382a-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"8788a7b246b98f83"},{"chapter":4,"officialStep":16,"officialId":989688,"chapterSteps":83,"title":"モーターマウントの部品を準備する②","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989688","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["GT2-20 アイドラープーリー（6個） — 「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/59388950f13ede970a72a7554195cde4-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"5003d3818e570bf6"},{"chapter":4,"officialStep":17,"officialId":989706,"chapterSteps":83,"title":"右XYモーターマウントを組む①","description":"Assembly-multi-toolの下側へプーリーを入れ、spacer 3.2、2個目のプーリーの順に重ねます。面取り角を写真と合わせ、一式をXY-motor-mount-rightへ入れてください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989706","checks":["右マウントへ、プーリー・spacer 3.2・プーリーの順に入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1ed8bad953284e48-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"95e86252abdc3ac5"},{"chapter":4,"officialStep":18,"officialId":989784,"chapterSteps":83,"title":"右XYモーターマウントを組む②","description":"穴を合わせ、M3x30をゆっくり締めます。樹脂にねじ山を作るため抵抗がありますが、頭がマウントに着いたら止めてください。工具を外し、追加のプーリーをM3x18で締めすぎず固定します。右マウントへM3nS角ナットも入れてください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989784","checks":["M3x30は頭が着いた位置で止め、追加プーリーをM3x18で留め、M3nSも入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/79c01984bd79ecc5430db63fb37631f9-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"74da451b6fd818da"},{"chapter":4,"officialStep":19,"officialId":989828,"chapterSteps":83,"title":"左XYモーターマウントを組む①","description":"Assembly-multi-toolの下側へプーリー、spacer 3.2、2個目のプーリーを重ねます。ねじ穴の隣の面取りを目印に、一式をXY-motor-mount-leftへ入れてください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989828","checks":["左マウントへ、面取りを確認してプーリー・spacer 3.2・プーリーを入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/33b57b2e51fe19b1a76ec648244d75ca-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"1cfa51027eb0cc4a"},{"chapter":4,"officialStep":20,"officialId":989906,"chapterSteps":83,"title":"左XYモーターマウントを組む②","description":"M3x30をゆっくり締め、樹脂にねじ山を作ります。頭がマウントに着いたら止め、締めすぎないでください。工具を外し、追加のプーリーをM3x18で固定します。こちらも締めすぎないようにします。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989906","checks":["左マウントのM3x30を頭の接触で止め、追加プーリーをM3x18で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/d92d7aa2799404c370cfa731e7f11f94-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"eef8e542bc82a2e7"},{"chapter":4,"officialStep":21,"officialId":989942,"chapterSteps":83,"title":"ベルトテンショナーの部品を準備する①","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#989942","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["GT2-20 アイドラープーリー（2個） — 「Electronics」同梱","M3x30ネジ（2本）","M3x18ネジ（2本）","M3x12ネジ（1本）","M3nSナット（2個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/37abb28ced3b3b79c1f91bd94e6319da-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"14d340bd61a078a1"},{"chapter":4,"officialStep":22,"officialId":990008,"chapterSteps":83,"title":"ベルトテンショナーの部品を準備する②","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990008","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["左ベルトテンショナー（Belt-tensioner-left）（1個） — 「Printed parts」同梱","右ベルトテンショナー（Belt-tensioner-right）（1個） — 「Printed parts」同梱","ベルトテンショナー用プーリー（Belt-tensioner-pulley）（2個） — 「Printed parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8143ecd488cdbdd02e53717658a7a417-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"55671da128a4a18c"},{"chapter":4,"officialStep":23,"officialId":990050,"chapterSteps":83,"title":"テンショナーのプーリーを準備する","description":"Belt-tensioner-pulleyの2個へ、M3nS角ナットを1個ずつ入れます。ナットのねじ穴と部品の穴が合う位置まで押してください。","parts":["xy"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990050","checks":["2個のナットが各部品の穴と合っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b5c451588a02adfd-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"0a353215ebc92d79"},{"chapter":4,"officialStep":24,"officialId":990084,"chapterSteps":83,"title":"左ベルトテンショナーを組む①","description":"未開封の潤滑剤はキャップを外し、キャップ裏側の突起でチューブの口を開けます。左右で使うM3x30の2本に少量のPrusa潤滑剤を付け、ねじ山全体へ薄く広げます。結束バンドの先で塗り広げられます。写真の向きで左テンショナーとプーリーホルダーを重ね、M3x30を3～4回転だけ入れてください。まだ締め切りません。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990084","checks":["M3x30の2本を潤滑し、左テンショナーは3～4回転の仮止めにした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d21b8675aeb284b32a2036865a125f7e-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"627d35a2bb02e9f1"},{"chapter":4,"officialStep":25,"officialId":990146,"chapterSteps":83,"title":"左ベルトテンショナーを組む②","description":"GT2-20アイドラープーリーを入れ、M3x18で固定します。ねじが樹脂へねじ山を作るため、少し抵抗があります。左テンショナーのM3x12は約5回転だけ入れ、反対側へ突き出さないようにしてください。このねじは後でドアセンサーの調整に使います。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990146","checks":["プーリーをM3x18で留め、M3x12は約5回転で反対側へ出ていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/32d4d6887850150fea1b50cfe626cd07-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"dca83646c42dbda1"},{"chapter":4,"officialStep":26,"officialId":990198,"chapterSteps":83,"title":"右ベルトテンショナーを組む","description":"右テンショナーをプーリーホルダーへ写真の向きで重ね、先ほど潤滑したM3x30を3～4回転だけ入れます。GT2-20アイドラープーリーを入れ、M3x18で固定してください。M3x30はまだ締め切りません。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990198","checks":["右プーリーをM3x18で留め、M3x30は3～4回転だけ入れている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/bf22e7d8fe7ff857af55004f11d356bf-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"ee7db7312b6915e5"},{"chapter":4,"officialStep":27,"officialId":990260,"chapterSteps":83,"title":"テンショナー取り付け部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990260","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["M3x30ネジ（5本）","M3x18ネジ（1本）","M3x6ネジ（2本）","組み立て済みの左ベルトテンショナー（1組） — 前の手順で組み立てたもの","組み立て済みの右ベルトテンショナー（1組） — 前の手順で組み立てたもの"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6c9dc17f4fda44fb41c034d7925f9f4d-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"fffe6cefda1c1f94"},{"chapter":4,"officialStep":28,"officialId":990320,"chapterSteps":83,"title":"左モーターマウントを取り付ける","description":"裏側にFaston端子がある角を確認します。左モーターマウントの四角い突起をCoreXY板の切り欠きへ合わせ、板の下へ差し込んでください。指定の穴をM3x6で固定します。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990320","checks":["左マウントの四角い突起が切り欠きに入り、板の下でM3x6により固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/976173e2936390d6409b52025dbf2c25-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"c55b08897d276435"},{"chapter":4,"officialStep":29,"officialId":990374,"chapterSteps":83,"title":"右モーターマウントを取り付ける","description":"右モーターマウントの四角い突起をCoreXY板の切り欠きへ合わせ、板の下へ差し込みます。指定の穴をM3x6で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990374","checks":["右マウントの四角い突起が切り欠きに入り、板の下でM3x6により固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5276cf25e9dcbfb81f59a7a48291de27-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"9f0fcd42b02a9417"},{"chapter":4,"officialStep":30,"officialId":990420,"chapterSteps":83,"title":"左ベルトテンショナーを取り付ける","description":"CoreXYを裏返して折り曲げ部を下へ向けます。左前のテンショナーを前縁と内側の縁へ合わせ、M3x30の2本とM3x18の1本で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990420","checks":["左テンショナーを前縁・内縁へ合わせ、M3x30の2本とM3x18の1本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e70598718dc44893ae09432a46690ec1-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"d45e165c4c5a7e49"},{"chapter":4,"officialStep":31,"officialId":990472,"chapterSteps":83,"title":"右ベルトテンショナーを取り付ける","description":"右テンショナーを右前の角へ置き、前縁と内側の縁に合わせます。こちらはM3x30の3本で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990472","checks":["右テンショナーを前縁・内縁へ合わせ、M3x30の3本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8d42ac5d22b219c883a257aeece54c31-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"b5bd6f9ccb90bd75"},{"chapter":4,"officialStep":32,"officialId":990508,"chapterSteps":83,"title":"リニアレールの部品を準備する","description":"リニアレール、レールビーム、M3x6を6本用意します。キャリッジの脱落防止ピンは、手順で指示されるまで絶対に外さないでください。防錆油を拭くための布かペーパータオルも用意します。","parts":["gantry"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990508","checks":["脱落防止ピンを付けたまま、レール一式、M3x6を6本、拭き取り用の布を用意した"],"supplies":["M3x6ネジ（6本）","リニアレール用ビーム（1本） — 「Metal parts 3/3」同梱","リニアレール（1本） — 「Electronics & Chamber parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2ad26a096878a9b11a90310c0d9235e6-800x600.jpg","reveal":["gantry"],"add":[],"verificationRevision":"daadbfbde12ce58e"},{"chapter":4,"officialStep":33,"officialId":990566,"chapterSteps":83,"title":"リニアレールを取り付ける","description":"レールの脱落防止ピンは、後の指示まで外しません。梱包から出したら保存用の油をペーパータオルで拭き、レールとビームの穴を合わせます。キャリッジを中央付近へ動かし、両端から3番目の穴へM3x6を2本入れて軽く締めてください。","parts":["gantry"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990566","checks":["脱落防止ピンを残し、両端から3番目の穴のM3x6を軽く締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7c318ede0a30c00c43f7d3c8850d7ee7-800x600.jpg","reveal":["gantry"],"add":[],"verificationRevision":"eca3624238a59d02"},{"chapter":4,"officialStep":34,"officialId":990620,"chapterSteps":83,"title":"リニアレールを固定する","description":"この手順では、リニアキャリッジを動かさないでください。安全ピンをラジオペンチで軽くつまんで抜き、レールの両端から4番目の穴へ移します。両端から5番目の穴にM3x6を各1本、続いて1番目の穴にも各1本入れ、4本とも軽く締めるだけにしてください。移した安全ピンは、後の取り外し指示まで付けたままにします。","parts":["gantry"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990620","checks":["キャリッジを動かさずに安全ピンを移し、両端から4番目の穴に残している","両端から1番目と5番目の穴に入れたM3x6の4本は、軽く締めるだけにした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8f0ce1f86bc8c05c6ddb95862f2e5d80-800x600.jpg","reveal":["gantry"],"add":[],"verificationRevision":"f1c07d136009dc37"},{"chapter":4,"officialStep":35,"officialId":990680,"chapterSteps":83,"title":"レールユニットの取り付けを準備する","description":"組み立てたリニアレールユニットとM3x8rTを6本用意します。同じ長さのM3x8と取り違えないでください。キャリッジの脱落防止ピンは、まだ外しません。","parts":["gantry"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990680","checks":["M3x8rTを6本選び、脱落防止ピンを付けたままにした"],"supplies":["M3x8rTネジ（6本）","組み立て済みのリニアレール（1組） — 前の手順で組み立てたもの"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b2c51fc57908e2a4d6ef455686b5ba90-800x600.jpg","reveal":["gantry"],"add":[],"verificationRevision":"588750e31eaee81d"},{"chapter":4,"officialStep":36,"officialId":990732,"chapterSteps":83,"title":"リニアレールユニットを取り付ける","description":"モーターマウントを手前にし、左右のリニアホルダーをY方向の中央付近へ動かします。前側からレール一式を合わせ、後ろ側からM3x8rTを左右3本ずつ、計6本入れて固定してください。","parts":["gantry"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990732","checks":["レールを前から合わせ、後ろから左右各3本のM3x8rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ed869dfa8d34e8e2b8aad55322cd0254-800x600.jpg","reveal":["gantry"],"add":[],"verificationRevision":"0984a3889c5b84b0"},{"chapter":4,"officialStep":37,"officialId":990778,"chapterSteps":83,"title":"レールの保護ピンを取り外す","description":"この手順で保護ピン2本を取り外します。ラジオペンチで軽くつまみ、レールから引き抜いてください。","parts":["gantry"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990778","checks":["保護ピン2本をレールから取り外した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d71be8674d6465860d22fc03e4fdc2a1-800x600.jpg","reveal":["gantry"],"add":[],"verificationRevision":"620e210d4d441f83"},{"chapter":4,"officialStep":38,"officialId":990804,"chapterSteps":83,"title":"ベッドストッパーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990804","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["後部ベッドストッパー（Bed-stop-rear）（1個） — 「Printed parts」同梱","M3nSナット（3個）","M3x8rTネジ（3本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7ef2fc05a95b4010200d0cfb9219070d-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"f82098d92c6e1169"},{"chapter":4,"officialStep":39,"officialId":990846,"chapterSteps":83,"title":"ベッドストッパーを組み立てる","description":"bed-stopへM3nS角ナットを一方の面から2個、反対の面から1個入れます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990846","checks":["M3nSを片側2個・反対側1個、計3個入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/df2aa2ea88eef0ebdaec54325988a9fc-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"7ab01c6ec11ec521"},{"chapter":4,"officialStep":40,"officialId":990874,"chapterSteps":83,"title":"ベッドストッパーを取り付ける","description":"モーターマウントを上にし、CoreXY板の後ろの三角突起の下へbed-stop-rearを入れます。3つの穴を合わせ、M3x8rTの3本で固定してください。上のねじは樹脂にねじ山を作るため、少し抵抗があります。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990874","checks":["後ろの三角突起の下へストッパーを入れ、M3x8rTの3本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1ed97fb76b7fc2dfc6d48b72cfb83821-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"842ef4d16fa51852"},{"chapter":4,"officialStep":41,"officialId":990936,"chapterSteps":83,"title":"X・Yモーターの部品を準備する","description":"モーターの表示を見て、X軸用とY軸用を1個ずつ用意します。以降もこの表示に従って作業してください。プーリーT16-2GTを2個と、前に使ったAssembly-multi-toolも用意します。プーリーの袋は「GT2-16」と表記されている場合があります。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990936","checks":["X/Yの表示を確認し、モーター各1個、プーリー2個、Assembly-multi-toolを用意した"],"supplies":["Y軸モーター（1個） — 「Motors」同梱","X軸モーター（1個） — 「Motors」同梱","プーリー T16-2GT（2個） — 「Electronics」同梱。袋の表示が「GT2-16」の場合があります","組み立て用マルチツール（Assembly-multi-tool）（1個） — 前の手順で使ったもの"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/69a76bd16b388b5da70ea4ee33b810b7-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"761af5eff05121b1"},{"chapter":4,"officialStep":42,"officialId":990996,"chapterSteps":83,"title":"X軸プーリーを取り付ける","description":"Xモーターの軸の平らな面を手前に向けます。プーリーの歯をモーター側に向け、Assembly-multi-toolのフォークで隙間を合わせてください。先に平らな面に当たる止めネジを締め、回してもう1本も締めます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#990996","checks":["歯がモーター側を向き、工具で隙間を合わせ、止めネジ2本を締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0744a86970bc32f1c92dd4b043d9a072-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"c6294b8a8b7b3034"},{"chapter":4,"officialStep":43,"officialId":991072,"chapterSteps":83,"title":"Y軸プーリーを取り付ける","description":"Yモーターのプーリーは、歯をモーターと反対側に向けます。Assembly-multi-toolの太いフックをモーターとプーリーの間に当てて隙間を合わせてください。軸にフックを掛けないでください。平らな面に当たる止めネジを先に締め、もう1本も締めます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991072","checks":["歯がモーターと反対側を向き、太いフックで隙間を合わせ、止めネジ2本を締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/cb6498c90043491f2c9afa6ad742ba21-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"b0d6d088de185442"},{"chapter":4,"officialStep":44,"officialId":991148,"chapterSteps":83,"title":"XYベルトの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991148","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["組み立て済みのX軸モーター（1組） — 前の手順で組み立てたもの","組み立て済みのY軸モーター（1組） — 前の手順で組み立てたもの","Nextruderホルダー（1個） — 「CORE XY parts + hinges + HB set」同梱","XYベルト（2本） — 「CORE XY parts + hinges + HB set」同梱","M3x35ネジ（8本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f5d8369f0caac5d2d3b01a9cf180f93c-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"1124f8a49c42d550"},{"chapter":4,"officialStep":45,"officialId":991210,"chapterSteps":83,"title":"XYベルトの注意点","description":"Xベルトは上段、Yベルトは下段に通します。Nextruderホルダーから出る4本の端は、突き出す歯数をすべてそろえてください。","parts":["xy"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991210","checks":["上段X・下段Yの経路と、端の歯数をそろえる条件を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/459a682c18cfc192bc42df79664d07d9-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"769d104843fcbee1"},{"chapter":4,"officialStep":46,"officialId":991251,"chapterSteps":83,"title":"YベルトをYモータープーリーに通す","description":"CoreXYの背面から見て左のモーターマウントで作業します。ベルトの歯を内側にして輪を作り、下段プーリーの間から丸い上側の穴に沿う位置まで通してください。Yモーターのプーリーを輪の中央に入れ、ケーブルを手前に向けます。ベルトを軽く引いてプーリーに掛けます。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991251","checks":["Yベルトは下段を通り、歯がプーリーに掛かり、モーターのケーブルが背面側を向いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4eb84a996c2682203d5a4b8730f3a406-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"2a2ba51970eabc5d"},{"chapter":4,"officialStep":47,"officialId":991321,"chapterSteps":83,"title":"Y軸モーターを固定する","description":"Yモーターを片手で支えたまま、CoreXYユニットを立てます。モーターを落としたり、ベルトを引き抜いたりしないでください。フレームの裏側からM3x35を4本締めて固定し、ユニットを水平に戻します。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991321","checks":["YモーターをM3x35の4本で固定し、ベルトが外れていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/384ea0c56a349fd4d4ada1d177deb117-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"3fc0f6e92900c414"},{"chapter":4,"officialStep":48,"officialId":991365,"chapterSteps":83,"title":"YベルトをYモーターマウントに通す","description":"Yベルトの左端を、モーターマウント内の下段左プーリーに回し、CoreXYプレートの前側へ通します。反対側の端はまだ固定されていません。引きすぎてベルト全体を抜かないようにしてください。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991365","checks":["Yベルトが下段左プーリーを回って前側へ出ており、反対側も残っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d9e869cd1f768254e23225cc3dd55558-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"f8eee82ea1a471d4"},{"chapter":4,"officialStep":49,"officialId":991401,"chapterSteps":83,"title":"Yベルトをテンショナーに通す","description":"Yベルトをテンショナーのプーリー、リニアユニットの前側プーリーの順に回します。Nextruderホルダーの中央穴から下段左の穴へ端を差し込み、歯を4～5個出してください。届きにくい場合は、前側のテンショナーネジを一時的に緩めます。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991401","checks":["Yベルトの端を下段左に固定し、歯が4～5個出ている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/226b068392040f7761210f163b021836-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"7b7bb690da539132"},{"chapter":4,"officialStep":50,"officialId":991455,"chapterSteps":83,"title":"YベルトをXモーターマウントに通す","description":"Yベルトの反対側を、Xモーターマウントの下段プーリーに回します。マウントを通して前側へ出し、リニアレールホルダーの下段右プーリーへ通してください。Yベルトは下段の経路を使います。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991455","checks":["Yベルトの反対側が下段の2つのプーリーを通っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a381440a21e3ebd5337c9dda265dc7b4-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"bc302ea807f38e7b"},{"chapter":4,"officialStep":51,"officialId":991501,"chapterSteps":83,"title":"Yベルトを固定する","description":"Yベルトの端を、Nextruderホルダーの中央穴から下段右の穴へ差し込み、歯を4～5個出します。届きにくくてテンショナーを緩めた場合は、固定後に元へ戻してください。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991501","checks":["下段右に歯が4～5個出ており、緩めたテンショナーは元に戻した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/05f9dadf65e2a98490c8620e4ddb3e9b-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"b89247555039eb31"},{"chapter":4,"officialStep":52,"officialId":991535,"chapterSteps":83,"title":"XベルトをXモータープーリーに通す","description":"CoreXYの背面から見て右のモーターマウントで、2本目のベルトを歯が内側になる輪にします。上段プーリーの間から、丸い上側の穴に沿う位置まで通してください。Xモーターのプーリーを輪の中央に入れ、ケーブルを背面側へ向けます。ベルトを軽く引いてプーリーに掛けます。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991535","checks":["Xベルトは上段を通り、歯がプーリーに掛かり、モーターのケーブルが背面側を向いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/dec61b3e03feba5700c7b1fd5ade4729-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"5a210121e9262cdf"},{"chapter":4,"officialStep":53,"officialId":991605,"chapterSteps":83,"title":"X軸モーターを固定する","description":"Xモーターを片手で支えたまま、CoreXYユニットを立てます。モーターを落としたり、ベルトを引き抜いたりしないでください。フレームの裏側からM3x35を4本締めて固定し、ユニットを水平に戻します。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991605","checks":["XモーターをM3x35の4本で固定し、ベルトが外れていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/14d5302304240393530341da97cb8324-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"4c4c74b4a2e7594a"},{"chapter":4,"officialStep":54,"officialId":991649,"chapterSteps":83,"title":"XベルトをXモーターマウントに通す","description":"引き続き上段のXベルトを扱います。右側の端を右上のプーリーに回し、モーターマウントを通して前方へ送ります。反対の端が抜けないようにしてください。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991649","checks":["上段のXベルトが右上のプーリーを通り、前方に出ている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8b9ba5db9b69c19ee3fdbf7644cc3967-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"6649a15c39708ae2"},{"chapter":4,"officialStep":55,"officialId":991685,"chapterSteps":83,"title":"Xベルトをテンショナーに通す","description":"Xベルトをテンショナーのプーリー、リニアユニットの前側上段プーリーの順に回します。Nextruderホルダーの中央穴から右の穴へ差し込み、歯を4～5個出してください。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991685","checks":["Xベルトが上段を通り、右の固定穴から歯が4～5個出ている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9acb24580823d034b71fd6790a8f5714-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"7a4f04000147ae52"},{"chapter":4,"officialStep":56,"officialId":991731,"chapterSteps":83,"title":"XベルトをYモーターマウントに通す","description":"Xベルトの反対側を、Yモーターマウントの上段プーリーに回します。マウントを通し、リニアレールホルダーの前側上段プーリーへ通してください。Xベルトは上段の経路を使います。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991731","checks":["Xベルトの反対側が上段の2つのプーリーを通っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e228c0b28283ef09f5664e9def5415fc-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"255ae8463a045cf2"},{"chapter":4,"officialStep":57,"officialId":991777,"chapterSteps":83,"title":"Xベルトを固定する","description":"Xベルトの端を、Nextruderホルダーの中央穴から上段左の穴へ差し込み、歯を4～5個出します。次の手順で、ベルト4端の歯数と経路をまとめて確認します。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991777","checks":["Xベルトの端を上段左に固定し、歯が4～5個出ている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/dff9335f4f3e789d083f02e87a12efc7-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"acf1ef7509527a72"},{"chapter":4,"officialStep":58,"officialId":991795,"chapterSteps":83,"title":"ベルトの通り道を確認する","description":"ホルダーから突き出す4本のベルト端の歯数を、すべて同じにそろえます。上下の経路を公式図と照合してから、次へ進んでください。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991795","checks":["4本のベルト端の歯数がすべて同じで、上下の経路も合っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/459a682c18cfc192bc42df79664d07d9-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"c5513c49599b8a5d"},{"chapter":4,"officialStep":59,"officialId":991812,"chapterSteps":83,"title":"ボーデンガイドの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991812","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["PTFEチューブのガイド（Bowden-guide）（1個） — 「Printed parts」同梱","M3x10ネジ（5本）","M3nSナット（1個）","結束バンド（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1dd72b4abd4c455e9864beec6efcec23-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"892d423fd1b41409"},{"chapter":4,"officialStep":60,"officialId":991866,"chapterSteps":83,"title":"Nextruderホルダーを固定する","description":"Nextruderホルダーをリニアレールのキャリッジに合わせ、M3x10を4本使って固定します。締める前に、ネジの通り道にベルトがないことを確認してください。ベルトをネジで貫かないでください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991866","checks":["M3x10の4本で固定し、どのネジにもベルトが巻き込まれていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1307b037ee9a238a4def7948a1623bd2-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"0310ee1361598b62"},{"chapter":4,"officialStep":61,"officialId":991892,"chapterSteps":83,"title":"Yモーターのケーブルを固定する","description":"motor-mount-rightに結束バンドを通します。Yモーターのケーブルをマウントの溝に沿わせ、バンドの上に置いてください。バンドで固定してから、余りを切ります。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991892","checks":["Yモーターのケーブルが溝に収まり、バンドで固定されている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d0af0fbe0a3ecbae7c202d1bf4c57d70-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"d5a3d4e41aab0010"},{"chapter":4,"officialStep":62,"officialId":991930,"chapterSteps":83,"title":"Xモーターのケーブルを固定する","description":"motor-mount-leftに結束バンドを通します。Xモーターのケーブルをマウントのガイドに沿わせ、バンドの上に置いてください。バンドで固定してから、余りを切ります。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991930","checks":["Xモーターのケーブルがガイドに収まり、バンドで固定されている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/710c63138ea7cee012c43da786ec9547-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"36aaf76d3d6b4715"},{"chapter":4,"officialStep":63,"officialId":991966,"chapterSteps":83,"title":"ボーデンガイドを取り付ける","description":"motor-mount-rightにM3nS角ナットを入れます。bowden-guideの向きを公式写真に合わせ、M3x10で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#991966","checks":["M3nSが入り、ガイドの向きを確認してM3x10で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0789648f8b679c374fbb981a180e5239-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"01a2bc90a3e4203b"},{"chapter":4,"officialStep":64,"officialId":992012,"chapterSteps":83,"title":"白色LEDの部品を準備する","description":"白色LEDストリップ1個、CoreXY strutを1本、M3x4rTを2本用意します。CoreXY strutはMetal parts 1/3箱の緩衝材の切り込みに差し込まれていて、見落としやすいので確認してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992012","checks":["緩衝材からCoreXY strutを取り出し、白色LEDとM3x4rTを2本用意した"],"supplies":["白色LEDストリップ（1本） — 「Electronics & Fasteners」同梱","CoreXY補強材（1本） — 「Metal parts 1/3」同梱","M3x4rTネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/98ef43da1f3a9c157a8c9b1538a814ee-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"7ff5f694607143ed"},{"chapter":4,"officialStep":65,"officialId":992064,"chapterSteps":83,"title":"白色LEDを貼り付ける","description":"白色LEDストリップのケーブルを、CoreXYストラットの長方形の切り欠き側へ向けます。保護紙を剥がし、貼る位置を合わせてから、切り欠きのある面へまっすぐ貼ってください。部品のない部分を軽く押さえます。LEDや抵抗には触れないでください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992064","checks":["ケーブルが切り欠き側を向き、ストリップが切り欠きのある面にまっすぐ貼られている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/45a34c4ba5926f2613ef94d55cdee51d-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"97fd3b030ce9e10e"},{"chapter":4,"officialStep":66,"officialId":992126,"chapterSteps":83,"title":"白色LEDユニットを取り付ける","description":"LEDを貼ったストラットをCoreXYユニットの前側に合わせます。ケーブルを左へ向け、穴をそろえてM3x4rTの2本で固定してください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992126","checks":["LEDケーブルが左を向き、M3x4rTの2本で固定されている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/599ad54e94c650e6e97d381acb5503dd-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"a1253b998fdd494b"},{"chapter":4,"officialStep":67,"officialId":992162,"chapterSteps":83,"title":"ドアセンサー・LEDの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992162","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["ドアセンサー（1個） — 「Electronics and Fasteners」内の「Cables 1/3」箱","M2.5x10ネジ（1本） — 銀色","結束バンド（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/292edd69979f118ad0463dcb365c2810-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"2306834c30d7a9c4"},{"chapter":4,"officialStep":68,"officialId":992208,"chapterSteps":83,"title":"結束バンドを通す","description":"CoreXYユニットを裏返し、モーターを下にして置きます。白色LEDのケーブルを手前に向けてください。結束バンド3本を頭が内側になるように通し、裏側のベルトを巻き込んでいないか確認します。数歯だけ留め、本締めはしません。最後にモーターが上になる向きへ戻します。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992208","checks":["3本の頭が内側を向き、ベルトを巻き込まず、配線用の隙間を残している"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/548311fbc2ca2d62d5ea96f00a9f745c-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"d8d809229efaf36c"},{"chapter":4,"officialStep":69,"officialId":992270,"chapterSteps":83,"title":"ドアセンサーを取り付ける","description":"左のベルトテンショナーにドアセンサーを載せ、レバーを前に向けます。M2.5x10で固定し、締めてから1/4回転戻してセンサーが動くようにしてください。テンショナーの後ろからM3x12をセンサーに触れるまで締めます。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992270","checks":["センサーが左テンショナーに取り付けられ、レバーが前を向いている","M2.5x10を締めてから1/4回転戻し、センサーを動かせることを確認した","後ろ側のM3x12がセンサーに触れている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/95475ed2a9a9f41fcd1c266048c56967-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"728525d79f6d75d6"},{"chapter":4,"officialStep":70,"officialId":992314,"chapterSteps":83,"title":"ドアセンサーのケーブルを固定する","description":"左のベルトテンショナーの穴に結束バンドを通し、ドアセンサーのケーブルをバンドの中に通します。ケーブルを固定してから、バンドの余りを切ってください。","parts":["xy"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992314","checks":["ドアセンサーのケーブルを左テンショナーのバンドで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/bb3580653a758c245fc53aa462ba60c3-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"93adc7b50c0e575e"},{"chapter":4,"officialStep":71,"officialId":992350,"chapterSteps":83,"title":"LED・ドアセンサーのケーブルを通す","description":"CoreXYを裏返してスムースロッドを上にし、前側を箱で少し持ち上げて支えます。ドアセンサーを傷めないでください。白色LEDとドアセンサーのケーブルを3本のバンドに通し、たるみや曲がりを残さずバンドを締め、余りを切ります。Buddyカメラを追加する場合は、USB-Cケーブルを通すまで本締めしません。","parts":["xy"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992350","checks":["ケーブルにたるみや曲がりがなく、Y軸の動きを妨げない。カメラ用ケーブルを追加する場合はバンドを本締めしていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/059209b0179ec72fb2575d948dd6f4a2-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"978b734e55b67193"},{"chapter":4,"officialStep":72,"officialId":992428,"chapterSteps":83,"title":"Buddy3Dカメラについて","description":"Buddy3D Cameraを使わない場合は次へ進みます。使う場合は、この手順の公式リンクから専用ガイドを開き、USBケーブルだけを先に配線して結束バンドを締められます。専用ガイドの写真はさらに組み立てが進んだ状態ですが、カメラ本体の取り付けは後の案内まで待ってください。","parts":["xy"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992428","checks":["カメラを使わないか、使用する場合は専用ガイドでUSBだけを先に配線し、バンドを固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f6fedbacfb97ff33034c97e305609cad-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"4daf77bd19337b04","references":[{"label":"Buddy3D Cameraの公式取り付けガイド","url":"https://help.prusa3d.com/guide/buddy3d-camera-for-core-one-installation_405529"}]},{"chapter":4,"officialStep":73,"officialId":992486,"chapterSteps":83,"title":"スムースロッドの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["xy"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992486","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["スムーズロッド 330 x 8 mm（2本） — 「Rods」同梱","M3x8rTネジ（1本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ac85deeb887c50879b5a6c2714364f1f-800x600.jpg","reveal":["xy"],"add":[],"verificationRevision":"8d8042e69325aab6"},{"chapter":4,"officialStep":74,"officialId":992522,"chapterSteps":83,"title":"CoreXYユニットを本体に取り付ける","description":"ベッドのベアリングと軸を合わせ、鋼球が外れないよう、2本のスムースロッドを非常にゆっくり通してベースのホルダーへ入れます。ファン配線は背面パネルへ一時的に掛け、パネルのくぼみとの間に隙間を確保してください。配線を挟まないよう慎重にCoreXYを載せ、両ロッドの着座と、後部Zねじ軸がbed-stop-rearを通ることを確認します。プリンターを持ち上げるときは、CoreXYをつかまずベースを支えてください。","parts":["xy","gantry"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992522","checks":["ロッド2本が下のホルダーに収まり、後部ねじ棒がbed-stop-rearを通っている","ファン配線と背面パネルのくぼみに隙間があり、CoreXYと背面パネルの間に配線を挟んでいない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6a9d65e81981de53425d6fdd85e42192-800x600.jpg","reveal":["xy","gantry"],"add":["xy","gantry"],"verificationRevision":"163e61ddf80f4f7e"},{"chapter":4,"officialStep":75,"officialId":992600,"chapterSteps":83,"title":"スムースロッドを固定する","description":"スムースロッド2本が、ホルダーの奥まで入っていることを確認します。入り切っていない場合は、公式写真のようにマイナスドライバーでスリットを慎重に少し広げます。正しく着座してから、左右のM3x10をしっかり締めて固定してください。","parts":["xy","gantry"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992600","checks":["両方のロッドが奥まで入り、左右のM3x10を締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/127fcd993407a14a6ca8e19573604d89-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"749adccc45dd2a4f"},{"chapter":4,"officialStep":76,"officialId":992636,"chapterSteps":83,"title":"リニアレールの位置を合わせる","description":"リニアレールのキャリッジを中央へ移動します。レールを下へ押さえながら、公式写真に示された順序で全てのネジをしっかり締めてください。","parts":["xy","gantry"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992636","checks":["キャリッジを中央にし、レールを下へ押さえ、写真の順番で全てのネジを締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/85bf400c59c37a171ce874d70a817a69-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"5cf649489e7a0bc2"},{"chapter":4,"officialStep":77,"officialId":992670,"chapterSteps":83,"title":"CoreXYのケーブルを通す","description":"背面側からFEケーブルを楕円穴へ通し、左後方のFEケーブル5をCoreXYプレート裏面のFaston端子に接続します。同じ側のXモーター、白色LED、ドアセンサーのケーブルも背面パネルの楕円穴へ通してください。","parts":["xy","gantry"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992670","checks":["FE5をプレート裏の端子に接続し、X・白色LED・ドアセンサーの配線を楕円穴に通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7748e3508d1f7aac4d4322ecab770435-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"d30102ec4f632327"},{"chapter":4,"officialStep":78,"officialId":992724,"chapterSteps":83,"title":"冷却ファンのケーブルを通す","description":"チャンバーファンと温度センサーのケーブルを、背面パネルの楕円穴へ通します。右後方のYモーターのケーブルは、上側の楕円穴へ通してください。","parts":["xy","gantry"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992724","checks":["ファンと温度センサーを楕円穴に通し、Yモーターは右後方の上側の穴に通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/57349eb5a3146b5e7146f3adbc734525-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"9288d69ae08896e6"},{"chapter":4,"officialStep":79,"officialId":992752,"chapterSteps":83,"title":"ベッドストッパーを固定する","description":"背面のファン下にある長穴を、反対側のbed-stopの穴に合わせます。必要に応じてCoreXYの後ろ側を数mmだけ持ち上げ、穴がそろってからM3x8rTで固定してください。","parts":["xy","gantry"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992752","checks":["長穴とbed-stopの穴がそろい、M3x8rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b421d2ee2f189ff159d54daffde13aab-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"30705b7ab81566aa"},{"chapter":4,"officialStep":80,"officialId":992796,"chapterSteps":83,"title":"冷却ファンのケーブルを接続する","description":"接続先の左右は、公式写真と同じ向きで確認してください。 ファン2本のケーブルをxBuddyケースの左穴から通し、拡張基板のFAN 1・FAN 2（4番目・5番目）へ接続します。ファン2本の順序は問いません。チャンバー温度センサーのケーブルも同じ経路へ通し、拡張基板の左から2番目のTEMPへ接続してください。","parts":["xy","gantry"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992796","checks":["ファン2本をFAN 1・FAN 2へ接続した","チャンバー温度センサーを拡張基板のTEMPへ接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1649d471da2b6824d0c15d51e995d77e-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"b8bade5ea606a5f0"},{"chapter":4,"officialStep":81,"officialId":992840,"chapterSteps":83,"title":"CoreXYのケーブルを接続する","description":"接続先の左右は、公式写真と同じ向きで確認してください。 Xモーター、ドアセンサー、白色LEDのケーブルはxBuddyケースの右穴へ通します。XはxBuddy基板の左から1番目、ドアセンサーは同基板の左下、白色LEDは拡張基板の右から2番目へ接続してください。Yモーターはケースの左穴から、xBuddy基板の左から2番目へ接続します。","parts":["xy","gantry"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992840","checks":["X・YをxBuddy基板の左から1・2番目へそれぞれ接続した","ドアセンサーはxBuddy基板の左下、白色LEDは拡張基板の右から2番目へ接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/17046a59c0c38416e85be92ab2fa7f45-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"ec2f58d28548076f"},{"chapter":4,"officialStep":82,"officialId":992884,"chapterSteps":83,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの4列目が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["xy","gantry"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992884","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/50a64777c74383cb0223feaf44b758a1-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":4,"officialStep":83,"officialId":992910,"chapterSteps":83,"title":"CoreXYの組み立てを確認する","description":"CoreXYの組み立てと取り付けはここまでです。未確認の手順がないか見直してから、Nextruderの章へ進みます。","parts":["xy","gantry"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/5-corexy-assembly_982276#992910","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/02958f2a7f6a83bd7b586a9f4dbd1be8-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"1244d7ec7442a18d"},{"chapter":5,"officialStep":1,"officialId":992936,"chapterSteps":58,"title":"この章で使う工具","description":"ユニバーサルレンチ、1.5 mmと2.5 mmの六角レンチ、T6とT10のトルクスを用意します。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":["ユニバーサルレンチ","1.5 mm 六角レンチ","2.5 mm 六角レンチ","T6 トルクスレンチ","T10 トルクスレンチ"],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#992936","checks":["ユニバーサルレンチ、1.5 mmと2.5 mmの六角レンチ、T6とT10のトルクスを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3f4de27076a766c3-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"4625ada923c348ca"},{"chapter":5,"officialStep":2,"officialId":992996,"chapterSteps":58,"title":"アイドラーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#992996","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["アイドラーレバーA（Idler-lever-a）（1個） — 「Electronics」内の「Nextruder assembly」袋","アイドラーレバーB（Idler-lever-b）（1個） — 「Electronics」内の「Nextruder assembly」袋","ベアリング 693 2RS（2個） — 「Electronics」同梱","ピン 2.9x8.5（2本） — 「Electronics」同梱","M3x6ネジ（1本）","筒型スペーサー 13.2x3.8x0.35（1個） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1811a2e44f23e07167012dd6fd6ea445-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"eb5b1a9c62dbf1f9"},{"chapter":5,"officialStep":3,"officialId":993064,"chapterSteps":58,"title":"アイドラーを組み立てる","description":"Idler-lever-aにベアリング2個を入れ、それぞれに2.9×8.5 mmのピンを通します。Idler-lever-bを重ね、M3x6で留めてください。締め過ぎず、両ベアリングが軽く回ることを確認します。同じ側からチューブスペーサーを入れ、底をアイドラー下面とそろえます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993064","checks":["両ベアリングが軽く回り、スペーサーの底が下面とそろっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c45ee278ccb117d393a425072a739cb3-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2c89810d63edf068"},{"chapter":5,"officialStep":4,"officialId":993108,"chapterSteps":58,"title":"エクストルーダーの部品を準備する①","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993108","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["PGギアアセンブリ（PG-assembly）（1組） — 「Electronics」同梱","ヒートシンクアセンブリ（1組） — 「Electronics」同梱","メインプレート（Main-plate）（1枚） — 「Electronics」同梱","PGリング（PG-ring）（1個） — 「Electronics」同梱","PG組み立てアダプター（PG-assembly-adapter）（1個） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4ed6a516e84542fe4aad4a39f640c8aa-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"5d6caf148a28c8f7"},{"chapter":5,"officialStep":5,"officialId":993174,"chapterSteps":58,"title":"エクストルーダーの部品を準備する②","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993174","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["エクストルーダーモーター（1個） — 「Motors」同梱","スペーサー 5x10x0.1 mm（1枚） — 「Electronics」内の「Nextruder」袋","M3x25イモネジ（1本） — 「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c628b55f9788b2b955623a2a0999c27a-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"7b54b48b5f5bce80"},{"chapter":5,"officialStep":6,"officialId":1046722,"chapterSteps":58,"title":"エクストルーダーを組み立てる","description":"モーター軸に5×10×0.1 mmのスペーサーを入れ、ヒートシンクを押出機モーターに重ねます。公式写真と同じ向きで、モーター配線を上、ヒートシンク配線を右に向けてください。ヒートシンクにメインプレートを載せ、切り欠きで向きを合わせます。次へ進む前に、スペーサーの入れ忘れがないか確認してください。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#1046722","checks":["0.1 mmのスペーサーを入れ、モーター配線は上、ヒートシンク配線は右にした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/e0bb5af24bc64a7d51c857697611dc48-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"80b2ee324644b60b"},{"chapter":5,"officialStep":7,"officialId":993272,"chapterSteps":58,"title":"ギアボックスを組み立てる","description":"組み付ける前に、公式手順にある遊星ギアの動画を確認してください。PG-assemblyの歯車をアダプターのくぼみに合わせ、PG-assembly-adapterを取り付けます。この工具は次の手順でも使います。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993272","checks":["歯車がアダプターのくぼみに合い、アダプターを取り付けた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4c8b2a09ea0f96e35e74c782959b4b90-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"b6db91f746ffc1bf"},{"chapter":5,"officialStep":8,"officialId":993308,"chapterSteps":58,"title":"PGリングを組み立てる","description":"アダプターを付けたままPGリングを通します。リング内歯の面取りがある側を下、PG-assembly側へ向けてください。全体を支え、リングを左右へ交互に少し回しながら下げます。回す範囲は約1/4回転で十分です。歯車とリングの表面がほぼそろったら止めます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993308","checks":["アダプターを使い、面取り側を下にして、歯車とリングの表面がほぼそろっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/35c08a9716d7358beac23336949801f8-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"002b7b3689a0f746"},{"chapter":5,"officialStep":9,"officialId":993368,"chapterSteps":58,"title":"PGユニットを組み立てる","description":"ギア一式の位置を崩さず、押出機モーターの軸へ合わせます。アダプターを付けた一式を、ごく軽く自由に回してください。Main-plateとの隙間がなくなる位置へ自然に下がります。押し込まないでください。着座してからアダプターを外します。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993368","checks":["押し込まずに着座し、Main-plateとの隙間がなく、アダプターを外した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/04584ff75bbb69b3c68cab2610bff4dd-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"4c86f01e1c6f731b"},{"chapter":5,"officialStep":10,"officialId":993414,"chapterSteps":58,"title":"PGユニットを確認する","description":"アダプターをもう一度付け、強い力を使わずにギア一式が回るか確認してから外します。歯車はPGリングの表面から飛び出さず、同じ高さか低い位置に収まります。リングとMain-plateの隙間が大きい場合は、ギア一式を外して組み直してください。アダプターは保守用に保管します。","parts":["head"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993414","checks":["アダプターで軽く回すことができ、確認後に外した","歯車がリングより高くなく、リングとMain-plateの隙間が最小限になっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/90a7a28c13f56f635e949f7a6c958b6d-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"5c1071d65361e6e9"},{"chapter":5,"officialStep":11,"officialId":993468,"chapterSteps":58,"title":"Nextruderアイドラーを組み立てる","description":"アイドラーをPGリングとモーターの間へ入れ、スペーサーをMain-plateの切り欠きとPGリングの穴に合わせます。止めネジM3x25で固定してください。締めすぎないでください。固定後もネジがPGリングから出るのは正常です。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993468","checks":["スペーサーが切り欠きと穴に合い、M3x25を締めすぎずに固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5b430dc1303c72d5bb77a71d02eba02c-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"c2c988e00aea990a"},{"chapter":5,"officialStep":12,"officialId":993496,"chapterSteps":58,"title":"ギアの潤滑に使うものを準備する","description":"Nextruderのフロントケース、M3x25を3本、潤滑剤を用意します。ケースのロゴは「PRUSA CORE ONE」のままで正しい部品です。手に付いたグリスを拭けるよう、ペーパータオルも数枚用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993496","checks":["CORE ONEロゴのケース、M3x25を3本、潤滑剤、ペーパータオルを用意した"],"supplies":["フロントケース（1個） — 「Printed parts」同梱","M3x25ネジ（3本）","潤滑剤（1個） — 「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c58e4fd587acbddacb2081e7a49a0401-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2f102aa3e03e0e9f"},{"chapter":5,"officialStep":13,"officialId":993549,"chapterSteps":58,"title":"ギアを潤滑する","description":"結束バンドの先に少量のPrusa Lubricantを取り、PGリングとPGアセンブリの歯に一周塗ります。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993549","checks":["PGリングとPGアセンブリの歯を一周潤滑した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/50fd10fb53ebb7c820b736d046b2cf57-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"93aa9ae85e655f9c"},{"chapter":5,"officialStep":14,"officialId":993595,"chapterSteps":58,"title":"遊星ギアにカバーを付ける","description":"PGリングの前面に残った潤滑剤を拭き取り、ケースをM3x25の3本で仮止めします。この段階では本締めせず、最後の校正時に締めてください。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993595","checks":["ケースのネジ3本は仮止めで、本締めしていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6a64cc342ce4ab8612123b79451c8a77-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"ec7aac0d438f4e30"},{"chapter":5,"officialStep":15,"officialId":993631,"chapterSteps":58,"title":"アイドラー回転部の部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993631","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["アイドラスイベル（Idler-swivel）（2個） — 「Electronics」同梱","アイドラーナット（Idler-nut）（1個） — 「Electronics」同梱","M3x30ネジ（2本）","M3x20rTネジ（2本）","M3nNナット（2個）","スプリング 15x5（2本） — 「Electronics」同梱","スペーサー 6x3.1x8（1個） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0674c88e3b60a9dbbf2e3c5a1f7231f8-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"e2157563deaf717b"},{"chapter":5,"officialStep":16,"officialId":993707,"chapterSteps":58,"title":"アイドラー回転部を組み立てる","description":"片方のIdler-swivelにM3x20rTを奥まで通し、スペーサーを入れます。反対側からもう片方を合わせ、M3nNナットを付けてください。ナットをユニバーサルレンチで支え、スペーサーが自由に回る程度に軽く締めます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993707","checks":["M3x20rTとM3nNで組み、スペーサーが自由に回る"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/636412ab866adfa1d4c8c665bcb5ee8b-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2a4ea50b5686777c"},{"chapter":5,"officialStep":17,"officialId":993751,"chapterSteps":58,"title":"アイドラーナットを組み立てる","description":"Idler-nutとIdler-swivelを公式写真の向きに合わせます。1本目と同じ側からM3x20rTを通し、M3nNナットで固定してください。締めすぎず、Idler-nutに対してIdler-swivelが動くことを確認します。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993751","checks":["ネジ2本を同じ側から通し、Idler-swivelがIdler-nutに対して動く"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/36d434a9b2e609a75cac2e15b3ccf202-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"d7631909a14a646d"},{"chapter":5,"officialStep":18,"officialId":993789,"chapterSteps":58,"title":"アイドラー回転ユニットを取り付ける","description":"M3x30の2本に15×5のスプリングを通し、ヒートシンクの突起にある穴へ通します。この穴にねじ山はありません。Idler-nutの刻印側が見える向きでスイベルを取り付けてください。ネジ先端がナットの前面にそろったところで締めるのを止めます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993789","checks":["ナットの刻印が見え、ネジ先端がナット前面にそろっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d60b8dbf17fa451cbc59a86b3133fd36-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"a6d25927c8e5bbf0"},{"chapter":5,"officialStep":19,"officialId":993835,"chapterSteps":58,"title":"NTCサーミスターの部品を準備する","description":"90 mmのNTCサーミスターを1個、M3x4Tの止めねじを1本用意します。サーミスターはElectronics箱内のNextruder box + Heatbed heatsink boxに入っています。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993835","checks":["90 mmサーミスター1個とM3x4Tを1本用意した"],"supplies":["NTCサーミスター 90 mm（1本） — 「Electronics」内の「Nextruder box+Heatbed heatsink」箱","M3x4Tイモネジ（1本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7d0cd9b40ce85c19a24daafb8f98dc53-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"55cdfa2d50dde247"},{"chapter":5,"officialStep":20,"officialId":993869,"chapterSteps":58,"title":"NTCサーミスターを組み立てる","description":"押出機モーター側から、NTCサーミスターをヒートシンクの穴に入れます。M3x4Tの止めネジを奥まで入れ、T6キーの短い側を指2本で持って、軽く、確実に固定してください。力をかけ過ぎると、ねじ山を傷めます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993869","checks":["NTCをモーター側の穴に入れ、M3x4Tで締め過ぎずに固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0dade92b0645d58401e8cfdcf7fb3148-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"5c8b97b2d5c41c3d"},{"chapter":5,"officialStep":21,"officialId":993895,"chapterSteps":58,"title":"Nextruder取り付け用の部品を準備する","description":"Nextruderスペーサー3個、M3x10を3本、ヒートベッドを保護する段ボール箱を用意します。スペーサーはElectronics & Fasteners箱のSmall parts & fasteners袋に入っています。保護用の箱はキットの空き箱を使えます。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993895","checks":["スペーサー3個、M3x10を3本、ベッド保護用の箱を用意した"],"supplies":["Nextruderスペーサー（3個） — 「Electronics & Fasteners」内の「Small parts & fasteners」袋","M3x10ネジ（3本）","段ボール箱（1個） — ヒートベッドの仮保護に使用"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/008189b99fca9217d4b6667af8873c96-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"36976a115e3a1c72"},{"chapter":5,"officialStep":22,"officialId":993949,"chapterSteps":58,"title":"ヒートベッドを保護する","description":"落とした部品でヒートベッドを傷めないよう、空の段ボール箱を置いて保護します。できるだけ広い範囲を覆ってください。キットの箱を使えます。","parts":["head"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993949","checks":["ヒートベッドを空箱で覆い、落下物から保護した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/04a39fba057285e3edc79c2c10170eb5-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"d9c070b26c129de9"},{"chapter":5,"officialStep":23,"officialId":993975,"chapterSteps":58,"title":"Nextruderを取り付ける","description":"Nextruderホルダーにスペーサー3本をしっかりねじ込みます。Nextruderを載せて穴を合わせ、M3x10の3本で固定してください。このネジは締めすぎないでください。NTCケーブルは左へ向けます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#993975","checks":["スペーサー3本とM3x10の3本で固定され、NTCケーブルが左を向いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d736e45c1cb31c9e99d6921a918b7ff3-800x600.jpg","reveal":["head"],"add":["head"],"verificationRevision":"0a8260769c7a1b1b"},{"chapter":5,"officialStep":24,"officialId":994021,"chapterSteps":58,"title":"ホットエンドファンの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994021","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["ホットエンドファン（1個） — 「Electronics」同梱","ホットエンドケーブルクリップ（Hotend-cable-clip）（1個） — 「Printed parts」同梱","M3x4rTネジ（2本）","M3x18ネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/01be82bb539b34be2c63a24b3b9ddcee-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"18b157ccdc5bcc33"},{"chapter":5,"officialStep":25,"officialId":994075,"chapterSteps":58,"title":"ホットエンドファンを取り付ける","description":"ファンのステッカーが奥側で見えなくなる向きにし、ケーブルを左下へ向けます。ヒートシンクの左側にM3x18の2本で固定してください。樹脂ケースが割れないよう、慎重に締めます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994075","checks":["ステッカーが奥側、ケーブルが左下で、M3x18の2本を締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/535f30c84a4c0ffa20d65f3a625f20d7-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"8b87c6f2fd24b27e"},{"chapter":5,"officialStep":26,"officialId":994109,"chapterSteps":58,"title":"ホットエンドファンのケーブルを通す","description":"Hotend-cable-clipを公式写真の向きに持ち、ファンとNTCのケーブルを一緒に右のフックへ通します。クリップをNextruderホルダーに合わせ、M3x4rTの2本で固定してください。","parts":["head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994109","checks":["ファンとNTCの2本が右フックを通り、クリップをM3x4rTの2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2901a3716256fad3aeec6970b2a64624-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2f35e70ff4641859"},{"chapter":5,"officialStep":27,"officialId":994147,"chapterSteps":58,"title":"LoveBoardの部品を準備する①","description":"Printhead-cover、Loveboard-mount、メインケーブルを用意します。ケーブルの色は製造ロットによって違いますが、組み立て方は変わりません。M3x10を4本、M3x8rTを1本、M3nSを5個用意し、次の部品表も確認してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994147","checks":["カバー、マウント、メインケーブルと、指定のねじ5本・M3nSを5個用意した"],"supplies":["プリントヘッドカバー（Printhead-cover）（1個） — 「Printed parts」同梱","LoveBoardマウント（Loveboard-mount）（1個） — 「Printed parts」同梱","メインケーブル（1本） — 「Electronics & Fasteners」同梱","M3x10ネジ（4本）","M3x8rTネジ（1本）","M3nSナット（5個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ce1be6bc5c0b6f74ee53abe65dfc3e3f-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"bb4cfd7ebde04217"},{"chapter":5,"officialStep":28,"officialId":994233,"chapterSteps":58,"title":"LoveBoardの部品を準備する②","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994233","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["LoveBoard基板（1枚） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9cf1145c691666758dbaae8f62ce642a-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"02bb53f7407b5aa6"},{"chapter":5,"officialStep":29,"officialId":994259,"chapterSteps":58,"title":"LoveBoardマウントを組み立てる","description":"Loveboard-mountのU字ケーブル溝の近くにM3nS角ナットを1個入れ、2.5 mm六角レンチで奥まで押します。反対側の穴にもM3nSを1個入れて、奥まで収めてください。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994259","checks":["M3nS角ナット2個を、それぞれの穴の奥まで入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e1e43c4ecb583ae46955c2b4fa54baec-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"91e75b022bec0e9c"},{"chapter":5,"officialStep":30,"officialId":994295,"chapterSteps":58,"title":"プリントヘッドカバーを組み立てる","description":"Printhead-coverの背面からM3nS角ナットを2個入れます。反対側からも1個入れ、合計3個を収めてください。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994295","checks":["背面から2個、反対側から1個のM3nSを入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/14735751176916b955810eee62d958ee-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"062bebf7e8cad886"},{"chapter":5,"officialStep":31,"officialId":994323,"chapterSteps":58,"title":"LoveBoardを組み付ける","description":"LoveBoardの端子を下に向け、M3x8rTで固定します。締め過ぎないでください。ホルダーを裏返し、白ラベルのない側のメインケーブルを接続します。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994323","checks":["端子が下を向き、白ラベルのない端をメイン端子に接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3376204667208a012f01844d53e7187e-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"af2cc08884b3d89f"},{"chapter":5,"officialStep":32,"officialId":994369,"chapterSteps":58,"title":"メインケーブルを通す","description":"メインケーブルを半回転ひねり、LoveBoardをまたいで反対側へ折り返します。基板一式を裏返し、ケーブルをLoveboard-mountの溝へ通してください。布スリーブの端を、樹脂部品の縁にそろえます。","parts":["head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994369","checks":["ケーブルが半回転して溝を通り、スリーブ端が樹脂部品の縁にそろっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0df39239debad313cf13bf1a75d33bdf-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"d5b28920e7c0290c"},{"chapter":5,"officialStep":33,"officialId":994423,"chapterSteps":58,"title":"LoveBoardにカバーを付ける","description":"LoveBoardのロゴを目印に、公式写真と同じ側からホルダーへM3x10を2本入れます。配線を挟まずにPrinthead-coverをかぶせ、M3x10の2本で固定してください。大きな隙間や、挟み込まれた布スリーブがないか確認します。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994423","checks":["M3x10の2本で固定され、大きな隙間や配線・スリーブの挟み込みがない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9beddbc00be23dfac84a2dd0eabf35c9-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"8ed4d15ae8d3dc3b"},{"chapter":5,"officialStep":34,"officialId":994485,"chapterSteps":58,"title":"スイングアームの部品を準備する①","description":"M5-4フィッティングと、710 × 4 × 2.5 mmのPTFEチューブを用意します。ねじとスイングアームは部品表の数量で取り出してください。結束バンド5本は重なった状態で入っているので、1本ずつ分けておきます。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994485","checks":["M5-4と710 mmチューブを含む部品を用意し、結束バンドを5本に分けた"],"supplies":["M3x8rTネジ（2本）","M3x10ネジ（1本）","継手 M5-4（1個） — 「Electronics & Fasteners」内の「Small parts & fasteners」袋","PTFEチューブ 710 x 4 x 2.5（1本） — 「CoreXY parts + Hinges set」同梱","スイングアームアセンブリ（1組） — 「Metal parts 3/3」同梱","結束バンド（5本） — 「Electronics & Fasteners」内の「Seals & Ties」袋"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/93dda9d197438cd886773f424e94c6c8-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"df3203298b82eca7"},{"chapter":5,"officialStep":35,"officialId":994571,"chapterSteps":58,"title":"スイングアームの部品を準備する②","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994571","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["PTFEチューブの曲げ部品（Bowden-bend）（1個） — 「Printed parts」同梱","メインケーブルクリップ（Main-cable-clip）（1個） — 「Printed parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1d5e588353d59b677040be214ad45427-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2b6b0bb88c28a5aa"},{"chapter":5,"officialStep":36,"officialId":994605,"chapterSteps":58,"title":"メインケーブルを通す","description":"Main-cable-clipを割らないよう慎重に開き、非対称の向きを公式写真に合わせてケーブルを挟みます。布スリーブの端から約5～15 cmの位置で閉じ、端まで移動させないでください。LoveBoard一式はヒートベッド上の箱に置き、ケーブルを右後方のCoreXYの後ろへ通します。","parts":["head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994605","checks":["クリップの向きを確認し、スリーブ端から5～15 cmを保ち、ケーブルを右後方へ通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4a65543b3192ec88a22b1e6f8938d17b-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"49e6b2f86b9cae4f"},{"chapter":5,"officialStep":37,"officialId":994657,"chapterSteps":58,"title":"メインケーブルを固定する","description":"右後方のYモーター側にある樹脂部品の穴へMain-cable-clipを合わせ、ケーブルごとM3x10で固定します。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994657","checks":["右後方の穴にクリップを合わせ、M3x10で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d8b070663a1d2d57ce24c99e344e3d6a-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"0fba217c6c37106b"},{"chapter":5,"officialStep":38,"officialId":994685,"chapterSteps":58,"title":"LoveBoardユニットを取り付ける","description":"Nextruderの後ろからLoveBoard一式を取り付け、Loveboard-mountの穴とヒートシンク上部のねじ穴を合わせます。M5-4継手をねじ込み、ユニバーサルレンチで締めてください。後ろ側のM3x10の2本も締めて固定します。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994685","checks":["M5-4継手と後ろのM3x10の2本でLoveBoard一式を固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a9a49606acf6f34751838f085a8fbbdd-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2e2273f7336d9ba2"},{"chapter":5,"officialStep":39,"officialId":994731,"chapterSteps":58,"title":"スイングアームを取り付ける","description":"背面パネル右上のねじ穴2か所へスイングアームを合わせ、M3x8rTの2本で固定します。ねじ山を傷めないよう、締めすぎないでください。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994731","checks":["背面右上にM3x8rTの2本で固定し、締めすぎていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4f7ff480063637114ce279a9049a2d51-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"2181c4adec45a388"},{"chapter":5,"officialStep":40,"officialId":994765,"chapterSteps":58,"title":"メインケーブルを取り付ける","description":"スイングアームの最初の切り欠きにメインケーブルを合わせます。公式写真と同じ向きで、切り欠きの後ろから結束バンドをアームとケーブルに回し、ロックへ通してしっかり締めてください。バンドを写真の位置へ回します。このバンドにはPTFEチューブを通しません。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994765","checks":["最初の切り欠きでメインケーブルだけを固定し、バンドの向きを写真に合わせた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/301ee22066b73359eb215035639ea7a2-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"40574ae5ad208f86"},{"chapter":5,"officialStep":41,"officialId":994827,"chapterSteps":58,"title":"PTFEチューブを入れる","description":"PTFEチューブをbowden-bendへ通し、先端を1 cm以上出します。チューブをNextruderのM5-4継手の奥まで差し込んでください。bowden-bendを下げ、継手を覆う位置へ合わせます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994827","checks":["チューブがM5-4の奥まで入り、bowden-bendが継手を覆っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6407a940ffb2acbaae4ad2f4809eafd6-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"5a5788117c06966f"},{"chapter":5,"officialStep":42,"officialId":994865,"chapterSteps":58,"title":"PTFEチューブを固定する","description":"PTFEチューブをメインケーブルの上へ平行に通します。最初のバンドには通さず、アームの残る切り欠き2か所でケーブルと一緒に固定してください。自由端をBowdenガイドとCoreXYプレートから下へ通し、垂らします。残り2本のバンドは10 cm間隔でチューブとケーブルをまとめます。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994865","checks":["PTFEがケーブルの上にあり、最初のバンドには入らず、残る切り欠き2か所で固定されている","チューブ端が下へ通り、残り2本のバンドが10 cm間隔になっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/27f732dca58b497948c4eb72f646e153-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"9985dc0ab2b6203e"},{"chapter":5,"officialStep":43,"officialId":994919,"chapterSteps":58,"title":"動きを確認する","description":"X・Yを手で端まで数回動かします。メインケーブルが張ってNextruderを後ろへ引かず、大きすぎる弧もできないか確認してください。合わない場合はクリップのネジを少し緩め、ケーブルを数mm上下へ調整します。締め直して、もう一度全範囲を確認します。","parts":["head"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994919","checks":["全範囲でケーブルがNextruderを引かず、大きすぎる弧もなく、クリップを締め直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d1d0a1f17d0d59b1d4c9ed07f6d4a12b-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"ffb130857e6bd415"},{"chapter":5,"officialStep":44,"officialId":994964,"chapterSteps":58,"title":"プリントファンの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["fan"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#994964","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["プリントファン（1個） — 「Electronics」同梱","ファンシュラウド（Fan-shroud）（1個） — 「Printed parts」同梱","M3x25ネジ（1本）","M3x10ネジ（2本）","M3nSナット（3個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9e27738461f058d7745f24671a45a3b2-800x600.jpg","reveal":["fan"],"add":[],"verificationRevision":"4478154ab4157100"},{"chapter":5,"officialStep":45,"officialId":995024,"chapterSteps":58,"title":"ファンシュラウドを組み立てる","description":"Fan-shroudの片側からM3nSを2個、反対側から1個入れます。ファンを公式写真の向きで差し込み、M3x25の1本で固定してください。ファンケースを傷めないよう、締めすぎないでください。","parts":["fan"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995024","checks":["M3nSが3個入り、ファンの向きを写真と合わせ、M3x25で締めすぎずに固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a1ede7b3a034d98298ca98b7c5c86635-800x600.jpg","reveal":["fan"],"add":[],"verificationRevision":"13ec1f2172bcdcc0"},{"chapter":5,"officialStep":46,"officialId":995078,"chapterSteps":58,"title":"プリントファンユニットを取り付ける","description":"ファン一式をNextruderの後ろへ合わせ、ブラケットとFan-shroudの穴をそろえます。NextruderホルダーへM3x10の2本で固定してください。","parts":["fan"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995078","checks":["後ろのブラケットに穴を合わせ、M3x10の2本でファン一式を固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3bd2100a9da665af5ad37b9f2af1afa4-800x600.jpg","reveal":["fan"],"add":["fan"],"verificationRevision":"109f8ba05f7e8a71"},{"chapter":5,"officialStep":47,"officialId":995114,"chapterSteps":58,"title":"ホットエンドの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995114","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["手締めネジ（2本） — 「Electronics」同梱","Prusaホットエンドアセンブリ（1組） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f0782fb151ccee1f8d53f0034cf7f157-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"6cec29c9e7835228"},{"chapter":5,"officialStep":48,"officialId":995148,"chapterSteps":58,"title":"ホットエンドを取り付ける","description":"ヒートシンクファンのケーブルを、公式写真で示す最初のねじ穴より上に通します。つまみネジ2本を、まず2回転だけ入れてください。配線を左へ向け、下からホットエンドを奥まで差し込みます。奥まで入った状態で、ノズルの真ちゅう部分とヒートシンクの隙間は約2 mmです。ホットエンドを押さえながら両ネジを締め、ケーブルを挟まないようにしてください。","parts":["head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995148","checks":["ヒートシンクファンのケーブルが、最初のねじ穴より上を通っている","約2 mmの隙間があり、ホットエンドを奥まで入れて固定した","つまみネジとヒートシンクの間に配線を挟んでいない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0e8b30962108e219297458c3e0f43d51-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"28534db87c4b902e"},{"chapter":5,"officialStep":49,"officialId":995226,"chapterSteps":58,"title":"ヒートシンクのケーブルを接続する","description":"NTCサーミスターはLoveBoardのメインケーブルより上の端子へ、ヒートシンクファンは左列の下側の端子へ接続します。","parts":["head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995226","checks":["NTCはメイン端子の上、ヒートシンクファンは左列の下に接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a1427247ff70883568cc77adfce20951-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"067285194f6cdd2d"},{"chapter":5,"officialStep":50,"officialId":995256,"chapterSteps":58,"title":"ホットエンドのケーブルを接続する","description":"ホットエンドの温度センサーとヒーターの配線を、Nextruderのケーブルクリップへ通します。それぞれを公式写真に示されたLoveBoardの端子へ接続してください。","parts":["head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995256","checks":["温度センサーとヒーターの2本をクリップへ通し、それぞれの接続先を写真と照合した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/74239ebe838c5cf2b8c51b5e2a8200af-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"72e3f436bcc1dd07"},{"chapter":5,"officialStep":51,"officialId":995286,"chapterSteps":58,"title":"プリントファンのケーブルを接続する","description":"プリントファンのケーブルを樹脂カバーの溝に通し、配線スペースにループを作ります。LoveBoardの中央の端子に接続してください。","parts":["head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995286","checks":["プリントファンを中央の端子に接続し、余長をループに収めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/233dbb7563195407280cea0f8acf9c70-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"fe721eded6375d78"},{"chapter":5,"officialStep":52,"officialId":995316,"chapterSteps":58,"title":"Eモーターのケーブルを接続する","description":"Eと表示されたNextruderモーターのケーブルを、上向きのコネクターへ接続します。Nextruder右側では、下から出るロードセルのケーブルを上のコネクターへ、上から出るフィラメントセンサーのケーブルを下のコネクターへ接続してください。ケーブルが出る位置と、接続先の上下を取り違えないよう、公式写真と照合します。","parts":["head"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995316","checks":["Eモーターのケーブルを、上向きのコネクターに接続した","下から出るロードセルのケーブルを、右側の上のコネクターに接続した","上から出るフィラメントセンサーのケーブルを、下のコネクターに接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1ce2beb843dbd25357355700aa8d70db-800x600.jpg","reveal":["head"],"add":[],"verificationRevision":"229bf87ad8036394"},{"chapter":5,"officialStep":53,"officialId":995354,"chapterSteps":58,"title":"LoveBoardカバーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["ventLever","head"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995354","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["レバー付き右プリントヘッドカバー（Print-head-cover-right-lever）（1個） — 「Printed parts」同梱","左プリントヘッドカバー（Printhead-cover-left）（1個）","M3x10ネジ（1本）","M3x6ネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/04a8bb986d09126070d3f3aaf592fdca-800x600.jpg","reveal":["ventLever","head"],"add":[],"verificationRevision":"e1a2233277a4d865"},{"chapter":5,"officialStep":54,"officialId":995449,"chapterSteps":58,"title":"LoveBoardの配線を確認する","description":"カバーを付ける前に、公式写真を拡大して全ケーブルの接続を照合します。配線束をLoveBoard側へ収め、外へ張り出してカバーに干渉しないようにしてください。","parts":["ventLever","head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995449","checks":["全ケーブルの接続先を照合し、配線束がカバーの取り付けを妨げない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/01/42462baffd69e455-800x600.jpg","reveal":["ventLever","head"],"add":[],"verificationRevision":"33b2304ee29b7401"},{"chapter":5,"officialStep":55,"officialId":995406,"chapterSteps":58,"title":"LoveBoardにカバーを取り付ける","description":"左カバーをM3x10の1本、右レバー付きカバーをM3x6の2本で固定します。配線を挟まないでください。メインケーブルを背面パネル右側の上の穴へ通し、端はまだ接続せず垂らしておきます。","parts":["ventLever","head"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995406","checks":["左右のカバーに正しいネジを使い、配線を挟まず、メインケーブルを上の穴へ通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/01/8e31b223cbf2f1c0-800x600.jpg","reveal":["ventLever","head"],"add":["ventLever"],"verificationRevision":"3b719def7bf8b277"},{"chapter":5,"officialStep":56,"officialId":995519,"chapterSteps":58,"title":"メインケーブルを通す","description":"プリンターの背面を手前に向けます。メインケーブルをxBuddyケースの左穴から通し、xBuddy基板の右側の端子へ接続してください。短い・張る場合は手順6.36へ戻り、クリップからケーブルを少し下へ引き出して調整します。ケース内のバンドで配線を固定し、ケーブルを切らないよう余りを切ります。","parts":["ventLever","head"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995519","checks":["メインケーブルをxBuddy右側へ無理なく接続し、バンドで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/52c0b7f627d592a9-800x600.jpg","reveal":["ventLever","head"],"add":[],"verificationRevision":"6a8349593e1322cf"},{"chapter":5,"officialStep":57,"officialId":995573,"chapterSteps":58,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの5列目が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["ventLever","head"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995573","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/07939a9fef99d16db75d800d9a0527e7-800x600.jpg","reveal":["ventLever","head"],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":5,"officialStep":58,"officialId":995607,"chapterSteps":58,"title":"Nextruderの組み立てを確認する","description":"Nextruderの組み立てはここまでです。未確認の手順がないか見直してから、外装・電子部品の章へ進みます。","parts":["ventLever","head"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/6-nextruder-assembly_982284#995607","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/02b0812a6e71059d54eb99256c3c7fc7-800x600.jpg","reveal":["ventLever","head"],"add":[],"verificationRevision":"1244d7ec7442a18d"},{"chapter":6,"officialStep":1,"officialId":995633,"chapterSteps":44,"title":"この章で使う工具","description":"1.5 mmと2.5 mmの六角レンチ、T10トルクス、ラジオペンチを用意します。ニッパーは任意です。","parts":["frame"],"tip":"","kind":"prepare","time":1,"tools":["2.5 mm 六角レンチ","1.5 mm 六角レンチ","T10 トルクスレンチ","ラジオペンチ","ニッパー（任意）"],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995633","checks":["1.5 mmと2.5 mmの六角レンチ、T10トルクス、ラジオペンチを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8bb1a8826f85d390-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"512927b2ea67fdbd"},{"chapter":6,"officialStep":2,"officialId":995695,"chapterSteps":44,"title":"前面プロファイルの部品を準備する","description":"前面左プロファイルは上部の丸穴が2個、右プロファイルは1個です。穴の数で左右を見分け、各1本とM3x4rTを8本用意してください。","parts":["frame"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995695","checks":["丸穴2個の左プロファイルと丸穴1個の右プロファイルを選んだ"],"supplies":["左前プロファイル（1本） — 「Metal parts 1/3」同梱","右前プロファイル（1本） — 「Metal parts 1/3」同梱","M3x4rTネジ（8本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/48a13b8029a0da1b62715c2c928d78ff-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"daf306e3806139ff"},{"chapter":6,"officialStep":3,"officialId":995755,"chapterSteps":44,"title":"右前プロファイルを取り付ける","description":"大きな丸穴が1つある右前プロファイルを使います。ベルト調整ねじ用の穴と小さいねじ穴を合わせ、CoreXY側をM3x4rTの2本、底部を同じねじ2本で固定してください。穴が合わない場合は、上下のロッドマウントへスムースロッドが奥まで入っているか確認します。","parts":["frame"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995755","checks":["丸穴1つの右前プロファイルを使い、上下各2本のM3x4rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d899eca1a9aa33bb4b2211247ed11662-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"260aedc067073b81"},{"chapter":6,"officialStep":4,"officialId":995809,"chapterSteps":44,"title":"左前プロファイルを取り付ける","description":"大きな丸穴が2つある左前プロファイルを使います。ドアセンサーのレバーを曲げないよう穴を合わせ、CoreXY側をM3x4rTの2本、底部を同じねじ2本で固定してください。","parts":["frame"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995809","checks":["丸穴2つの左前プロファイルを上下各2本で固定し、センサーレバーを曲げていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6a41fd8f4af4bdc7497586e1e078aa61-800x600.jpg","reveal":["frame"],"add":["frame"],"verificationRevision":"10e011e8c9572517"},{"chapter":6,"officialStep":5,"officialId":995863,"chapterSteps":44,"title":"上部プロファイルの部品を準備する","description":"上部プロファイルを3本、穴が2個ある上部背面プロファイルを1本用意します。ねじはM3x4rTを8本と、頭の形が違うM3x4を4本です。混ぜずに分けて置き、ナイロンリベット3個も用意してください。","parts":["frame"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995863","checks":["穴2個の背面用を見分け、M3x4rTを8本とM3x4を4本に分けた"],"supplies":["上部プロファイル（3本） — 「Metal parts 1/3」同梱","上部後ろプロファイル（1本） — 「Metal parts 1/3」同梱。部品の2つの穴を確認","M3x4rTネジ（8本）","M3x4ネジ（4本） — ネジ頭の形状が異なるもの","ナイロンリベット（3個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d8f481869688ee670ea044b6c25e1be6-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"c23ae6fe771f358c"},{"chapter":6,"officialStep":6,"officialId":995917,"chapterSteps":44,"title":"上部プロファイルを組み立てる①","description":"板金の鋭い縁に注意してください。穴が2つある上部プロファイルを、平らな側を下にして公式写真の向きに置き、左隣に別の上部プロファイルを合わせます。フランジは左側のプロファイルの下へ差し込み、M3x4を1本使って接合してください。残り2本も同様にM3x4を1本使い、もう1つの角を作ります。","parts":["frame"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995917","checks":["2組の角を作り、フランジが相手のプロファイルの下に入っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1514fbd4d95f3363147dcb274e6672ba-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"a5d27b718570eba1"},{"chapter":6,"officialStep":7,"officialId":995995,"chapterSteps":44,"title":"上部プロファイルを組み立てる②","description":"2組の角を合わせ、フランジを相手のプロファイルの下に入れます。穴を合わせ、M3x4の2本で接合してください。","parts":["frame"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#995995","checks":["フランジを下に重ね、2組の角をM3x4の2本で接合した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8a506d2f3f8d78d1a901e8a128545efc-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"313dad68225c03df"},{"chapter":6,"officialStep":8,"officialId":996029,"chapterSteps":44,"title":"上部プロファイルの位置を合わせる","description":"中央に開口が2つあるプロファイルを後ろにして、上部一式を載せます。後ろの突き出た部分は背面板金の後ろへ、側面と前面はねじ穴付きタブの上へ収めてください。","parts":["frame"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996029","checks":["開口2つが後ろで、背面は板金の後ろ、前面と側面はタブの上に収まっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a674bdc20e5a5027ee55a3779654c346-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"e6ea080ccc6bb55d"},{"chapter":6,"officialStep":9,"officialId":996073,"chapterSteps":44,"title":"上部プロファイルを取り付ける","description":"上部プロファイルの位置が合ったら、角の残りの穴をM3x4rTの8本で固定します。背面パネルと上部プロファイルは、ナイロンリベット3本で接合してください。","parts":["frame"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996073","checks":["上部をM3x4rTの8本、背面との接合部をリベット3本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6f414ad36449fb8b10bbd0bcae132b9a-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"1b42e458a290fd2a"},{"chapter":6,"officialStep":10,"officialId":996103,"chapterSteps":44,"title":"CoreXY固定用ネジを準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["frame"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996103","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["M3x4rTネジ（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b24ef0c567dbc7d9e65bceb688775e89-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"165af582f23f7ccb"},{"chapter":6,"officialStep":11,"officialId":996129,"chapterSteps":44,"title":"CoreXYユニットを固定する","description":"CoreXYのねじ穴を背面プロファイルの開口へ合わせます。必要に応じてCoreXYを少し持ち上げ、指定位置のM3x4rTの4本で固定してください。","parts":["frame"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996129","checks":["背面の指定位置へM3x4rTの4本を入れ、CoreXYを固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1c26df973f3d3632ef3ebbf127bddc94-800x600.jpg","reveal":["frame"],"add":[],"verificationRevision":"ca2a53ce7bbdbf46"},{"chapter":6,"officialStep":12,"officialId":996155,"chapterSteps":44,"title":"側面センサーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["sensorBody","sensorLever"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996155","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["フィラメントセンサー本体（Filament-sensor-body）（1個） — 「Printed parts」同梱","フィラメントセンサーレバー（Filament-sensor-lever）（1個） — 「Printed parts」同梱","フィラメントセンサースイッチ（Filament-sensor-switch）（1個） — 「Printed parts」同梱","M3x10ネジ（1本）","磁石 10x6x2mm（2個） — 「Electronics & Fasteners」同梱","磁性ボール 7mm（1個） — 「Electronics & Fasteners」同梱","M3wワッシャー（1枚）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/43992467cafe9ee394a0c5160137f4f7-800x600.jpg","reveal":["sensorBody","sensorLever"],"add":[],"view":"right","verificationRevision":"e1eee797b44e778c"},{"chapter":6,"officialStep":13,"officialId":996213,"chapterSteps":44,"title":"側面センサーのベースを組み立てる","description":"レバーへ磁石を入れ、センサーベース内側の穴へボールを置きます。磁石側がボールの隣になるようレバーを入れ、磁石に引かれたボールが穴から外れていないか確認してください。M3wワッシャーとM3x10で保持しますが、ねじは数回転だけ入れ、本締めしません。締め切るとレバーが動かなくなります。","parts":["sensorBody","sensorLever"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996213","checks":["ボールが穴に収まり、M3wとM3x10で保持したレバーは本締めしていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4078daa4c0e22ba2895c7f7c21cb92f1-800x600.jpg","reveal":["sensorBody","sensorLever"],"add":[],"view":"right","verificationRevision":"3bfa2c4e15dc39d1"},{"chapter":6,"officialStep":14,"officialId":996267,"chapterSteps":44,"title":"レバーの動きを確認する","description":"レバーが引っかからずに動くことを確認します。動きが重い、または動かない場合は、ねじを¼回転緩めて再度試してください。レバーのねじは本締めしません。","parts":["sensorBody","sensorLever"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996267","checks":["レバーが引っかからずに動き、ねじを本締めしていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0b64f98dc39c1da6c6dcda30c1b58115-800x600.jpg","reveal":["sensorBody","sensorLever"],"add":[],"verificationRevision":"5e85eda91ea77a34"},{"chapter":6,"officialStep":15,"officialId":1014196,"chapterSteps":44,"title":"スイッチを組み立てる","description":"この手順全体を読んでから、2個目の10x6x2磁石をfilament-sensor-switchへ入れ、スイッチを本体へ組み込みます。スイッチを左端へ動かして磁石同士を向かい合わせ、反発することを確認してください。引き合う場合はスイッチ側の磁石を外して裏返し、もう一度確かめます。細い六角レンチやトルクスレンチで磁石を押し出せます。","parts":["sensorBody","sensorLever","sensorSwitch"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#1014196","checks":["スイッチを左端にしたとき、2個の磁石が引き合わず反発する"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4e814369dcca7b06bb2b81944483b3a2-800x600.jpg","reveal":["sensorBody","sensorLever","sensorSwitch"],"add":[],"verificationRevision":"602266b098f21991"},{"chapter":6,"officialStep":16,"officialId":996357,"chapterSteps":44,"title":"IRセンサーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["sensorBody"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996357","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["サイドフィラメントセンサーケーブル（1本） — 「Electronics & Fasteners」同梱","IRフィラメントセンサー（1個） — 「Electronics & Chamber parts」同梱","サイドフィラメントセンサーカバー（1個） — 「Printed」同梱","M2x8ネジ（1本）","M3x10ネジ（2本）","M3nSナット（2個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f3ee93c588f52e4584162592497bce50-800x600.jpg","reveal":["sensorBody"],"add":[],"view":"right","verificationRevision":"73039d1f6d0e8785"},{"chapter":6,"officialStep":17,"officialId":996425,"chapterSteps":44,"title":"IRセンサーを接続する","description":"IRフィラメントセンサーへケーブルを接続します。CORE One用の配線は、茶色が「+5V」、白が「GND」です。基板のピン表示と向きを照合してから差し込んでください。","parts":["sensorBody"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996425","checks":["基板表示と照合し、茶色を+5V、白をGNDへ接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/012b5de036cdcb501846a536127db95e-800x600.jpg","reveal":["sensorBody"],"add":[],"view":"right","verificationRevision":"21b732948a778a19"},{"chapter":6,"officialStep":18,"officialId":996469,"chapterSteps":44,"title":"IRセンサーを取り付ける","description":"先にケーブルを溝へ入れ、黒いコネクターをセンサーベースの中央付近に置きます。IR基板を専用の溝に入れ、レバーがセンサーの光学ゲート内に収まるよう合わせてください。コネクターもケーブルもレバーに触れないことを確認し、1.5 mm六角レンチでM2x8を締めて基板を固定します。","parts":["sensorBody"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996469","checks":["ケーブルが溝に入り、黒いコネクターがベースの中央付近にある","IR基板をM2x8で固定し、光学ゲート内のレバーに配線やコネクターが触れていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/482613e1dd94b707f53a4e48903b99c8-800x600.jpg","reveal":["sensorBody"],"add":[],"view":"right","verificationRevision":"2bc90c4af71296e1"},{"chapter":6,"officialStep":19,"officialId":996523,"chapterSteps":44,"title":"側面センサーのカバーを取り付ける","description":"M3nS角ナット2個を入れ、1.5 mm六角レンチで奥まで押します。横から見てねじ穴が合っていることを確かめ、カバーを左右のM3x10の2本で固定してください。中央のねじは締めません。締めるとセンサーが動作しなくなります。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996523","checks":["左右のM3x10でカバーを固定し、中央ねじは締めていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/52e659a0e6ea34315d3dd17caa21b795-800x600.jpg","reveal":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"add":[],"view":"right","verificationRevision":"7e9b3b6d936f3eed"},{"chapter":6,"officialStep":20,"officialId":996577,"chapterSteps":44,"title":"側面センサー取り付けの準備","description":"この手順で使用する部品・工具を用意してください。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996577","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["サイドフィラメントセンサーアセンブリ（1組） — 前の手順で組み立てたもの","コレット（1個） — 「Electronics & Fasteners」同梱","結束バンド（3本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ca619889236cab222ecec6ccc31fbd38-800x600.jpg","reveal":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"add":[],"view":"right","verificationRevision":"d0728bac846c61db"},{"chapter":6,"officialStep":21,"officialId":996619,"chapterSteps":44,"title":"側面フィラメントセンサーを取り付ける","description":"金属プロファイルの下でケーブルを固定するため、指定の穴へ結束バンドを1本通します。センサーへコレットを入れ、プリンター側のPTFEチューブをセンサーへ奥まで差し込んでください。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996619","checks":["結束バンドとコレットを入れ、PTFEチューブをセンサーの奥まで差し込んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0699f2c08d3c22d4b07782f21e9cfdd6-800x600.jpg","reveal":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"add":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"view":"right","verificationRevision":"2cc64d4a63fd3ce5"},{"chapter":6,"officialStep":22,"officialId":996665,"chapterSteps":44,"title":"センサーのケーブルを通す","description":"センサーをフレームの高さの中央付近へ移動して配線を合わせます。プロファイルの下で結束バンドを軽く締め、後で調整できる余裕を残して余りを切ってください。専用の開口から背面へケーブルを通し、xBuddyボックス内へ入れます。まだ接続はしません。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996665","checks":["プロファイル下のバンドは調整できる締め加減で、ケーブルを背面からxBuddy内へ通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/687159b9c12e5fd31577759b8b67c3ad-800x600.jpg","reveal":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"add":[],"view":"right","verificationRevision":"559585fb31d854ac"},{"chapter":6,"officialStep":23,"officialId":996711,"chapterSteps":44,"title":"側面センサーを接続する","description":"側面センサーのケーブルを、xBuddy拡張基板の上側にある「FILAMENT」端子へ接続します。必要ならラジオペンチで補助し、配線を傷めないようにしてください。指定位置を結束バンド2本でまとめ、下の板金の開口2つをふさがないよう束をできるだけ高い位置に固定します。締めすぎたりケーブルを強く引っ張ったりしないでください。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996711","checks":["側面センサーを拡張基板のFILAMENTへ接続した","下の開口2つをふさがず、配線を引っ張らない位置で2本のバンドを留めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5cd5f937a6b030ff3dd28b8f88742c05-800x600.jpg","reveal":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"add":[],"view":"right","verificationRevision":"e6876c51eeec00c7"},{"chapter":6,"officialStep":24,"officialId":996763,"chapterSteps":44,"title":"NFCアンテナの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics","covers"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996763","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["電子基板ケースのカバー（El-box-cover）（1個） — 「Printed parts」同梱","M3x10ネジ（2本）","NFCコイル（1個） — 「Electronics & Chamber parts」同梱","接着フィルム 32 x 25 mm（1枚） — 「Electronics & Chamber parts」同梱","NFCコイルケーブル（1本） — 「Electronics & Chamber parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/aa5da745a7d8ab2917b5ceef7b8e8f22-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"7018ae9f2dd5fc59"},{"chapter":6,"officialStep":25,"officialId":996821,"chapterSteps":44,"title":"粘着フィルムを貼る","description":"粘着シートの黄色い保護フィルムを剥がし、NFCコイルの平らな面へしっかり貼ります。コイルに残った保護フィルムも剥がしてください。","parts":["electronics","covers"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996821","checks":["粘着シートをNFCコイルの平らな面へ貼り、保護フィルムを剥がした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/15b3cb58b3843d18bdd2fc393afaa53e-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"db37e5d4bb9e424a"},{"chapter":6,"officialStep":26,"officialId":996859,"chapterSteps":44,"title":"NFCコイルを取り付ける","description":"NFCコイルをEl-box-coverの内側へ、公式写真に合わせて貼ります。小さな丸いコネクターはカバーの縁に近い側へ向けてください。端子をまっすぐ合わせ、均等に軽く押し、はまる感触を確かめます。ずれたまま押したり、強く押したりすると破損します。金属工具で押し込まないでください。","parts":["electronics","covers"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996859","checks":["NFCコイルをカバーの内側に貼り、丸いコネクターが縁に近い側にある","コネクターをまっすぐ合わせ、軽く均等に押してはまる感触を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7899d4fb4dfd50157ca166fc125beeda-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"a994fc67678f5d48"},{"chapter":6,"officialStep":27,"officialId":996903,"chapterSteps":44,"title":"NFCコイルを接続する","description":"xBuddyの左下にある小さな丸形「NFC」端子を探します。コイル側の端子をまっすぐ合わせ、カチッと入るまで軽く押してください。","parts":["electronics","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996903","checks":["コイルの端子をxBuddy左下のNFCへ合わせ、クリックするまで入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/40bab9043a8e6a721b88613d3c1348ca-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"91300bb4461a4817"},{"chapter":6,"officialStep":28,"officialId":996933,"chapterSteps":44,"title":"配線を確認する","description":"公式写真と見比べ、電子部品の各接続を確認します。コネクターがすべて奥まで入り、電源ユニットのケーブルを留めるねじがしっかり締まっていることを確かめてから、カバーの取り付けへ進んでください。","parts":["electronics","covers"],"tip":"","kind":"connect","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996933","checks":["写真で全接続を照合し、コネクターの挿入と電源ケーブルのねじ締めを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a6fea97660b6acac8bd80ab50e5e8015-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"2af876e4e5f763fe"},{"chapter":6,"officialStep":29,"officialId":996961,"chapterSteps":44,"title":"電子部品のカバーを準備する","description":"El-box-coverへM3x10の2本を通し、次の手順で取り付けられるようにします。","parts":["electronics","covers"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996961","checks":["El-box-coverにM3x10の2本を通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d83f939f2cc31f1e-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"088c956a2e6af802"},{"chapter":6,"officialStep":30,"officialId":996979,"chapterSteps":44,"title":"電子部品のカバーを取り付ける","description":"xBuddyボックス下部のねじ穴をケーブルがふさいでいれば、先に配線をよけます。NFCケーブルはEthernet端子と電源ケーブルの間の隙間へ通してください。端子や電源線の上を横切らせないようにして、カバーを開口へ合わせ、ネジを締めて固定します。閉じるときにNFCケーブルを挟まないよう確認してください。","parts":["electronics","covers"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#996979","checks":["ねじ穴が配線でふさがれておらず、NFCケーブルをEthernetと電源線の間の隙間へ通した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7c56ec267a8053d6f52487b3b0944a9a-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"9939a38495a1d5f4"},{"chapter":6,"officialStep":31,"officialId":997032,"chapterSteps":44,"title":"Buddy3Dカメラについて","description":"Buddy3D Cameraを使う場合は、先に配線したUSBケーブルを使います。下の専用公式ガイドへ戻り、カメラの取り付けと接続手順を確認してください。使わない場合は次へ進めます。","parts":["electronics","covers"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997032","checks":["カメラを使う場合は専用ガイドを確認し、使わない場合はこの手順を省略した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0d0face7d711cb1c7c6374cde65dbd6b-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"7d2450dcda0fc91a","references":[{"label":"Buddy3D Cameraの公式取り付けガイド","url":"https://help.prusa3d.com/guide/buddy3d-camera-for-core-one-installation_405529"}]},{"chapter":6,"officialStep":32,"officialId":997066,"chapterSteps":44,"title":"xBuddyカバーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["electronics","covers"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997066","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["金属製の背面カバー（1枚） — 「Metal parts 2/3」同梱","xBuddyカバー（1枚） — 「Metal parts 3/3」同梱","M3x4rTネジ（8本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/aaca592e8ba48f13b63860cb3f938325-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"163728533d80e0b4"},{"chapter":6,"officialStep":33,"officialId":997110,"chapterSteps":44,"title":"xBuddyカバーを取り付ける","description":"写真どおりボックス内の配線を整え、NFCケーブルの位置をもう一度確認します。カバーの折り曲げ部を先に差し込み、基板に対して垂直に入れてください。ケーブルを挟まず、M3x4rTの6本で固定します。","parts":["electronics","covers"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997110","checks":["NFCを含む配線を挟まず、折り曲げ部を先に入れて6本のM3x4rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/17e0e0fe46758ebd-800x600.jpg","reveal":["electronics","covers"],"add":[],"verificationRevision":"93389f4a9b072df3"},{"chapter":6,"officialStep":34,"officialId":997154,"chapterSteps":44,"title":"背面カバーを取り付ける","description":"ケーブルがトレー部分を通る向きで背面板金カバーをくぼみに入れます。プリンターへ押し付けてから上へスライドし、4つのタブを掛けてください。内側からM3x4rTの2本で固定します。","parts":["covers","filter"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997154","checks":["ケーブルをトレーへ収め、4つのタブを掛けて内側から2本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d318de292a83ee4a12b222066bf19bb4-800x600.jpg","reveal":["covers","filter"],"add":["filter"],"verificationRevision":"5c98b51aea712e8a"},{"chapter":6,"officialStep":35,"officialId":997200,"chapterSteps":44,"title":"右側面の部品を準備する","description":"中央にねじ穴があるパネルを右側面用に選びます。M3x8rTを4本、Puck-universalを1個、作業を支える段ボール箱を用意してください。Prusamentの箱も使えます。","parts":["sideRight","puck"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997200","checks":["中央のねじ穴で右パネルを見分け、パック、M3x8rTを4本、支えの箱を用意した"],"supplies":["右側の金属パネル（1枚） — 「Metal parts 2/3」同梱","M3x8rTネジ（4本） — 「Electronics & fasteners」同梱","スプールホルダーの取付部品（Puck-universal）（1個）","段ボール箱（1個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b8d365a5a41dddab4f71f72004573f0c-800x600.jpg","reveal":["sideRight","puck"],"add":[],"view":"right","verificationRevision":"b2f55ed8979a4b4e"},{"chapter":6,"officialStep":36,"officialId":997250,"chapterSteps":44,"title":"ユニバーサルパックを取り付ける","description":"Puck-universalをねじ穴が上になるよう段ボール箱に載せ、右パネルを箱の中央で重ねます。穴を合わせ、M3x8rTの4本で固定してください。このねじは樹脂にねじ山を作るため、回すときに抵抗があります。","parts":["sideRight","puck"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997250","checks":["箱で支えながらPuck-universalと右パネルをM3x8rTの4本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0a48b570eb7688ffd2d9f3bd0412a0d2-800x600.jpg","reveal":["sideRight","puck"],"add":["puck"],"view":"right","verificationRevision":"5581fb47672c2068"},{"chapter":6,"officialStep":37,"officialId":997288,"chapterSteps":44,"title":"右ハンドルの部品を準備する","description":"右ハンドル、コレット、45 mmの短いPTFEチューブを1個ずつ、M3x8rTを2本、ナイロンリベットを11個用意します。PTFEの寸法は4 × 2.5 × 45 mmで、CoreXY parts + Hinges setのヒンジ部品と一緒に入っています。","parts":["handleRight"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997288","checks":["45 mmチューブを含む右ハンドル部品と、M3x8rTを2本用意した"],"supplies":["サイドハンドル（1個） — 「Printed parts」同梱","M3x8rTネジ（2本）","コレット（1個） — 「Electronics & Fasteners」同梱","PTFEチューブ 4 x 2.5 x 45 mm（1本） — 「CoreXY parts + Hinges set」内。ヒンジの部品と同梱","ナイロンリベット（11個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f92fdf7d5dbecaa65c2c316774625902-800x600.jpg","reveal":["handleRight"],"add":[],"view":"right","verificationRevision":"1f40c77e45facffb"},{"chapter":6,"officialStep":38,"officialId":997348,"chapterSteps":44,"title":"コレットを取り付ける","description":"右ハンドルへコレットを奥まで押し込んでください。","parts":["handleRight"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997348","checks":["ハンドルのコレットが奥まで入っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6512fee48b939e3a7ba9c33eed32c23e-800x600.jpg","reveal":["handleRight"],"add":[],"verificationRevision":"263debb1bc63edaa"},{"chapter":6,"officialStep":39,"officialId":997376,"chapterSteps":44,"title":"右ハンドルを取り付ける","description":"右側板のU字切り欠きを上にし、ハンドル後ろの穴からM3x8rTを通します。板とハンドルを支えたまま側面センサーをねじへ掛けてください。ケーブルを引っ張らないよう板をプリンターへ近づけます。ナットが動ける程度に軽く締め、センサーを前側の穴へ合わせます。","parts":["handleRight"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997376","checks":["側板を近づけてセンサーを引っ張らず、後ろねじを仮締めして前穴を合わせた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4e4e7337c5a4edfc819ef147bbba9904-800x600.jpg","reveal":["handleRight"],"add":["handleRight"],"view":"right","verificationRevision":"2121700d0534d74d"},{"chapter":6,"officialStep":40,"officialId":997446,"chapterSteps":44,"title":"右側面を固定する","description":"2本目のM3x8rTで、右ハンドルと側面センサーを側板へ固定します。側板はナイロンリベット11本でプリンターへ留めてください。短いPTFEチューブ4x2.5x45をハンドルのコレットへ奥まで入れます。チューブの一部は外へ残ります。","parts":["sideRight","handleRight","puck"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997446","checks":["2本目のM3x8rTとリベット11本を取り付け、短いPTFEをコレットの奥まで入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/fa981b4faba9a174c1417a787ded3e34-800x600.jpg","reveal":["sideRight","handleRight","puck"],"add":["sideRight"],"view":"right","verificationRevision":"71ba400171f4ad4f"},{"chapter":6,"officialStep":41,"officialId":997492,"chapterSteps":44,"title":"左側面の部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["sideLeft","handleLeft"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997492","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["左側の金属パネル（1枚） — 「Metal parts 2/3」同梱","サイドハンドル（1個） — 「Printed parts」同梱","M3x5rTネジ（2本）","ナイロンリベット（11個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/63674cd5006e90a3ae277204249a123f-800x600.jpg","reveal":["sideLeft","handleLeft"],"add":[],"view":"right","verificationRevision":"87d7f48c9b150e19"},{"chapter":6,"officialStep":42,"officialId":997544,"chapterSteps":44,"title":"左側面を取り付ける","description":"左ハンドルを側板のねじ穴へ合わせ、M3x5rTの2本で固定します。左側板をナイロンリベット11本でプリンターへ留めてください。","parts":["sideLeft","handleLeft"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997544","checks":["左ハンドルはM3x5rTの2本、左側板はリベット11本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0ae8338026b6ce94352d8095f0f15fc1-800x600.jpg","reveal":["sideLeft","handleLeft"],"add":["sideLeft","handleLeft"],"view":"right","verificationRevision":"4fe92554bd030b34"},{"chapter":6,"officialStep":43,"officialId":997580,"chapterSteps":44,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの6列目が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["sideLeft","handleLeft"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997580","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6c0a61b9a63c9a8bb69f39628b20c8b6-800x600.jpg","reveal":["sideLeft","handleLeft"],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":6,"officialStep":44,"officialId":997614,"chapterSteps":44,"title":"外装・電子部品を確認する","description":"外装・電子部品の章はここまでです。未確認の手順がないか見直してから、カバー・ドア・xLCDの章へ進みます。","parts":["sideLeft","handleLeft"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/7-bodywork-electronics_982292#997614","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/1f91211d644a2b1dd34f398e4efcec5a-800x600.jpg","reveal":["sideLeft","handleLeft"],"add":[],"verificationRevision":"1244d7ec7442a18d"},{"chapter":7,"officialStep":1,"officialId":997640,"chapterSteps":46,"title":"この章で使う工具","description":"2.5 mm六角レンチ、T10トルクス、ラジオペンチを用意します。","parts":["top","grille","ventBlock"],"tip":"","kind":"prepare","time":1,"tools":["2.5 mm 六角レンチ","T10 トルクスレンチ","ラジオペンチ"],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997640","checks":["2.5 mm六角レンチ、T10トルクス、ラジオペンチを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8bb1a8826f85d390-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"verificationRevision":"e687f76dd7b9e041"},{"chapter":7,"officialStep":2,"officialId":997684,"chapterSteps":46,"title":"トップカバーの部品を準備する","description":"トップカバー、ベントカバー、Upg-vent-blockと部品表の金具を用意します。この組み立てではM3x12rTを3本使います。断熱インサート3個は灰色でも黒でも形は同じで、組み立て方は変わりません。","parts":["top","grille","ventBlock"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997684","checks":["M3x12rTを3本選び、断熱インサート3個とカバー類を用意した"],"supplies":["トップカバー（1枚） — 「Plexi set」同梱","ベントカバー（1個） — 「Plexi set」同梱","M3nNナット（3個）","絶縁インサート（3個） — 「Electronics & Fasteners」同梱","M3x12rTネジ（3本）","ナイロンリベット（4個）","ベントブロック（Upg-vent-block）（1個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b1c470c81f8ec99d40a6ac90aac4ebe1-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"view":"top","verificationRevision":"e4b3a7556d20c516"},{"chapter":7,"officialStep":3,"officialId":997762,"chapterSteps":46,"title":"保護フィルムを剥がす","description":"トップカバー用の樹脂板2枚から保護フィルムを剥がします。裏返し、反対側のフィルムも剥がしてください。","parts":["top","grille","ventBlock"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997762","checks":["樹脂板2枚の両面から保護フィルムを剥がした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d5a62066af19827f0c50ed0656595e13-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"verificationRevision":"923b49541ff8f229"},{"chapter":7,"officialStep":4,"officialId":997790,"chapterSteps":46,"title":"トップカバーを仮合わせする","description":"ベントの開口をプリンター前方に向け、上部カバーをくぼみに仮合わせします。四隅のネジ頭が切り欠きに収まることを確認してください。カバーは非対称です。穴が合わない場合はカバーを裏返し、公式写真に合わせて向きを確認し直します。","parts":["top","grille","ventBlock"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997790","checks":["ベントが前方にあり、四隅の切り欠きが合う"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/736853856c474bd1cfa0ebe512a695c5-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"view":"top","verificationRevision":"600344d9f4ff5d40"},{"chapter":7,"officialStep":5,"officialId":997834,"chapterSteps":46,"title":"トップカバーを組み立てる①","description":"組み立てキットでは3本ともM3x12rTを使います。インサートのつばをネジ頭側に向け、カバーの外側から3つのスロットに通してください。","parts":["top","grille","ventBlock"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997834","checks":["3本ともM3x12rTで、つばがネジ頭側を向いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a9a32cfaec625669c6dc3b15a391505f-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"view":"top","verificationRevision":"9f8eda85c85aef29"},{"chapter":7,"officialStep":6,"officialId":1044337,"chapterSteps":46,"title":"トップカバーを組み立てる②","description":"上部カバーの前側を持ち上げ、内側へベントカバーを合わせます。非対称の部品なので公式写真で向きを確認してください。左へスライドすると開き、右へ動かすと閉じます。右端のM3nNをM3x12rTへ軽く仮止めし、Upg-vent-blockを残り2個のM3nNで取り付けます。ベントとブロックはプリンター内側へ向け、開口をブロックでふさがないようにしてください。ナットをラジオペンチかユニバーサルレンチで支え、がたがなくなる程度に締めます。動きを妨げない緩さを残してください。","parts":["top","grille","ventBlock"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1044337","checks":["ブロックは内側を向き、開いたベントをふさいでいない","3個のナットはがたを取る程度に締め、ベントがスライドできる緩さを残した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/d48b5c7cd09652ec28d8bd4a2ba5a080-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"view":"top","verificationRevision":"a8e8a9a65d698409"},{"chapter":7,"officialStep":7,"officialId":997916,"chapterSteps":46,"title":"ベントの動きを確認する","description":"ネジ1本を手で動かし、ベントを開閉します。左に動かすと開き、右に動かすと閉じます。重い場合は、動きを妨げているネジを緩めてください。","parts":["top","grille","ventBlock"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997916","checks":["ベントが引っかからず、軽く全開・全閉に動く"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/98db2422bc898cf31fa1fefb87aa07a8-800x600.jpg","reveal":["top","grille","ventBlock"],"add":[],"verificationRevision":"d9767d4204e7990f"},{"chapter":7,"officialStep":8,"officialId":997950,"chapterSteps":46,"title":"トップカバーを取り付ける","description":"ベントが前を向くようトップカバーをプリンターのくぼみに合わせます。指定穴のナイロンリベット4本で固定してください。穴は8か所ありますが、この手順では4本を使います。","parts":["top","grille","ventBlock"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997950","checks":["ベントが前を向き、指定位置のリベット4本でトップカバーを固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/de9a9effe3e5eabf3ed81f1f40c7b6e6-800x600.jpg","reveal":["top","grille","ventBlock"],"add":["top","grille","ventBlock"],"view":"top","verificationRevision":"c30ef9d95dd209e3"},{"chapter":7,"officialStep":9,"officialId":997984,"chapterSteps":46,"title":"側面カバーの部品を準備する","description":"この手順で使用する部品・工具を用意してください。","parts":["windowLeft","windowRight"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#997984","checks":["部品表の種類と数量を確認し、必要な部品を用意した"],"supplies":["サイドカバー（2枚） — 「Plexi set」同梱","ナイロンリベット（10個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/fa06804400491eb9dcac80c9f8a7beec-800x600.jpg","reveal":["windowLeft","windowRight"],"add":[],"verificationRevision":"894826bbcb73ca16"},{"chapter":7,"officialStep":10,"officialId":998020,"chapterSteps":46,"title":"保護フィルムを剥がす","description":"側面カバー2枚とも、表と裏の保護フィルムをすべて剥がしてください。","parts":["windowLeft","windowRight"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998020","checks":["側面カバー2枚の両面からフィルムを剥がした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5d47b28d2f2916eb0a74e89ded434f7f-800x600.jpg","reveal":["windowLeft","windowRight"],"add":[],"verificationRevision":"7291d09f7bde7b42"},{"chapter":7,"officialStep":11,"officialId":998048,"chapterSteps":46,"title":"左側面を覆う","description":"左側面のくぼみにカバーを合わせ、突き出ているねじをカバーの大きい穴へ通します。指定の5か所へナイロンリベットを入れて固定してください。","parts":["windowLeft"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998048","checks":["突き出たねじが大きい穴に収まり、左カバーをリベット5本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7c93f18638ed97a1-800x600.jpg","reveal":["windowLeft"],"add":["windowLeft"],"verificationRevision":"dd163f7ad7e7db51"},{"chapter":7,"officialStep":12,"officialId":998086,"chapterSteps":46,"title":"右側面を覆う","description":"右側面のくぼみにカバーを合わせ、指定位置のナイロンリベット5本で固定してください。","parts":["windowRight"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998086","checks":["右カバーを指定位置のリベット5本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/5403f94af29bb483f585ab3c55e13e29-800x600.jpg","reveal":["windowRight"],"add":["windowRight"],"verificationRevision":"89f167df0c7cd04e"},{"chapter":7,"officialStep":13,"officialId":998114,"chapterSteps":46,"title":"xLCDの部品を準備する","description":"xLCD、フロントカバー、Display-mount、ノブ、3x8sTを4本、Faston端子を用意します。マウントは従来の3Dプリント製か、新しい射出成形品です。次の参考写真で版を見分け、以降は手元の版に合う指示に従ってください。","parts":["lcd"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998114","checks":["xLCD一式、3x8sTを4本、Faston端子を用意した"],"supplies":["xLCDユニット（1個） — 「Electronics」同梱","xLCDフロントカバー（1個） — 「Printed parts」同梱","xLCDディスプレイマウント（1個） — 「Printed parts」同梱","ノブ（1個） — 「Printed parts」同梱","3x8sTネジ（4本）","ファストン端子（1個） — 「Electronics」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/10772ade7c248f22642a90384d5923b8-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"334e1834b654bceb"},{"chapter":7,"officialStep":14,"officialId":1048724,"chapterSteps":46,"title":"新しいxLCDマウントを確認する","description":"手元のxLCDマウントを参考写真と見比べます。旧型の3Dプリント品は積層のある粗い表面、新型の射出成形品は滑らかな表面です。この後は、手元の型に合う注意事項に従ってください。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1048724","checks":["表面と写真を見比べ、手元のxLCDマウントの型を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/5f28c7a7bf73643ebf66aa2194b6bb0e-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"b03dca4ebcda0798"},{"chapter":7,"officialStep":15,"officialId":998180,"chapterSteps":46,"title":"xLCDを組み立てる①","description":"前カバーの表面を下にし、箱や机の端で支えてノブの軸を逃がします。xLCDの保護フィルムを剥がし、カバーへ入れてください。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998180","checks":["軸に荷重をかけずに支え、フィルムを剥がしたxLCDをカバーへ入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2bae360d23b369977a1a35e89942e007-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"08b44e19f02b3313"},{"chapter":7,"officialStep":16,"officialId":998218,"chapterSteps":46,"title":"xLCDを組み立てる②","description":"背面カバーを載せます。旧型のプリント品は角をxLCDへ掛け、新しい型はそのまま載せてください。指定の3か所だけを3x8sTで固定します。コネクターの長いスリットの隣にある4つ目の穴は、次の手順用に空けておきます。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998218","checks":["3x8sTの3本だけを使い、コネクター横の4つ目の穴を空けている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/92ddf043ca18fc4ba3819d4761840edc-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"961e9a9390668a6f"},{"chapter":7,"officialStep":17,"officialId":998264,"chapterSteps":46,"title":"FEファストン端子を取り付ける","description":"空けておいた4つ目の穴に、接地用Faston端子を合わせます。ラジオペンチで端子を保持し、3x8sTで固定してください。締めるときに端子が回って周囲の電子部品へ当たらないようにします。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998264","checks":["4つ目の穴へFastonを固定し、締めるときに端子を回していない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f31c61137e1157342fb91d360b35e357-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"a3f2cdfc63f8c24e"},{"chapter":7,"officialStep":18,"officialId":998310,"chapterSteps":46,"title":"LCDノブを取り付ける","description":"エンコーダー軸の平らな面を上へ向けます。射出成形ノブの小さなゲート跡も上に合わせ、軸へ差し込んでください。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998310","checks":["軸の平面とノブの小さな跡を上に合わせて取り付けた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a41a1556ad7866ce8bbf9c61bb3159c2-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"95bc9a928a47ebb6"},{"chapter":7,"officialStep":19,"officialId":998346,"chapterSteps":46,"title":"xLCDベゼルの部品を準備する","description":"xLCD、ベゼル、M3x6を2本用意します。プリント製ディスプレイマウントではM3nSも2個使います。新しい射出成形マウントには、このM3nSは不要です。","parts":["lcd"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998346","checks":["マウントの種類を確認し、必要なねじ・ナットを用意した"],"supplies":["xLCDユニット（1個） — 「Electronics」同梱","M3nSナット（2個）","M3x6ネジ（2本）","ベゼル（1個） — 「Metal parts 2/3」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/26de78855c460cfcd1366403d8b063d2-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"0bc5af3e2ce8dc9c"},{"chapter":7,"officialStep":20,"officialId":998396,"chapterSteps":46,"title":"xLCDを組み付ける①","description":"旧プリント製マウントはM3nSを2個、背面の穴の奥まで入れ、ネジ穴とそろえます。新しい射出成形マウントはナットを使わず、M3x6を直接樹脂へねじ込みます。この型で多少の抵抗があるのは正常です。どちらもM3x6を2本、仮止めし、ネジ頭の下に3 mm以上の隙間を残してください。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998396","checks":["マウントの種類に合う固定方法で、ネジ頭の下に3 mm以上ある"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/11b87c24dde5e0da05e89f73d05c7869-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"5cd5235e4c3dceea"},{"chapter":7,"officialStep":21,"officialId":998442,"chapterSteps":46,"title":"xLCDを組み付ける②","description":"xLCD一式のねじ頭をベゼルの鍵穴へ入れ、左右とも細い部分の奥までスライドさせます。ディスプレイが上を向き、ベゼルの折り曲げ縁が上にあることを確認してから、ねじを締めてください。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998442","checks":["左右のねじ頭が鍵穴の細い部分の奥に入り、画面と折り曲げ縁が上を向いている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3c1484c37ff507e4638e129db964eb92-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"7851d78599cd7c45"},{"chapter":7,"officialStep":22,"officialId":998504,"chapterSteps":46,"title":"xLCDユニットを取り付ける","description":"メインコネクターの赤い突起を、xLCD基板の三角マークに合わせて接続します。アース線のファストン端子も接続してください。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998504","checks":["赤い突起と三角マークの向きが合い、アース線も接続した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d8131a0b2cbf70396223a1ff7d4f2107-800x600.jpg","reveal":["lcd"],"add":["lcd"],"verificationRevision":"ae868069c9347b09"},{"chapter":7,"officialStep":23,"officialId":998558,"chapterSteps":46,"title":"xLCDユニットを固定する","description":"ケーブルを挟んだり抜いたりしないよう、xLCD一式を静かに起こします。ベゼル左の小さなタブを左の縦プロファイルの後ろへ掛けてください。底を少し持ち上げて余裕を作り、右のタブも右プロファイルへ掛けます。","parts":["lcd"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998558","checks":["配線を挟んだり抜いたりせず、ベゼルの左右のタブが掛かっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/603eb228b87f2a45442207a323ba7bab-800x600.jpg","reveal":["lcd"],"add":[],"verificationRevision":"b0b9f4e5798f6ecd"},{"chapter":7,"officialStep":24,"officialId":998648,"chapterSteps":46,"title":"ドアシールの部品を準備する","description":"長い側面用ドアシールを2本、短い上部用を1本用意します。保護フィルムの色は異なる場合があります。長さで使う位置を見分けてください。","parts":["door"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998648","checks":["長いシール2本と短いシール1本を見分けて用意した"],"supplies":["ドア側面のシール（2本） — 長い方。「Electronics & Fasteners」同梱","ドア上部のシール（1本） — 短い方。「Electronics & Fasteners」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3f7742fac09f4a1cb3cdb8e9cfb082aa-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"b64bd81bfea751b3"},{"chapter":7,"officialStep":25,"officialId":998690,"chapterSteps":46,"title":"上側のシールを貼る","description":"短い方のドアシールを使います。保護紙を少しずつ剥がしながら、フレーム上辺へ貼ってください。左右の角には、それぞれシールの厚さと同じ幅の隙間を残します。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998690","checks":["短いシールを上辺へ貼り、両端にシール厚と同じ隙間を残した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d11c5d367ad3f1d1dbe4a2fb316333aa-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"ff25bae6bf1de6a2"},{"chapter":7,"officialStep":26,"officialId":998752,"chapterSteps":46,"title":"側面のシールを貼る","description":"長いシールを、上のシールの端から下へ向けて貼ります。底部でLCDパネルに重なる余りをラジオペンチで切ってください。左辺にも同じように、残りの長いシールを貼ります。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998752","checks":["左右の長いシールを上から貼り、底部のLCDに重なる余りを切った"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8eda6e21425723135ceefbca2e2243b1-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"4e92cbd4dbe35965"},{"chapter":7,"officialStep":27,"officialId":998798,"chapterSteps":46,"title":"マグネットホルダーの部品を準備する","description":"20x6x2 mm磁石2個、マグネットホルダー2個、M3x5rTを2本、M3nSを2個用意します。磁石同士がぶつかると割れることがあるため、十分に離して置いてください。","parts":["door"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998798","checks":["部品表の部品を用意し、磁石2個を離して置いた"],"supplies":["M3x5rTネジ（2本）","M3nSナット（2個）","磁石 20x6x2（2個） — 「Electronics & Fasteners」同梱","マグネットホルダー（2個） — 「Printed parts」同梱"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9669ea96742c228f3e4cc9439fd8c893-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"70a1c72111385665"},{"chapter":7,"officialStep":28,"officialId":998856,"chapterSteps":46,"title":"マグネットホルダーを組み立てる","description":"ドア用のマグネットホルダーへM3nS角ナットを奥まで入れ、ねじ穴を合わせます。磁石もポケットの奥まで押してください。このドア用磁石の向きはどちらでも構いません。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998856","checks":["ドア用ホルダーのナットと磁石を奥まで入れ、ねじ穴が合っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/28fe2ddb188dc6ecabb9d53958a6906d-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"b7ec02dfe84c6bcc"},{"chapter":7,"officialStep":29,"officialId":998900,"chapterSteps":46,"title":"マグネットホルダーを取り付ける","description":"プリンター内側から、右プロファイル下部の開口へマグネットホルダーを入れます。突き出た四角い部分を切り欠きへ合わせ、M3x5rTで固定してください。上の開口にも同じように取り付けます。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998900","checks":["右の上下ホルダーの四角い部分を切り欠きへ合わせ、各M3x5rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3292dbc1985615072a6880f59227f62e-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"89cd6d9371180385"},{"chapter":7,"officialStep":30,"officialId":998946,"chapterSteps":46,"title":"ヒンジの部品を準備する","description":"内側ヒンジ2個、外側ヒンジ2個、2×40 mmのピン2本、M3x5rTネジ2本を用意します。","parts":["door"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998946","checks":["ヒンジ各2個、2×40 mmピン2本、M3x5rTネジ2本を用意した"],"supplies":["ドアヒンジの内側部品（Door-hinge-in）（2個） — 「CoreXY + Hinges set」同梱","ドアヒンジの外側部品（Door-hinge-out）（2個） — 「CoreXY + Hinges set」同梱","ヒンジピン 2 x 40 mm（2本） — 「Electronics & Fasteners」同梱","M3x5rTネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/b01712c92d6281d375880e35779c187b-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"aaf1c3b4e5c71751"},{"chapter":7,"officialStep":31,"officialId":998996,"chapterSteps":46,"title":"内側のヒンジを取り付ける","description":"内側から左プロファイル下部の四角穴へdoor-hinge-inを入れ、突き出た部分を前へ通します。M3x5rTで固定し、上側も同じように取り付けてください。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#998996","checks":["左の上下ヒンジ内側を、突起が前へ出る向きで各M3x5rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/770b1d4a7589bf893e9bc966cef3d38a-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"6042974143a2a8af"},{"chapter":7,"officialStep":32,"officialId":999034,"chapterSteps":46,"title":"外側のヒンジを取り付ける①","description":"外側ヒンジdoor-hinge-outを内側ヒンジへ合わせます。ピンの面取りされた端を先にして上から通し、奥まで入れてください。ラジオペンチの先で押し込んで固定します。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999034","checks":["面取り端を先に上からピンを通し、奥まで押し込んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0bcc6541b96e7d931c71446638b21b39-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"dc07d53b5cde2ccb"},{"chapter":7,"officialStep":33,"officialId":999080,"chapterSteps":46,"title":"外側のヒンジを取り付ける②","description":"下側の外側ヒンジも同じように取り付けます。上下のヒンジの溝をのぞき、ピンが溝の底面から出ていないことを確認してください。両方のヒンジを開きます。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999080","checks":["上下とも溝の底面からピンが出ておらず、両ヒンジを開いた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4feaaea1b40e84764b80d61742b69bff-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"2a60bac1a9965274"},{"chapter":7,"officialStep":34,"officialId":999118,"chapterSteps":46,"title":"ドアパネルの部品を準備する","description":"ドア、金属製のドアハンドル、M3x5rTを4本用意します。ドアの表示が「CORE ONE」でも正しい部品です。「+」デカールは最後の手順で確認します。すでに「+」が付いている場合は追加で貼る必要はありません。","parts":["door"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999118","checks":["ドア、金属ハンドル、M3x5rTを4本用意した"],"supplies":["ドア（1枚） — 「Plexi set」同梱","ドアハンドル（1個） — 「Metal parts 2/3」同梱","M3x5rTネジ（4本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3a0c6851f152197b7597e30e6656a455-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"94bd0132db2e75ad"},{"chapter":7,"officialStep":35,"officialId":1075170,"chapterSteps":46,"title":"新しいドア部品を確認する","description":"付属品にDoor handle plateとM3x8rTの2本があるか確認します。これらがあればネジ固定式の部品です。取り付けに進む前に、手元の部品に合う固定方式を確認してください。","parts":["door"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1075170","checks":["Door handle plateとM3x8rTの有無を確認した"],"supplies":["ドアハンドルの固定プレート（1枚）","M3x8rTネジ（2本）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/05/82c048c78fb2f07c9d29c317c63cdfc0-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"969f9770f1dcef70"},{"chapter":7,"officialStep":36,"officialId":999162,"chapterSteps":46,"title":"ドアの保護フィルムを剥がす","description":"ドア全面を覆う薄い透明フィルムを剥がします。反対側の中央を覆う白いフィルムは、今剥がしても、表面保護のため取り付け後まで残しても構いません。中央のフィルムはヒンジやハンドルの取り付けを妨げません。","parts":["door"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999162","checks":["全面のフィルムを剥がし、中央の白いフィルムを残すか確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ce4f2b58222d458e1f0ce616116b11ac-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"023092a7bdc5dab7"},{"chapter":7,"officialStep":37,"officialId":1075344,"chapterSteps":46,"title":"ドアハンドルの固定方式を選ぶ","description":"Door handle plateが付属していれば画面で「ネジ固定式」を選び、ハンドル取り付けへ進みます。プレートがなければ「接着式」を選んでください。先にドアパネルを取り付け、その後でハンドルを接着する順になります。","parts":["door"],"tip":"ネジ固定式と接着式では手順が分かれます。キットの部品に合う方式を選んでください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1075344","checks":["プレートの有無を確認し、付属部品に合う固定方式を画面で選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/05/68142ca349d30b80b4f6c7bd95d69ffb-800x600.jpg","reveal":["door"],"add":[],"chooseVariant":true,"verificationRevision":"e46ffb0a6e790b01"},{"chapter":7,"officialStep":38,"officialId":1075220,"chapterSteps":46,"title":"ハンドルを取り付ける〔ネジ固定〕","description":"ハンドルに粘着層がある型だけ、裏側から細いT6トルクスレンチを2か所のねじ穴へ1か所ずつ通し、両方の粘着層を開けます。新しい粘着層なしの型では、この作業は不要です。Prusaロゴを上にし、ハンドルとドアパネルの穴を合わせて差し込んでください。","parts":["door"],"tip":"ネジ固定式と接着式では手順が分かれます。キットの部品に合う方式を選んでください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1075220","checks":["必要な型だけ粘着層を開け、ロゴを上にしてハンドルとパネルの穴を合わせた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/05/1017a1227a943d8e270f9594f9f73285-800x600.jpg","reveal":["door"],"add":[],"variant":"screw","chooseVariant":true,"verificationRevision":"287fea81fb820c03"},{"chapter":7,"officialStep":39,"officialId":1075290,"chapterSteps":46,"title":"ハンドルを固定する〔ネジ固定〕","description":"ドアを立ててしっかり支え、ロゴのある外側で、パネルとハンドルの間へプレートを入れます。プレートのネジ支柱をパネルから離れる向きにし、パネルとハンドルの穴へそろえてください。M3x8rTを2本、軽く、確実に締めて固定します。この後の接着式ハンドルの手順は、ねじ固定したハンドルには適用しません。","parts":["door"],"tip":"ネジ固定式と接着式では手順が分かれます。キットの部品に合う方式を選んでください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1075290","checks":["プレートはロゴのある外側にあり、ネジ支柱がパネルから離れる向きで、M3x8rT 2本を軽く確実に締めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/05/df899d402c3d0cd07022d70069f39d5a-800x600.jpg","reveal":["door"],"add":[],"variant":"screw","chooseVariant":true,"verificationRevision":"007f9646e6a70a12"},{"chapter":7,"officialStep":40,"officialId":999206,"chapterSteps":46,"title":"ドアパネルを取り付ける","description":"ドアの表示を外向きにし、上下の切り欠きをヒンジの溝へ合わせて奥まで差し込みます。M3x5rTの4本を、上側から始めて下側の順に取り付け、ドアを固定してください。","parts":["door"],"tip":"ネジ固定式と接着式では手順が分かれます。キットの部品に合う方式を選んでください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999206","checks":["表示が外向きで上下とも奥まで入り、上から順にM3x5rTの4本で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/56755887b4792fbd4c389140df0826ce-800x600.jpg","reveal":["door"],"add":["door"],"chooseVariant":true,"verificationRevision":"470ab19f3d5f456c"},{"chapter":7,"officialStep":41,"officialId":999252,"chapterSteps":46,"title":"ハンドルを組み立てる〔接着〕","description":"接着式ハンドルだけの手順です。内側の粘着テープ2本から保護フィルムを剥がします。粘着面はドアの裏側へ付きますが、まだ貼らないでください。次の手順で位置を合わせます。","parts":["door"],"tip":"ネジ固定式と接着式では手順が分かれます。キットの部品に合う方式を選んでください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999252","checks":["接着式の粘着テープ2本のフィルムを剥がし、まだドアへ貼っていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4713a58cd996ff77661c78235fc7d3ce-800x600.jpg","reveal":["door"],"add":[],"variant":"glued","chooseVariant":true,"verificationRevision":"c67db529cba8a30f"},{"chapter":7,"officialStep":42,"officialId":999288,"chapterSteps":46,"title":"ハンドルを固定する〔接着〕","description":"接着式ハンドルの前側の面取り部をドアへ平らに当て、上端をドア上端とそろえます。位置を保って押し当てながら、公式写真の向きでゆっくり反時計回りに回して接着してください。粘着テープの位置でドアとハンドルをしっかり押し合わせます。","parts":["door"],"tip":"ネジ固定式と接着式では手順が分かれます。キットの部品に合う方式を選んでください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999288","checks":["面取り部と上端を合わせてから回して接着し、テープ2か所を押し合わせた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ca2441a72fefc30c5ab5f8ef7b45a173-800x600.jpg","reveal":["door"],"add":[],"variant":"glued","chooseVariant":true,"verificationRevision":"87cfd979dc9a6094"},{"chapter":7,"officialStep":43,"officialId":1014666,"chapterSteps":46,"title":"ステッカーを準備する","description":"まずドアの「CORE ONE」表示に「+」が付いているか確認します。付いている場合は、追加のステッカーは不要です。付いていない場合は、CORE One+ Upgrade箱のプラスステッカーを用意してください。","parts":["door"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1014666","checks":["ドアにプラスが付いていることを確認したか、貼り付け用ステッカーを用意した"],"supplies":["CORE One+ 透明パネル用ステッカー"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d3680d7edae42f034745110d6efbedb7-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"870570d035c50970"},{"chapter":7,"officialStep":44,"officialId":1014593,"chapterSteps":46,"title":"ステッカーを貼る","description":"すでに＋が付いているドアは、「ONE」との位置を確認して次へ進みます。未貼付の場合は、青い台紙から＋ステッカーを外し、「ONE」のロゴに合わせて軽く確実に押し付けてください。透明フィルムをゆっくり剥がし、＋がドアに残ることを確認します。","parts":["door"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#1014593","checks":["ドアの＋がONEにそろっていることを確認した。今回貼った場合は透明フィルムを剥がした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7f4c9a73802c60b4e8792c31d70d6045-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"f5676b1062742319"},{"chapter":7,"officialStep":45,"officialId":999326,"chapterSteps":46,"title":"ここでひと休み","description":"ここでひと休み。公式写真で案内されるグミの7列目が、この章のごほうびです。休憩せずに次へ進んでもかまいません。","parts":["door"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999326","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/16f53db6bb795887b09218629a7e83ac-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":7,"officialStep":46,"officialId":999360,"chapterSteps":46,"title":"ドア・xLCDを確認する","description":"本体の組み立てはここまでです。未確認の手順を見直し、最後の章で初回起動と校正を行います。プリントの前に、この設定を済ませてください。","parts":["door"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/8-trim-door-xlcd_982300#999360","checks":["この章の作業を終え、未確認の手順を見直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d4d84003c095ebbf236be35a5125cb6b-800x600.jpg","reveal":["door"],"add":[],"verificationRevision":"1244d7ec7442a18d"},{"chapter":8,"officialStep":1,"officialId":999385,"chapterSteps":18,"title":"ベルトの張りを調整する","description":"電源は切ったまま、テンショナーのM3x30ねじ2本が潤滑済みか確認します。NextruderをX中央・Y最前部へ動かし、ガントリー左右の角が前枠に当たり、がたつきがないことを確認してください。片側に隙間がある場合は両ねじを十分に緩め、ガントリーをレールの中ほどへ戻します。両端を持ち、傾きと逆向きへ慎重に力を加えて整え、前へ動かして左右の隙間を再確認します。ベルトやベアリングを傷めないよう、無理に力を加えないでください。整列を保ち、両ねじを交互に同じ量ずつ締めます。測定時はヘッドをX右端・Y最前部へ動かします。公式Belt TunerでCORE One → XY-beltを選び、Start listeningを押し、端末を近づけて前側の上下ベルトをそれぞれ中央で弾いて測ります。目安は上側98 Hz・下側92 Hzです。両方が90～98 Hzで差が8 Hz以内なら、下側が少し高くても構いません。左ねじは上側、右は下側に作用し、締めると周波数が上がり、緩めると下がります。両ねじを交互に同じ量ずつ、半回転ごとに調整・再測定します。前側の角に隙間ができたら両ねじを緩め、整列からやり直してください。初回電源投入前なので、実機のManual Belt Tuningはまだ使いません。","parts":["xy","gantry"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999385","checks":["M3x30の潤滑と、ガントリー左右の整列を確認した","マイクで上下ベルトを測定・調整し、張りと左右の整列を再確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/70400209b97f3e236b640fab06546599-800x600.jpg","reveal":["xy","gantry"],"add":[],"verificationRevision":"aea13a5ab4aeb996","references":[{"label":"ベルト張り調整の公式記事","url":"https://help.prusa3d.com/article/adjusting-belt-tension-core-one-core-one-indx-core-one-l_845048"},{"label":"ベルト測定ツール（Belt Tuner）","url":"https://belt.connect.prusa3d.com/"}]},{"chapter":8,"officialStep":2,"officialId":1014724,"chapterSteps":18,"title":"スプールホルダーの部品を準備する","description":"Spoolholder-staticとOリングを用意します。どちらも同じ袋に入っています。","parts":["sheet","spoolNew"],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#1014724","checks":["スプールホルダーとOリングを用意した"],"supplies":["Oリング","固定スプールホルダー（Spoolhoder-static）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/886a2be0d717353120a92b1c0dcaa300-800x600.jpg","reveal":["sheet","spoolNew"],"add":[],"verificationRevision":"e069cc380e2bcfe9"},{"chapter":8,"officialStep":3,"officialId":999427,"chapterSteps":18,"title":"シートとスプールホルダーを取り付ける","description":"清潔で何も載っていないヒートベッドに、シート後端の切り欠きを位置決めピンに合わせて載せます。前の両隅を持ち、指を挟まないように下ろしてください。ホルダーにOリングを付け、パックに押し込んで時計回りにロックします。シート表面を触った場合はIPAで脱脂します。","parts":["sheet","spoolNew"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999427","checks":["シートが清潔なヒートベッドのピンに合い、表面に油分がない","ホルダーにOリングを付け、パックにロックした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/fc0471bd87bcff5e52310a25ff6a1b99-800x600.jpg","reveal":["sheet","spoolNew"],"add":["sheet","spoolNew"],"verificationRevision":"773cea5fd4ef6efe"},{"chapter":8,"officialStep":4,"officialId":999963,"chapterSteps":18,"title":"ファームウェアを更新する","description":"公式サポートでCORE One+用のファームウェアを確認し、.bbfファイルを付属のUSBドライブに保存します。機種名を確認して選んでください。","parts":["electronics","lcd"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999963","checks":["CORE One+用の.bbfファイルを付属USBドライブに保存した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7122ba49b0f12fe7aa570bfa889f1eb2-800x600.jpg","reveal":["electronics","lcd"],"add":[],"verificationRevision":"5c96cfd2efe5c2f6"},{"chapter":8,"officialStep":5,"officialId":999469,"chapterSteps":18,"title":"プリンターの電源を入れる","description":"USBドライブをプリンターに挿し、電源ケーブルをつないで背面スイッチを入れます。「New firmware available」が出たら、ノブを押して「FLASH」を選んでください。更新が終わったら次へ進みます。更新の案内が出ない場合も次へ進めます。","parts":["electronics","lcd"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999469","checks":["電源を入れ、更新が案内された場合はFLASHを完了した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/330e90d0d24f294df8f5970c635d5c47-800x600.jpg","reveal":["electronics","lcd"],"add":[],"verificationRevision":"b58880a2d67256db"},{"chapter":8,"officialStep":6,"officialId":999539,"chapterSteps":18,"title":"初期設定を始める","description":"ノブまたはタッチ画面で言語を選び、ようこそ画面で「OK」を押します。モデル選択では、公式手順にある「COREONE」を選び、「Done」で進んでください。","parts":["electronics","lcd"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999539","checks":["言語とモデルを選び、初期設定を進めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e910498be7b86ce66fc26fc6128a7264-800x600.jpg","reveal":["electronics","lcd"],"add":[],"verificationRevision":"e1fdc81b745c22a3"},{"chapter":8,"officialStep":7,"officialId":999577,"chapterSteps":18,"title":"ネットワークを設定する","description":"ネットワーク設定は任意です。Prusa公式アプリでWi-Fiを設定するか、画面で「No」を選んで別の方法を使います。接続せずに進み、後から設定してもかまいません。","parts":["electronics","lcd"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999577","checks":["ネットワークを設定するか、後から設定するかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/08e3da0d4cf3a514261a28da6c6e03e1-800x600.jpg","reveal":["electronics","lcd"],"add":[],"verificationRevision":"2ce706257d79bce6"},{"chapter":8,"officialStep":8,"officialId":999620,"chapterSteps":18,"title":"セットアップウィザードを始める","description":"「YES」でセルフテストを開始し、画面の指示に従います。中では部品が加熱され、移動します。ドアは開けるように指示されるまで閉めておいてください。最初のファンテストでは大きな音が出ることがあります。","parts":["electronics","lcd"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999620","checks":["セルフテストを開始し、ドアを開けるタイミングは画面の指示に従っている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/db20a3a8d16bb2160bfa2f9d03e89d65-800x600.jpg","reveal":["electronics","lcd"],"add":[],"verificationRevision":"3c9a006c2e19d72f"},{"chapter":8,"officialStep":9,"officialId":999672,"chapterSteps":18,"title":"ドアセンサーを校正する","description":"「Calibrate」で開始し、画面の指示に従って、初期状態の緩い位置からセンサー調整ねじを少しずつ締めます。通常は1/2回転ずつです。調整のたびに前フレームの穴から出るスイッチを確認してください。手が入る程度の隙間で反応するまで指示に従って繰り返し、「Continue」で進みます。ドアの開閉時にクリック音がするか確認します。","parts":["head","sensorBody","door"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999672","checks":["調整のたびに穴から出るスイッチを確認し、手が入る程度のドアの隙間で反応するように調整した","ドアを開閉するとセンサーの位置からクリック音がする"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0e547227808b2a78fbc905b502617c6a-800x600.jpg","reveal":["head","sensorBody","door"],"add":[],"verificationRevision":"2bc9970c89d60a21"},{"chapter":8,"officialStep":10,"officialId":999726,"chapterSteps":18,"title":"ロードセルをテストする","description":"このロードセルテストでは加熱しません。ドアを開け、「Continue」で進み、「Tap nozzle NOW」が出るまでノズルには触れないでください。表示後に下から軽くたたきます。検出されなかった場合は、画面の再試行指示に従ってください。成功表示を確認し、ドアを閉めてウィザードを続けます。","parts":["head","sensorBody","door"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999726","checks":["指示が出てからノズルをたたき、ロードセルテストの成功を確認した","テスト後にドアを閉めた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6485190dab9b5c55bef0afce4043b08b-800x600.jpg","reveal":["head","sensorBody","door"],"add":[],"verificationRevision":"194286fb6f3e4837"},{"chapter":8,"officialStep":11,"officialId":999780,"chapterSteps":18,"title":"ギアボックスの位置を調整する","description":"「Gearbox Alignment」で「Continue」を選び、アイドラードアのロックを外します。ギアボックス前面のねじ3本を各1.5回転緩めてください。自動位置合わせは外からは見えません。完了後、画面に指示が出てから、表示された順番で3本を締め直します。","parts":["head","sensorBody","door"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999780","checks":["アイドラーのロックを外し、前面のねじ3本を各1.5回転緩めて自動位置合わせを行った","画面の指示後、指定の順番でねじ3本を締め直した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/f311854a3da1dafed6039b9b9a9c1761-800x600.jpg","reveal":["head","sensorBody","door"],"add":[],"verificationRevision":"349962cc59dab095"},{"chapter":8,"officialStep":12,"officialId":999833,"chapterSteps":18,"title":"フィラメントセンサーを校正する","description":"センサースイッチをONにし、校正開始前はエクストルーダーからフィラメントを抜いておきます。短いフィラメントを用意し、右側のホルダーにスプールを載せ、「Continue」で進みます。指示が出てから右ハンドル下のPTFEチューブへ挿し、校正後は抜いてください。","parts":["head","sensorBody","door"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999833","checks":["スイッチをONにし、フィラメントなしで校正を始めた","画面の指示に合わせて挿入し、校正後にフィラメントを抜いた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c2dcefab8a337075c4ad56dae7118a67-800x600.jpg","reveal":["head","sensorBody","door"],"add":[],"verificationRevision":"9cc2cd250c5511bc"},{"chapter":8,"officialStep":13,"officialId":999887,"chapterSteps":18,"title":"ウィザードを完了する","description":"ウィザードの結果を確認します。テストや校正に未解決のエラーが残っていないことを確認してから、初めてのプリントの準備へ進んでください。","parts":["head","sensorBody","door"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999887","checks":["ウィザードを完了し、未解決のテスト・校正エラーがない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7798e4301bf9fdc6211493fb05a659c6-800x600.jpg","reveal":["head","sensorBody","door"],"add":[],"verificationRevision":"e551e5dc4fa02977"},{"chapter":8,"officialStep":14,"officialId":999904,"chapterSteps":18,"title":"ここでひと休み","description":"残りのグミでひと休み。準備ができたら、ハンドブックの確認へ進みます。休憩せずに進んでもかまいません。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999904","checks":["休憩するか、そのまま次へ進むかを選んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d7903640a62828fada135ee0142648bf-800x600.jpg","reveal":[],"add":[],"verificationRevision":"ae3947de3fb402f9"},{"chapter":8,"officialStep":15,"officialId":999930,"chapterSteps":18,"title":"ハンドブックを確認する","description":"お使いの機種の3Dプリントハンドブックを開き、免責事項と安全上の注意を読んでください。初めてのプリントの準備も、ハンドブックに沿って進めます。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#999930","checks":["機種に合ったハンドブックの免責事項と安全上の注意を読んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c95fe7d117aeed70f7f4419d8e31f018-800x600.jpg","reveal":[],"add":[],"verificationRevision":"556aafcd984451a4"},{"chapter":8,"officialStep":16,"officialId":1039526,"chapterSteps":18,"title":"フィードバックを送るには","description":"マニュアルの分かりにくかった点や改善案は、公式手順のアンケートから送れます。回答は任意です。送信せずに次へ進んでもかまいません。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#1039526","checks":["任意のアンケートの案内を確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/01/75b0984ea5bfc07d94fe5bf91c3bb917-800x600.jpg","reveal":[],"add":[],"verificationRevision":"7758e04bfeab30b8"},{"chapter":8,"officialStep":17,"officialId":1000013,"chapterSteps":18,"title":"ナレッジベースの使い方","description":"組み立てや印刷で困ったときは、Prusa公式サポートのナレッジベースを確認できます。お使いの機種と症状に合った記事を選んでください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#1000013","checks":["困ったときに使う公式ナレッジベースを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/04/1e36a534c2945b48-800x600.jpg","reveal":[],"add":[],"verificationRevision":"57ee082c8bba07d0"},{"chapter":8,"officialStep":18,"officialId":1000039,"chapterSteps":18,"title":"Printablesコミュニティへ","description":"Printablesでは印刷用モデルを探せます。作品の紹介はPrusaブログ、組み立ての相談はフォーラムも利用できます。コミュニティへの登録やモデルの入手は、必要なときに行ってください。","parts":[],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/9-calibration-first-run_982308#1000039","checks":["モデルや相談先の案内を確認した。登録やモデルの入手は任意"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0c1b84f7664fc0708478af48867783ba-800x600.jpg","reveal":[],"add":[],"final":true,"verificationRevision":"343d96a64ebc8213"}]},"upgrade":{"title":"CORE One → CORE One+","guide":"アップグレードガイド","revision":"1.00","manual":"https://help.prusa3d.com/manual/prusa-core-one-to-core-one-upgrade_2338","chapters":["はじめに","プリンターのアップグレード","最終セットアップ"],"steps":[{"chapter":0,"officialStep":1,"officialId":1014808,"chapterSteps":6,"title":"アップグレードキットを準備する","description":"CORE One → CORE One+アップグレードキットを準備します。必要なプリントパーツはキットに含まれています。","parts":["sensorBody","spoolNew","ventLever"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_1014609#1014808","checks":["CORE One → CORE One+アップグレードキットを用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/02d2d52199cf0f51083795c37f638dc7-800x600.jpg","add":[],"remove":[],"reveal":[],"overview":true,"action":"アップグレードを開始","verificationRevision":"0a68f3dcb603e9e7"},{"chapter":0,"officialStep":2,"officialId":1014861,"chapterSteps":6,"title":"交換する箇所を確認する","description":"このアップグレードでは、フィラメントセンサー、スプールホルダー、チャンバーの自動ベントを変更します。最後にモデル表示とS/Nラベルを更新します。","parts":["sensorBody","spoolNew","ventLever"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_1014609#1014861","checks":["交換する3か所と、最後に貼る2種類のラベルを確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/07f783da30a6a3df4559dd5fa4416cfb-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"9d0607c63580c270"},{"chapter":0,"officialStep":3,"officialId":1014921,"chapterSteps":6,"title":"工具を準備する","description":"1.5 mmと2.5 mmの六角レンチ、T10トルクス、ラジオペンチ、M3ナット用の開口があるユニキーを用意します。工具はアップグレードキットに含まれないため、元のCORE Oneの工具を使ってください。ニッパーは任意です。","parts":[],"tip":"","kind":"prepare","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_1014609#1014921","checks":["必要な工具を用意した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/ec2231f4185b9738ec39094868ced840-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"bad4006e603ac2e6"},{"chapter":0,"officialStep":4,"officialId":1015017,"chapterSteps":6,"title":"フィラメントとスプールを外す","description":"電源を入れた状態で、メニューの「Filament → Unload filament」からフィラメントを抜きます。排出が終わったら、ホルダーからスプールを外してください。","parts":[],"tip":"フィラメントのアンロードとスプールの取り外しを、電源を切る前に行います。","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_1014609#1015017","checks":["フィラメントの排出が終わり、スプールを外した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/10/d9c6226e2cd6ecc8d0058a79b84e9082-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"0d767abf0db62906"},{"chapter":0,"officialStep":5,"officialId":1015049,"chapterSteps":6,"title":"ヒートベッドを下げる","description":"「Control → Move Axis → Move Z」でZを100 mm以上に設定します。ヒートベッドが下がり、停止するまで待ってください。","parts":["heatbed"],"tip":"公式手順ではZ位置を100 mm以上に下げてから、冷却と電源切断に進みます。","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_1014609#1015049","checks":["Zを100 mm以上に設定し、ヒートベッドが停止した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/01/c8f7e2b79deb7cff7d71384707c2810b-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"e7a0c592e683c521"},{"chapter":0,"officialStep":6,"officialId":1014977,"chapterSteps":6,"title":"冷却して電源を切る","description":"プリンターが室温まで冷めてから、背面スイッチで電源を切り、電源ケーブルを抜きます。プリントシートは、作業しやすいように取り外してもかまいません。","parts":["electronics"],"tip":"室温まで冷えたことを確認し、背面スイッチを切って電源コードを抜きます。","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/1-introduction_1014609#1014977","checks":["プリンターが冷めており、電源を切って電源ケーブルを抜いた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/0bfedcd9c8b4d649d081b9ea56759094-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"6a76abd70ef0a841"},{"chapter":1,"officialStep":1,"officialId":1023949,"chapterSteps":30,"title":"トップカバーを外す","description":"ドアを開け、左前のトップカバー用リベットを内側から押して解除し、外側から抜きます。残りのリベットも同様に外してから、カバーを持ち上げてください。","parts":["top","grille"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023949","checks":["リベットを解除してから外し、トップカバーを取り外した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/09/f5c8fe1860fd8a43-800x600.jpg","add":[],"remove":["top","grille"],"reveal":[],"view":"top","verificationRevision":"ab23a752caeb8c90"},{"chapter":1,"officialStep":2,"officialId":1022584,"chapterSteps":30,"title":"右ハンドルを外す","description":"右側面のハンドルのねじ2本をT10で外します。短いPTFEチューブを付けたままハンドルを外してください。チューブがプリンター側に残った場合は抜き取り、再利用のため保管します。","parts":["handleRight"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022584","checks":["右ハンドルを外し、短いPTFEチューブを保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/a560d63c10fcde86a0afcfa5f3283adb-800x600.jpg","add":[],"remove":["handleRight"],"reveal":[],"view":"right","verificationRevision":"26b74669e35cde93"},{"chapter":1,"officialStep":3,"officialId":1022634,"chapterSteps":30,"title":"右サイドパネルを外す","description":"右サイドパネルのナイロンリベット11個を外し、パネルを取り外します。リベットは切らずに外し、パネルを戻すときに再利用してください。","parts":["sideRight"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022634","checks":["右サイドパネルを外し、リベット11個を保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/cacfbd032520a4204e79fc89f0b623b3-800x600.jpg","add":[],"remove":["sideRight"],"reveal":[],"view":"right","verificationRevision":"a12353d603349db8"},{"chapter":1,"officialStep":4,"officialId":1022670,"chapterSteps":30,"title":"旧スプールホルダーを外す","description":"パネルの内側からM3x8rTを4本外し、旧スプールホルダーを取り外します。旧ホルダーは使いません。ねじ4本は、新しいパックの取り付けに使うため保管してください。","parts":["spoolOld"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022670","checks":["旧ホルダーを外し、M3x8rTを4本保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/04/d276712889a68c008db3e056f47eb641-800x600.jpg","add":[],"remove":["spoolOld"],"reveal":[],"view":"right","verificationRevision":"24d92f51b7b847da"},{"chapter":1,"officialStep":5,"officialId":1022696,"chapterSteps":30,"title":"新ホルダーの部品を準備する","description":"CORE Spool holderとPuck-universalを1個ずつ、Oリング25x3.5 mmを1個用意します。先ほど外したM3x8rTを4本、手元に置いてください。","parts":["puck","spoolNew"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022696","checks":["ホルダー、パック、Oリング、再利用するねじ4本を用意した"],"supplies":["CORE スプールホルダー（1個）","スプールホルダーの取付部品（Puck-universal）（1個）","Oリング 25x3,5mm（1個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/3b5e0aa4b1c81e1b4802659577732b65-800x600.jpg","add":[],"remove":[],"reveal":[],"view":"right","verificationRevision":"c3994b85d13b7e74"},{"chapter":1,"officialStep":6,"officialId":1022736,"chapterSteps":30,"title":"ユニバーサルパックを取り付ける","description":"パックをねじ穴が上になる向きで段ボール箱の上に置きます。右サイドパネルを重ねて4か所の穴を合わせ、M3x8rTを4本締めて固定してください。","parts":["puck"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022736","checks":["パックの4か所をM3x8rTで固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e53d787f51ee31584867478d98d8ce6b-800x600.jpg","add":["puck"],"remove":[],"reveal":[],"view":"right","verificationRevision":"a34b3ccc0cb2be10"},{"chapter":1,"officialStep":7,"officialId":1022776,"chapterSteps":30,"title":"新スプールホルダーを取り付ける","description":"Oリングをスプールホルダーの溝にはめます。ホルダーをパックに押し込み、ホルダー側から見て時計回りに回してロックしてください。","parts":["spoolNew"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022776","checks":["Oリングを入れ、ホルダーを回してロックした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6066ee4b6b47c58862a776c1feaaab1e-800x600.jpg","add":["spoolNew"],"remove":[],"reveal":[],"view":"right","verificationRevision":"1a7c124b1bf335f6"},{"chapter":1,"officialStep":8,"officialId":1022852,"chapterSteps":30,"title":"旧センサーとIR基板を取り外す","description":"2.5mm六角レンチで、公式写真に示されたM3x10固定ねじを外します。旧型センサーの場合は側面のM3x10だけを外してください。続いて1.5mm六角レンチで基板を留めるM2x8を外します。静電気に弱いIR基板は端だけを持ち、ケーブルを接続したまま横へ抜いて、作業の邪魔にならない位置に置きます。","parts":["sensorOld"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022852","checks":["センサーの型に合わせ、公式写真で示されたM3x10固定ねじを外した","IR基板を配線につないだまま、作業部からよけた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/d8b0b5ed58d9798dfeef50a114935986-800x600.jpg","add":[],"remove":["sensorOld"],"reveal":[],"view":"right","verificationRevision":"7a7e96acd2fc779e"},{"chapter":1,"officialStep":9,"officialId":1022910,"chapterSteps":30,"title":"チューブ・コレットを外す","description":"コレットを押し込んだままPTFEチューブを抜き、旧センサーをチューブから外します。コレットは抜き取って保管してください。初期型で入口側にも短いチューブとコレットがある場合は、その2点も外します。","parts":["sensorOld"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022910","checks":["旧センサーからチューブを外し、コレットを保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/7762044446c7f3b7f99aa96719b12b81-800x600.jpg","add":[],"remove":[],"reveal":[],"previewParts":["sensorOld"],"view":"right","verificationRevision":"b30cc436f37311e9"},{"chapter":1,"officialStep":10,"officialId":1022950,"chapterSteps":30,"title":"ボディから磁石を取り出す","description":"旧センサーボディに埋め込まれた磁石を、ラジオペンチで慎重に取り出します。この磁石は新しいセンサーで使うため、紛失しないように保管してください。","parts":["sensorOld"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022950","checks":["ボディ側の磁石を取り出し、保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/c062df820bb296bd8f9600f434917466-800x600.jpg","add":[],"remove":[],"reveal":[],"previewParts":["sensorOld"],"view":"right","verificationRevision":"8a907412aaa597a7"},{"chapter":1,"officialStep":11,"officialId":1022982,"chapterSteps":30,"title":"レバー・ボール・磁石を外す","description":"M3x10を外して旧レバーを取り出します。中の7 mmスチールボールとレバーの磁石を取り出し、M3x10と一緒に保管してください。3点とも再利用します。","parts":["sensorOld"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1022982","checks":["7 mmボール、レバーの磁石、M3x10を保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/02/e6b38290fe1d94aa43afb8d2d8b88a7a-800x600.jpg","add":[],"remove":[],"reveal":[],"previewParts":["sensorOld"],"view":"right","verificationRevision":"6be35adcf4896e4c"},{"chapter":1,"officialStep":12,"officialId":1023033,"chapterSteps":30,"title":"新センサーの部品を準備する","description":"新しいセンサーボディ、レバー、スイッチを1個ずつと、M3ワッシャーを用意します。旧センサーから取り出した10x6x2 mm磁石2個、7 mmボール、M3x10を再利用します。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023033","checks":["新しい3部品とワッシャー、再利用する磁石2個・ボール・ねじを用意した"],"supplies":["フィラメントセンサー本体（Filament-sensor-body）（1個）","フィラメントセンサーレバー（Filament-sensor-lever）（1個）","フィラメントセンサースイッチ（Filament-sensor-switch）（1個）","M3x10ネジ（1本） — プリンターから取り外したものを再使用","磁石 10x6x2mm（2個） — プリンターから取り外したものを再使用","ボール 7mm（1個） — プリンターから取り外したものを再使用","M3wワッシャー（1枚）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/da76be23af01b7a116b349c639dd912b-800x600.jpg","add":[],"remove":[],"reveal":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"view":"right","verificationRevision":"2a9011ef960f08e7"},{"chapter":1,"officialStep":13,"officialId":1023121,"chapterSteps":30,"title":"センサーベースを組み立てる","description":"磁石1個をレバーに入れ、ボールをベース内側のくぼみに入れます。レバーの磁石がボールの横に来る向きで組み込み、上からワッシャーとM3x10で留めます。レバーが動く締め具合にしてください。","parts":["sensorBody","sensorLever"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023121","checks":["ボールと磁石が所定の位置にあり、ねじ頭の下にワッシャーを入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/4078daa4c0e22ba2895c7f7c21cb92f1-800x600.jpg","add":[],"remove":[],"reveal":[],"view":"right","verificationRevision":"9adb68748b5a57c2"},{"chapter":1,"officialStep":14,"officialId":1023169,"chapterSteps":30,"title":"レバーの動きを確認する","description":"レバーを指で動かし、引っ掛かりなく動くか確認します。動きが固い場合は中央のM3x10を1/4回転緩め、もう一度確認してください。","parts":["sensorLever"],"tip":"レバーが引っかからずに戻ることを確認します。締め付けの調整は公式の同じ手順を参照してください。","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023169","checks":["レバーが引っ掛からずに動く"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d42c382826941446fdf824dd7060dd54-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"6bef57eb987c5d7e"},{"chapter":1,"officialStep":15,"officialId":1023193,"chapterSteps":30,"title":"スイッチを組み付ける","description":"残りの磁石をスイッチに入れ、ボディに組み込んで左端まで動かします。向かい合う磁石が反発することを確認してください。引き合う場合は、細い六角レンチでスイッチの磁石を押し出して裏返し、再確認します。","parts":["sensorSwitch","sensorLever"],"tip":"2つの磁石が反発する向きかを確認します。極性の確認方法は公式手順を参照してください。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023193","checks":["スイッチを左端にしたとき、2個の磁石が反発する"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/2680334660edee75832c3ddeff7d1679-800x600.jpg","add":[],"remove":[],"reveal":[],"verificationRevision":"cda5442e89ab61f3"},{"chapter":1,"officialStep":16,"officialId":1023249,"chapterSteps":30,"title":"センサーの接続を確認する","description":"この機種のIRセンサーは、茶色の線を+5V、白い線をGNDに接続します。一般的な配線色と思い込まず、基板のピン表示と照合してください。","parts":["electronics"],"tip":"この機種の配線色には注意が必要です。接続は公式手順のピン表示と写真で照合してください。","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023249","checks":["茶色は+5V、白はGNDに接続されている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/02/8832eba355e3f10c89dc60ff1c477711-800x600.jpg","add":[],"remove":[],"reveal":[],"view":"right","verificationRevision":"b871370015442a5d"},{"chapter":1,"officialStep":17,"officialId":1023289,"chapterSteps":30,"title":"IRセンサーを取り付ける","description":"先にケーブルを溝へ入れ、コネクターをセンサーベースの中央付近に置きます。IR基板を専用の溝に入れ、レバーがセンサーの光学ゲート内に収まるよう合わせてください。コネクターもケーブルもレバーに触れないことを確認し、1.5 mm六角レンチでM2x8を締めて基板を固定します。","parts":["sensorBody"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023289","checks":["ケーブルが溝に入り、コネクターがベースの中央付近にある","IR基板をM2x8で固定し、光学ゲート内のレバーに配線やコネクターが触れていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8d367f5e0403c08817fffa9afaac4e2f-800x600.jpg","add":[],"remove":[],"reveal":[],"view":"right","verificationRevision":"f636c2cfa851e9b0"},{"chapter":1,"officialStep":18,"officialId":1023337,"chapterSteps":30,"title":"センサーカバーを取り付ける","description":"M3nSナット2個を1.5 mm六角レンチで奥まで押し込み、横から穴の位置を確認します。カバーをM3x8で2か所固定してください。中央のねじは締め込まないでください。締めるとセンサーが動かなくなることがあります。","parts":["sensorCover"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023337","checks":["ナット2個の穴が合い、カバーをM3x8で2か所固定した","中央のねじを締め込まず、レバーの動きを保った"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/441e124badf12084ad39cf263ee1b215-800x600.jpg","add":[],"remove":[],"reveal":[],"view":"right","verificationRevision":"8c3e9d85e42d1349"},{"chapter":1,"officialStep":19,"officialId":1023377,"chapterSteps":30,"title":"センサーを取り付ける","description":"保管しておいたコレットを新しいセンサーに取り付けます。プリンター側のPTFEチューブを、センサーのコレットに奥まで差し込んでください。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023377","checks":["コレットが入り、PTFEチューブが奥まで差し込まれている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/0d0a924ffeb082fa71413524f9184645-800x600.jpg","add":["sensorBody","sensorLever","sensorSwitch","sensorCover"],"remove":[],"reveal":[],"view":"right","verificationRevision":"a0f78025b2cd6d30"},{"chapter":1,"officialStep":20,"officialId":1023411,"chapterSteps":30,"title":"側面ハンドルを準備する","description":"ハンドルの短いPTFEチューブを、ハンドルとコレットの中へ押し通して抜きます。コレットのない初期型ハンドルの場合は、最新版のプリントパーツに交換してください。ハンドルにM3x10rTを2本入れます。","parts":["handleRight"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023411","checks":["コレット付きハンドルから短いチューブを外し、M3x10rTを2本入れた"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/10/ee990ed15a106e6e389e5627ac23bada-800x600.jpg","add":[],"remove":[],"reveal":[],"view":"right","verificationRevision":"4f430e7bc3f66152"},{"chapter":1,"officialStep":21,"officialId":1023587,"chapterSteps":30,"title":"センサーとハンドルを固定する","description":"サイドパネルをプリンターの横に置き、ハンドルのねじ穴とPTFE用の大きな穴を合わせます。内側からセンサーのナットとねじの軸をまっすぐ合わせ、M3x10rTを2本締めて固定してください。","parts":["sensorBody","sensorLever","sensorSwitch","sensorCover","handleRight"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023587","checks":["PTFEの開口が大きな穴に合い、ねじ2本が斜めに入らず固定されている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/098235eb585affc3ef2ec42f488c49e3-800x600.jpg","add":["handleRight"],"remove":[],"reveal":[],"view":"right","verificationRevision":"993c96242a6c11f6"},{"chapter":1,"officialStep":22,"officialId":1023656,"chapterSteps":30,"title":"サイドパネルを戻す","description":"センサーとPTFEチューブを傷めないようにサイドパネルを戻し、ナイロンリベット11個で固定します。短いPTFEチューブをハンドルのコレットに奥まで差し込んでください。","parts":["sideRight"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1023656","checks":["パネルをリベット11個で固定し、短いPTFEチューブを奥まで差し込んだ"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/8191a4134eed15fe3a2894836b369fdb-800x600.jpg","add":["sideRight"],"remove":[],"reveal":[],"view":"right","verificationRevision":"979655d1b973463c"},{"chapter":1,"officialStep":23,"officialId":1024998,"chapterSteps":30,"title":"ベントレバーの部品を準備する","description":"新しいプリントパーツ「Cover Right Lever」を1個用意します。次の手順でプリントヘッド右側のカバーと交換します。","parts":["ventLever"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024998","checks":["Cover Right Leverを用意した"],"supplies":["レバー付き右カバー（Cover Right Lever）（1個）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/565de2935169615da55bdb7615d927eb-800x600.jpg","add":[],"remove":[],"reveal":["ventLever"],"verificationRevision":"7ee114f049394508"},{"chapter":1,"officialStep":24,"officialId":1024964,"chapterSteps":30,"title":"ベントレバーを取り付ける","description":"プリントヘッド右側のM3x6を2本外し、元のカバーを取り外します。Cover Right Leverに交換し、外したM3x6を2本使って固定してください。","parts":["coverOld","ventLever"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024964","checks":["Cover Right Leverを元のM3x6で2か所固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/e0dd25274e0746479d58fcc7bd95e51e-800x600.jpg","add":["ventLever"],"remove":["coverOld"],"reveal":[],"verificationRevision":"996b78547aed1547"},{"chapter":1,"officialStep":25,"officialId":1024023,"chapterSteps":30,"title":"トップカバーを分解する","description":"取り外したトップカバーの裏側でM3nNナットをペンチで押さえ、上側のM3x10rTを3本外します。断熱インサート2個を抜き取り、ねじ・ナットと一緒に保管してください。","parts":["top","grille"],"tip":"","kind":"remove","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024023","checks":["ねじ3本、ナット、断熱インサート2個を外して保管した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/a20ff09457ceeb0779e63fb1d5cb35ff-800x600.jpg","add":[],"remove":[],"reveal":[],"previewParts":["top","grille"],"view":"top","verificationRevision":"f09988782830e565"},{"chapter":1,"officialStep":26,"officialId":1024071,"chapterSteps":30,"title":"ベントブロックの部品を準備する","description":"Upg-vent-block、M3x12rTを2本、先ほど外した断熱インサート2個を用意します。右側には元のM3x10rTを再利用するので、ねじの長さを分けておいてください。","parts":["ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024071","checks":["ブロック、12 mmねじ2本、インサート2個、再利用する10 mmねじを用意した"],"supplies":["ベントブロック（Upg-vent-block）","M3x12rTネジ（2本）","絶縁インサート（2個） — 取り外しておいたものを再使用"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/50a76b8849738d8a64b10bfd2a464172-800x600.jpg","add":[],"remove":[],"reveal":["ventBlock"],"previewParts":["top","grille"],"view":"top","verificationRevision":"7872c3cb0fa84bb6"},{"chapter":1,"officialStep":27,"officialId":1024113,"chapterSteps":30,"title":"トップカバーを仮合わせする","description":"トップカバーは左右対称ではありません。元の取り付け向きを保ち、くぼみに合わせて重ねます。四隅のボルト頭が切り欠きに収まっているか確認してください。","parts":["top"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024113","checks":["カバーの向きが合い、四隅のボルト頭が切り欠きに収まっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/dbe2019b7162b122886d66df364f755a-800x600.jpg","add":[],"remove":[],"reveal":["ventBlock"],"previewParts":["top","grille"],"view":"top","verificationRevision":"f4f3a574c7bdc3ba"},{"chapter":1,"officialStep":28,"officialId":1024147,"chapterSteps":30,"title":"トップカバーを組み立てる①","description":"長いM3x12rTを2本用意し、絶縁インサートのつばをねじ頭に向けて通します。この2本はベントの中央と左の長穴へ入れ、右には取り外したM3x10rTを戻してください。公式写真と同じ向きで、ねじ穴が長方形の開口の左側にそろうようベントカバーを合わせます。","parts":["top","grille"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024147","checks":["中央と左は12 mm、右は元の10 mmのネジを使用した","インサートのつばはねじ頭側にあり、カバーのねじ穴は長方形の開口の左側にそろっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/90f6c960bb01c7e09f2db7901802f604-800x600.jpg","add":[],"remove":[],"reveal":["ventBlock"],"previewParts":["top","grille"],"view":"top","verificationRevision":"2e2be653f7c5f506"},{"chapter":1,"officialStep":29,"officialId":1047357,"chapterSteps":30,"title":"トップカバーを組み立てる②","description":"ベントカバーは左右非対称です。公式写真と同じ向きで合わせ、左へ動かすと開き、右へ動かすと閉じることを確認します。まず右端のM3nNを手で軽く留め、本締めしないでください。Upg-vent-blockのレバーをプリンター内側へ向け、開いた通気口に重ならない位置で、残る2個のM3nNで固定します。ペンチまたはユニバーサルレンチでナットを保持し、がたつきがなくなる分だけ締め、カバーが滑らかに動く余裕を残します。","parts":["ventBlock","grille"],"tip":"ベントが開閉できる締め方と、ブロックが開口をふさがない向きを公式写真で確認します。","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1047357","checks":["カバーは写真の向きにあり、左で開・右で閉になり、内側へ向けたブロックが開いた通気口を覆わない","ねじはがたつきがなくなる分だけ締め、ベントが滑らかに開閉する"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/a296e8cd276137c3-800x600.jpg","add":[],"remove":[],"reveal":["ventBlock"],"previewParts":["top","grille"],"view":"top","verificationRevision":"43f30d04fc07b57e"},{"chapter":1,"officialStep":30,"officialId":1024238,"chapterSteps":30,"title":"トップカバーを戻す","description":"3本のねじのいずれかを手で動かし、ベントが軽く全開・全閉に動くか確認します。固い場合は動きを妨げるねじを少し緩めてください。ベントを前に向けてカバーを戻し、指定位置のナイロンリベット4個で固定します。","parts":["top","grille","ventBlock"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/2-printer-upgrade_1014628#1024238","checks":["ベントが軽く全開・全閉に動き、前向きのカバーをリベット4個で固定した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2026/03/98db2422bc898cf31fa1fefb87aa07a8-800x600.jpg","add":["top","grille","ventBlock"],"remove":[],"reveal":["ventBlock"],"view":"top","verificationRevision":"88f11e943128708b"},{"chapter":2,"officialStep":1,"officialId":1023893,"chapterSteps":10,"title":"ステッカーを準備する","description":"CORE One+の「+」ステッカーと、新しいS/Nラベルを1枚ずつ用意します。S/Nラベルは、この後プリンター背面のラベルと交換します。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1023893","checks":["「+」ステッカーと新しいS/Nラベルを用意した"],"supplies":["CORE One+ 透明パネル用ステッカー（1枚）","CORE One+ シリアル番号ステッカー（1枚）"],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/9ef2ee9690b13b556caa25a346e3f6f9-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"661e3249f8718aa6"},{"chapter":2,"officialStep":2,"officialId":1023917,"chapterSteps":10,"title":"プラスのステッカーを貼る","description":"ステッカーを台紙から剥がします。「ONE」の表示に「+」ステッカーの位置を合わせ、押し付けて貼ります。透明の転写フィルムだけをゆっくり剥がし、「+」が本体側に残っていることを確認してください。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"install","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1023917","checks":["「+」が正しい位置に残り、透明フィルムを剥がした"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/d4b3a5c87bce10a969ed55ffa2f81ba6-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"564755d9e39896fc"},{"chapter":2,"officialStep":3,"officialId":1024303,"chapterSteps":10,"title":"S/Nラベルを更新する","description":"プリンター背面の旧S/Nラベルを、新しいCORE One+のS/Nラベルに交換します。キットに入っている新しいラベルを捨てないでください。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024303","checks":["背面のS/NラベルをCORE One+用に交換した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/b365e1575aabad3fcb9a95d76475306d-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"108172a9b0743fc3"},{"chapter":2,"officialStep":4,"officialId":1024943,"chapterSteps":10,"title":"プリントシートを確認する","description":"ヒートベッドが清潔で、物がないことを確認します。シート後端の切り欠きを位置決めピンに合わせ、前の両隅を持って指を挟まないように下ろしてください。表面に油分を付けず、手で触れた場合はIPAで清掃します。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024943","checks":["清潔なヒートベッドにシートを合わせ、シート表面に油分がない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/6813d90079ad747a1822a9048ad5b028-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"cf7fd65879538980"},{"chapter":2,"officialStep":5,"officialId":1024706,"chapterSteps":10,"title":"センサースイッチを確認する","description":"側面のフィラメントセンサースイッチをONにします。「X」の窓からオレンジ色が見えている状態はOFFです。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024706","checks":["センサースイッチがONで、Xの窓にオレンジ色が見えていない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e5aa9a9b7d89f2442e3ed71a9d2587f3-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"view":"right","verificationRevision":"068e0c6e4a529790"},{"chapter":2,"officialStep":6,"officialId":1024605,"chapterSteps":10,"title":"ファームウェアを入手する","description":"公式サポートからCORE One+用のファームウェアを入手し、.bbfファイルをUSBドライブに保存します。このアップグレード手順の指定は6.4.0以降です。機種名を確認して選んでください。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024605","checks":["CORE One+用の6.4.0以降の.bbfファイルをUSBに保存した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/9d72a45e1d0f0052-800x571.png","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"b1fc4a7af2a1dc95"},{"chapter":2,"officialStep":7,"officialId":1024647,"chapterSteps":10,"title":"ファームウェアを適用する","description":"ファームウェア入りのUSBドライブを挿し、電源ケーブルを接続して背面スイッチを入れます。「New firmware available」が表示されたら「FLASH」を選び、更新が完了してから次へ進んでください。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024647","checks":["USBからファームウェアを書き込み、更新が完了した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/e72ff2ea28893c858c03928540485d24-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"74c9943d591c91eb"},{"chapter":2,"officialStep":8,"officialId":1024902,"chapterSteps":10,"title":"セルフテストを行う","description":"「Control → Calibrations & Tests → Selftest」からセルフテストを最初から実行し、画面の指示に従います。テスト中は中の部品が加熱され、動きます。ドアは開けるように指示されるまで閉めておいてください。結果に未解決のエラーがある場合は、この手順を完了にせず公式手順で確認します。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"check","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024902","checks":["セルフテストを最初から実行し、未解決のエラーがない"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/10/07a6ddab377c18651441c585c8282ba0-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"238b7cf9c5b1f409"},{"chapter":2,"officialStep":9,"officialId":1024688,"chapterSteps":10,"title":"チャンバーベントを設定する","description":"「Settings → Hardware → Chamber Vent Control」を開き、「Auto」を選びます。チャンバーベントが自動制御に設定されているか確認してください。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024688","checks":["Chamber Vent ControlがAutoになっている"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/11/01f284897d24d50cb38adf16993fe2c3-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"verificationRevision":"d47b0bc3f57bfedf"},{"chapter":2,"officialStep":10,"officialId":1024919,"chapterSteps":10,"title":"アップグレードの最終確認","description":"アップグレードの最終確認です。取り付け、ファームウェア、セルフテスト、ベントのAuto設定まで終わっているか確認してください。工程一覧に未確認の手順が残っている場合は、その手順に戻ります。","parts":["lcd","sensorBody","ventBlock"],"tip":"","kind":"info","time":1,"tools":[],"source":"https://help.prusa3d.com/guide/3-final-setup_1014620#1024919","checks":["取り付けと最終設定を終え、残りの未確認手順も確認した"],"supplies":[],"photo":"https://help.prusa3d.com/wp-content/uploads/2025/12/23f03c634047117dcb4b0f78eb3b709b-800x600.jpg","add":[],"remove":[],"reveal":[],"fullContext":true,"final":true,"verificationRevision":"6f2569c3e4cd32b0"}]}};
